    /// <summary>Generated from strings.tsv and lang/*.tsv by make_langdata.py: English text → each language.</summary>
    static class LangData
    {
        public static readonly string[] Codes = { "ar", "zh", "de", "es", "fr", "ja", "pt", "ru" };

        /// <summary>The translations for a language code, or null for English (or a code there are none for).</summary>
        public static Dictionary<string, string> For(string code)
        {
            switch (code)
            {
                case "ar": return Arabic();
                case "zh": return Chinese();
                case "de": return De();
                case "es": return Es();
                case "fr": return Fr();
                case "ja": return Ja();
                case "pt": return Pt();
                case "ru": return Ru();
                default: return null;
            }
        }

