                { "Includes borderless games", "يشمل الألعاب بلا إطار" },
                { "Keep minimized sources playing", "إبقاء المصادر المصغّرة قيد التشغيل" },
                { "The PiP keeps moving when you minimize", "تستمر النافذة العائمة بالحركة عند التصغير" },
                { "Reconnect when a closed app opens again", "إعادة الاتصال عند فتح التطبيق المغلق مجددًا" },
                { "Window sources always run at full speed", "مصادر النوافذ تعمل دائمًا بأقصى سرعة" },
                { "Frame rate", "معدل الإطارات" },
                { "Show the pointer", "إظهار المؤشر" },
                { "Use game controllers", "استخدام وحدات تحكم الألعاب" },
                { "Xbox, PlayStation, Switch and most others", "Xbox وPlayStation وSwitch ومعظم الأنواع الأخرى" },
                { "Turn controls on when PiP Studio starts", "تشغيل التحكم عند بدء PiP Studio" },
                { "Release the game's focus while controls are on", "تحرير تركيز اللعبة أثناء تشغيل التحكم" },
                { "The game ignores the controller while you move the PiP, and gets focus back afterwards", "تتجاهل اللعبة وحدة التحكم أثناء تحريكك للنافذة العائمة، وتستعيد التركيز بعد ذلك" },
                { "The game ignores the controller meanwhile", "تتجاهل اللعبة وحدة التحكم في هذه الأثناء" },
                { "Show button hints on the PiP", "إظهار تلميحات الأزرار على النافذة العائمة" },
                { "Controller-friendly mode", "وضع ملائم لوحدة التحكم" },
                { "Bigger layout and button hints", "تخطيط أكبر وتلميحات للأزرار" },
                { "Bigger layout, a focus ring and button hints, so you can use this window with a controller. Pressing a key on the keyboard switches back.", "تخطيط أكبر وحلقة تركيز وتلميحات للأزرار حتى تستخدم هذه النافذة بوحدة التحكم. الضغط على أي مفتاح في لوحة المفاتيح يعيدها كما كانت." },
                { "When I use a controller", "عندما أستخدم وحدة تحكم" },
                { "Always", "دائمًا" },
                { "Off", "إيقاف" },
                { "Fade controller hints when idle", "إخفاء تلميحات وحدة التحكم عند الخمول" },
                { "Hints fade after a few seconds", "تتلاشى التلميحات بعد بضع ثوانٍ" },
                { "The PiP's name and button hints fade after a few seconds without input. Any button brings them back. Less for Windows to draw over your game.", "يتلاشى اسم النافذة العائمة وتلميحات الأزرار بعد بضع ثوانٍ دون إدخال. أي زر يعيدها. فيقل ما يرسمه Windows فوق لعبتك." },
                { "Controller options", "خيارات وحدة التحكم" },
                { "Button assignments", "تعيين الأزرار" },
                { "Click, then press a button. Right-click clears it.", "انقر ثم اضغط زرًا. النقر بالزر الأيمن يمسحه." },
                { "Click a binding, then press the button or combination. Right-click clears it. Trigger: press, double press or hold.", "انقر على أحد التعيينات ثم اضغط الزر أو المجموعة. النقر بالزر الأيمن يمسحه. طريقة التشغيل: ضغطة أو ضغطتان أو ضغط مطوّل." },
                { "Click, then press the button(s). Right-click to clear.", "انقر ثم اضغط الزر (أو الأزرار). انقر بالزر الأيمن للمسح." },
                { "Press once, press twice quickly, or hold", "اضغط مرة، أو مرتين بسرعة، أو اضغط مطولًا" },
                { "Press", "ضغطة" },
                { "Double press", "ضغطتان" },
                { "Hold", "ضغط مطوّل" },
                { "Reset", "إعادة تعيين" },
                { "Connect a controller", "وصّل وحدة تحكم" },
                { "Press button(s)…", "اضغط الزر (أو الأزرار)…" },
                { "No controller connected", "لا توجد وحدة تحكم موصولة" },
                { "No controller found", "لم يُعثر على وحدة تحكم" },
                { "Connect an Xbox, PlayStation or Switch controller by USB or Bluetooth.", "وصّل وحدة تحكم Xbox أو PlayStation أو Switch عبر USB أو Bluetooth." },
                { "Connect an Xbox, PlayStation or Switch controller to use controller controls.", "وصّل وحدة تحكم Xbox أو PlayStation أو Switch لاستخدام التحكم بها." },
                { "Controls are on — the PiP has an accent outline. {0} turns them off.", "التحكم مفعّل — للنافذة العائمة إطار ملوّن. {0} يوقفه." },
                { "Press {0} to turn controls on.", "اضغط {0} لتشغيل التحكم." },
                { "Controller controls", "التحكم بوحدة التحكم" },
                { "Controller controls on · {0} turns them off", "التحكم بوحدة التحكم مفعّل · {0} يوقفه" },
                { "Controller controls off", "التحكم بوحدة التحكم متوقف" },
                { "Controller controls ({0})", "التحكم بوحدة التحكم ({0})" },
                { "Xbox controller", "وحدة تحكم Xbox" },
                { "PlayStation controller", "وحدة تحكم PlayStation" },
                { "Switch controller", "وحدة تحكم Switch" },
                { "These work anywhere in Windows. Click a shortcut, then press the new keys (Backspace clears, Esc cancels). Right-click clears it. They act on the PiP you used or pointed at most recently.", "تعمل هذه في أي مكان في Windows. انقر على اختصار ثم اضغط المفاتيح الجديدة (Backspace يمسح وEsc يلغي). النقر بالزر الأيمن يمسحه. تعمل على آخر نافذة عائمة استخدمتها أو أشرت إليها." },
                { "Open and choose", "الفتح والاختيار" },
                { "Move and size", "التحريك والحجم" },
                { "Look and visibility", "الشكل والظهور" },
                { "Source and media", "المصدر والوسائط" },
                { "Click, then press keys. Right-click to clear.", "انقر ثم اضغط المفاتيح. انقر بالزر الأيمن للمسح." },
                { "Reset shortcuts", "إعادة تعيين الاختصارات" },
                { "Puts every shortcut back to its default", "يعيد كل اختصار إلى وضعه الافتراضي" },
                { "Start PiP Studio when I sign in", "تشغيل PiP Studio عند تسجيل الدخول" },
                { "It starts quietly in the tray", "يبدأ بهدوء في شريط المهام" },
                { "Bring back my PiPs when PiP Studio starts", "إعادة نوافذي العائمة عند بدء PiP Studio" },
                { "Tips and alerts from the tray icon", "نصائح وتنبيهات من أيقونة شريط المهام" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "إخفاء النوافذ العائمة من لقطات الشاشة والتسجيلات ومشاركة الشاشة" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "لن يراها OBS وDiscord وTeams وأداة القصاصة. يكلّف قليلًا من الأداء، لذا اتركه مطفأً ما لم تكن تبث أو تشارك شاشتك." },
                { "Costs a little performance", "يكلّف قليلًا من الأداء" },
                { "Keep running in the tray when I close this window", "الاستمرار في العمل في شريط المهام عند إغلاق هذه النافذة" },
                { "Otherwise closing this window quits PiP Studio", "وإلا فإن إغلاق هذه النافذة ينهي PiP Studio" },
                { "Release memory while idle", "تحرير الذاكرة عند الخمول" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "يعيد الذاكرة غير المستخدمة إلى Windows أثناء بقاء PiP Studio في شريط المهام" },
                { "Give memory back while in the tray", "إعادة الذاكرة أثناء البقاء في شريط المهام" },
                { "Running as administrator", "يعمل كمسؤول" },
                { "PiP Studio can show windows of apps that run as administrator", "يمكن لـ PiP Studio عرض نوافذ التطبيقات التي تعمل كمسؤول" },
                { "Can show admin apps' windows", "يمكنه عرض نوافذ تطبيقات المسؤول" },
                { "Restart as administrator", "إعادة التشغيل كمسؤول" },
                { "Needed only to show windows of apps that run as administrator", "مطلوب فقط لعرض نوافذ التطبيقات التي تعمل كمسؤول" },
                { "Only needed for admin apps' windows", "مطلوب فقط لنوافذ تطبيقات المسؤول" },
                { "Needs administrator", "يتطلب صلاحيات المسؤول" },
                { "Version {0}", "الإصدار {0}" },
                { "Exit PiP Studio", "إنهاء PiP Studio" },
                { "Settings folder", "مجلد الإعدادات" },
                { "Open", "فتح" },
                { "Picture-in-picture for any window or part of the screen", "صورة داخل صورة لأي نافذة أو جزء من الشاشة" },
                { "Uses Windows' own live thumbnails", "يستخدم الصور المصغرة المباشرة الخاصة بـ Windows" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "يستخدم عرض النوافذ المباشر نظام الصور المصغرة الخاص بـ Windows، لذا لا يكاد يكلّف شيئًا." },
                { "Select", "تحديد" },
                { "Back", "رجوع" },
                { "Tabs", "علامات التبويب" },
                { "Search", "بحث" },
                { "Scroll", "تمرير" },
                { "Type", "كتابة" },
                { "Space", "مسافة" },
                { "Clear", "مسح" },
                { "Done", "تم" },
                { "Snap spots", "مواضع التثبيت" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "عند إفلات نافذة عائمة تنزلق إلى أقرب موضع: الزوايا الأربع، ومنتصف كل حافة عند تفعيل المواضع الثمانية. تستخدم مفاتيح الأسهم وأزرار الاتجاه المواضع نفسها." },
                { "How far a PiP sits from the edges of the screen.", "المسافة بين النافذة العائمة وحواف الشاشة." },
                { "Where new PiPs open", "أين تُفتح النوافذ العائمة الجديدة" },
                { "A new PiP pops up in the corner you pick here.", "تظهر النافذة العائمة الجديدة في الزاوية التي تختارها هنا." },
                { "Size of new PiPs", "حجم النوافذ العائمة الجديدة" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "عندما يصل المؤشر إلى النافذة العائمة، يمكنها إظهار عناصر التحكم أو التلاشي أو عدم فعل شيء أو الابتعاد عن الطريق. عندما تبتعد، اضغط Ctrl مطولًا لإمساكها. وتحدد «شفافية التلاشي» مدى شفافيتها." },
                { "Move arrows", "أسهم التحريك" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "أزرار الأسهم على النافذة العائمة ترسلها إلى الموضع التالي، أو إلى الشاشة التالية." },
                { "Ghost mode", "وضع الشبح" },
                { "Clicks go straight through the PiP to the window behind it.", "تمر النقرات عبر النافذة العائمة مباشرة إلى النافذة التي خلفها." },
                { "Follow the window you left", "تابع النافذة التي غادرتها" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "عند التبديل بين النوافذ، تنتقل النافذة العائمة إلى النافذة التي كنت عليها، فتبقى النافذة التي غادرتها ظاهرة. النوافذ العائمة التلقائية تفعل ذلك دائمًا." },
                { "Hide while its window is in front", "الإخفاء عندما تكون نافذتها في المقدمة" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "لا داعي لعرض النافذة مرتين: تختفي النافذة العائمة أثناء وجودك في نافذتها." },
                { "Hide over full-screen apps", "الإخفاء فوق التطبيقات بملء الشاشة" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "تبتعد النوافذ العائمة على الشاشة أثناء تشغيل تطبيق أو لعبة بملء الشاشة عليها." },
                { "How see-through a new PiP is.", "مدى شفافية النافذة العائمة الجديدة." },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "نافذة عائمة كبيرة في المنتصف عندما تريد المشاهدة بتركيز. اضغط مجددًا للعودة." },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "تصغير المصدر يخفيه خارج الشاشة لتستمر النافذة العائمة بالحركة. انقر عليه في شريط المهام لإعادته." },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "ما يفعله النقر بالزر الأيمن على النافذة العائمة: فتح قائمتها أو إغلاقها أو إظهار نافذتها أو وضع المسرح أو لا شيء." },
                { "More than one PiP", "أكثر من نافذة عائمة" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "تشغيل: تُفتح كل نافذة عائمة جديدة بجانب الأخرى. إيقاف: فتح نافذة جديدة يبدّل النافذة المفتوحة إلى النافذة الجديدة." },
                { "Other apps' PiPs", "النوافذ العائمة للتطبيقات الأخرى" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "عندما لا تكون هناك نافذة عائمة من PiP Studio مفتوحة، تتحكم اختصاراتك ووحدة التحكم في نوافذ الصورة داخل الصورة الخاصة بـ Chrome وEdge وFirefox وDiscord وغيرها: تحريكًا وتغييرًا للحجم وتلاشيًا وكتمًا وإغلاقًا. وتستقر أيضًا في نفس مواضع نوافذك عند فتحها وعند إفلاتها بعد السحب." },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "حرّك النوافذ العائمة وغيّر حجمها وبدّلها بوحدة تحكم Xbox أو PlayStation أو Switch أو معظم الأنواع الأخرى. مع تفعيل «تحرير تركيز اللعبة» تتجاهل اللعبة وحدة التحكم أثناء توجيهك للنافذة العائمة وتستعيد التركيز بعد ذلك. تُظهر التلميحات وظيفة كل زر، وتتلاشى بعد بضع ثوانٍ من الخمول." },
                { "Shows controls", "تُظهر عناصر التحكم" },
                { "Fades to {0}%", "تتلاشى إلى {0}%" },
                { "Nothing happens", "لا يحدث شيء" },
                { "Moves out of the way", "تبتعد عن الطريق" },
                { "Glides into place", "تنزلق إلى مكانها" },
                { "Jumps into place", "تقفز إلى مكانها" },
                { "Max height {0}%", "أقصى ارتفاع {0}%" },
                { "Max width {0}%", "أقصى عرض {0}%" },
