                { "PiP Studio is running", "PiP Studio يعمل" },
                { "Press {0} any time to put a window in picture-in-picture. Click this tray icon to open PiP Studio.", "اضغط {0} في أي وقت لوضع نافذة في وضع الصورة داخل الصورة. انقر على أيقونة شريط المهام هذه لفتح PiP Studio." },
                { "Something went wrong", "حدث خطأ ما" },
                { "Some shortcuts are taken by another app", "بعض الاختصارات يستخدمها تطبيق آخر" },
