                { "Enter or double-click to confirm  ·  Esc to cancel  ·  F = everything  ·  Shape: 1 Free  2 16:9  3 4:3  4 1:1  5 9:16  (now: {0})", "Enter أو النقر المزدوج للتأكيد  ·  Esc للإلغاء  ·  F = الكل  ·  الشكل: 1 حر  2 16:9  3 4:3  4 1:1  5 9:16  (الحالي: {0})" },
                { "8 spots instead of 4 corners", "8 مواضع بدلًا من 4 زوايا" },
