                { "Smallest size", "أصغر حجم" },
                { "Eight sizes from Extra small to Extra large, set by width so a PiP keeps its shape. Bigger and Smaller step through the same sizes. Your choice is highlighted.", "ثمانية أحجام من صغير جدًا إلى كبير جدًا، تُحدَّد بالعرض لتحافظ النافذة العائمة على شكلها. يتنقل «أكبر» و«أصغر» بين الأحجام نفسها. يُبرَز اختيارك." },
                { "Extra small", "صغير جدًا" },
