                { "Snapping", "التثبيت" },
                { "Match the picture", "مطابقة الصورة" },
                { "Follow my setting", "اتبع إعدادي" },
                { "Always snap to spots", "التثبيت دائمًا في المواضع" },
                { "Never snap", "عدم التثبيت أبدًا" },
                { "No sound from this app right now", "لا يصدر هذا التطبيق صوتًا الآن" },
                { "Crops away the bars around the video", "يقص الأشرطة المحيطة بالفيديو" },
                { "Fits the window to the video so the bars disappear", "يلائم النافذة مع الفيديو لتختفي الأشرطة" },
                { "Snapping follows Settings", "التثبيت يتبع الإعدادات" },
                { "Snaps to spots", "تُثبَّت في المواضع" },
                { "Doesn't snap", "لا تُثبَّت" },
                { "Showing the whole picture", "عرض الصورة كاملة" },
                { "Couldn't look at the source right now", "تعذر فحص المصدر الآن" },
                { "No black bars found", "لم يُعثر على أشرطة سوداء" },
                { "Black bars removed", "أُزيلت الأشرطة السوداء" },
                { "Removing black bars", "جارٍ إزالة الأشرطة السوداء" },
                { "Black bars left alone", "تُركت الأشرطة السوداء كما هي" },
                { "Updates", "التحديثات" },
                { "What's new", "ما الجديد" },
                { "Check now", "تحقّق الآن" },
                { "Update now", "حدّث الآن" },
                { "Check for updates automatically", "التحقّق من التحديثات تلقائيًا" },
                { "Once a day, on GitHub. Nothing about you or your PC is sent.", "مرة يوميًا عبر GitHub. لا يُرسَل أي شيء عنك أو عن جهازك." },
                { "Checking for updates…", "جارٍ التحقّق من التحديثات…" },
                { "You're up to date (version {0})", "لديك أحدث إصدار ({0})" },
                { "Version {0} is available", "الإصدار {0} متاح" },
                { "Downloading the update… {0}%", "جارٍ تنزيل التحديث… {0}%" },
                { "Installing the update…", "جارٍ تثبيت التحديث…" },
                { "You have version {0}", "لديك الإصدار {0}" },
                { "The update didn't work", "لم ينجح التحديث" },
                { "Update available", "يتوفّر تحديث" },
                { "PiP Studio {0} is out. Click to update.", "صدر PiP Studio {0}. انقر للتحديث." },
                { "PiP Studio was updated", "تم تحديث PiP Studio" },
                { "You're now on version {0}.", "أنت الآن على الإصدار {0}." },
                { "Update to version {0}…", "التحديث إلى الإصدار {0}…" },
                { "Couldn't reach GitHub. Check your internet connection and try again.", "تعذّر الوصول إلى GitHub. تحقّق من اتصالك بالإنترنت وحاول مرة أخرى." },
                { "The download was damaged (its fingerprint doesn't match). Please try again.", "التنزيل تالف (البصمة غير مطابقة). يُرجى المحاولة مرة أخرى." },
                { "Show controls on other apps' PiPs", "إظهار عناصر التحكم على النوافذ العائمة للتطبيقات الأخرى" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "أشِر إلى النافذة العائمة لتطبيق آخر ليظهر فوقها شريط عنوان PiP Studio: اسحبه لتحريك النافذة، ومرّر عليه لتغيير الصوت، واستخدم أزرار شريط العنوان التي اخترتها." },
                { "Controls on other apps' PiPs", "عناصر التحكم على النوافذ العائمة للتطبيقات الأخرى" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "أشِر إلى النافذة العائمة لـ Chrome أو Firefox أو Discord أو تطبيق آخر فيظهر شريط عنوان PiP Studio فوق حافتها العليا. اسحب الشريط لتحريك النافذة، ومرّر عليه لتغيير الصوت، وصغّرها، واستخدم الأزرار نفسها الموجودة في شريط عنوان نوافذك: إظهار التطبيق، ووضع المسرح، والتكبير، والتصغير، والزاوية التالية، والإغلاق والمزيد. يبقى باقي النافذة يعمل كالمعتاد." },
                { "Show {0}", "إظهار {0}" },
                { "Options in PiP Studio", "الخيارات في PiP Studio" },
                { "Minimize", "تصغير إلى شريط المهام" },
                { "Restore", "استعادة" },
                { "Restore {0}'s PiP", "استعادة النافذة العائمة لـ {0}" },
                { "PiP Studio's title bar appears", "يظهر شريط عنوان PiP Studio" },
                { "Your video", "الفيديو الخاص بك" },
                { "Remove", "إزالة" },
                { "Remove all", "إزالة الكل" },
                { "Marked as PiPs", "المعلَّمة كنوافذ عائمة" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "النوافذ التي اخترت معاملتها كنوافذ عائمة. إزالة إحداها تعيدها نافذة عادية وتلغي إبقاءها فوق النوافذ الأخرى." },
                { "Treat this window as a PiP?", "هل تريد معاملة هذه النافذة كنافذة عائمة؟" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "سيتعامل PiP Studio معها مثل النافذة العائمة لتطبيق آخر:" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  تنتقل إلى النوافذ العائمة الحالية وتلتصق بمواضع النوافذ العائمة" },
                { "•  It stays on top of your other windows once you move or steer it", "•  تبقى فوق نوافذك الأخرى بعد أن تحرّكها أو تتحكّم بها" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  تحرّكها اختصاراتك ووحدة التحكم وتغيّر حجمها وشفافيتها وتغلقها" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "ينطبق هذا على كل نافذة مثل هذه من {0}، الآن ولاحقًا. يمكنك التراجع عنه في أي وقت من النوافذ العائمة الحالية > المعلَّمة كنوافذ عائمة، وهذا يلغي أيضًا إبقاءها فوق النوافذ الأخرى." },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "ينطبق هذا على هذه النافذة فقط حتى تُغلق. يمكنك التراجع عنه في أي وقت من النوافذ العائمة الحالية > المعلَّمة كنوافذ عائمة، وهذا يلغي أيضًا إبقاءها فوق النوافذ الأخرى." },
                { "Remove every mark?", "هل تريد إزالة كل العلامات؟" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "تعود كل نافذة علّمتها بـ «معاملة كنافذة عائمة» نافذة عادية، ويُلغى إبقاؤها فوق النوافذ الأخرى." },
                { "Every window like this from {0}", "كل نافذة مثل هذه من {0}" },
