                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "أدِر نوافذك العائمة وصوت كل تطبيق من متصفح هاتفك عبر شبكة Wi-Fi المنزلية. قد يطلب Windows السماح لـ PiP Studio على الشبكات الخاصة." },
