                { "Your phone opens {0}", "يفتح هاتفك {0}" },
                { "Not used since PiP Studio started", "لم يُستخدم منذ تشغيل PiP Studio" },
                { "Last used {0}", "آخر استخدام {0}" },
                { "Remove {0}?", "هل تريد إزالة {0}؟" },
                { "It stops working right away. You can pair it again any time.", "سيتوقف عن العمل فورًا. يمكنك إقرانه مجددًا في أي وقت." },
                { "No network", "لا توجد شبكة" },
                { "PiP Studio can't find this PC's address on your local network. Connect to Wi-Fi or Ethernet and try again.", "لا يستطيع PiP Studio العثور على عنوان هذا الكمبيوتر على شبكتك المحلية. اتصل بشبكة Wi-Fi أو Ethernet وحاول مرة أخرى." },
                { "Paired with {0}. You can close this.", "تم الإقران مع {0}. يمكنك إغلاق هذه النافذة." },
                { "Couldn't open a network port. Another app may be using it.", "تعذّر فتح منفذ الشبكة. ربما يستخدمه تطبيق آخر." },
                { "Or open {0} on your phone", "أو افتح {0} على هاتفك" },
                { "Waiting for your phone…", "في انتظار هاتفك…" },
                { "That PIN doesn't match. Check the PIN on your phone.", "رمز PIN غير مطابق. تحقّق من الرمز الظاهر على هاتفك." },
                { "Too many wrong PINs. Start pairing again on your phone.", "محاولات خاطئة كثيرة. ابدأ الإقران من جديد على هاتفك." },
                { "No phone is showing a PIN yet. Open the page on your phone and tap Pair.", "لا يوجد هاتف يعرض رمز PIN بعد. افتح الصفحة على هاتفك واضغط «إقران»." },
                { "Your phone is showing a PIN. Type it here.", "يعرض هاتفك رمز PIN. اكتبه هنا." },
                { "1. Scan this code with your phone's camera (it needs to be on the same Wi-Fi as this PC) and tap Pair.", "1. امسح هذا الرمز بكاميرا هاتفك (يجب أن يكون على شبكة Wi-Fi نفسها التي يتصل بها هذا الكمبيوتر) ثم اضغط «إقران»." },
                { "2. Your phone shows a 6-digit PIN. Type it below.", "2. يعرض هاتفك رمز PIN من 6 أرقام. اكتبه أدناه." },
                { "Pair", "إقران" },
                { "PiP Studio closed unexpectedly", "أُغلق PiP Studio بشكل غير متوقع" },
                { "Click to send a crash report, so it can be fixed.", "انقر لإرسال تقرير الأعطال حتى يمكن إصلاحه." },
                { "Sending this report helps get it fixed. It opens a new issue on GitHub in your browser with this already filled in, so you can check it, add what you were doing, and send it yourself. Your Windows user name and PC name are left out.", "إرسال هذا التقرير يساعد على إصلاح المشكلة. سيفتح بلاغًا جديدًا على GitHub في متصفحك وقد مُلئ بهذه المعلومات، لتتحقق منه وتضيف ما كنت تفعله وترسله بنفسك. لا يُضمَّن اسم مستخدم Windows ولا اسم الكمبيوتر." },
                { "Send report", "إرسال التقرير" },
                { "Copy report", "نسخ التقرير" },
                { "Report a problem", "الإبلاغ عن مشكلة" },
                { "Opens a bug report on GitHub with your PiP Studio and Windows versions and recent errors filled in", "يفتح بلاغًا عن خطأ على GitHub مع إصدار PiP Studio وإصدار Windows والأخطاء الأخيرة" },
                { "Report", "إبلاغ" },
                { "Copied", "تم النسخ" },
                { "Controller controls on · The game runs as admin, so it still gets the controller", "تحكم وحدة التحكم مفعّل · اللعبة تعمل كمسؤول، لذا ما زالت تستقبل وحدة التحكم" },
                { "The game runs as administrator", "اللعبة تعمل كمسؤول" },
                { "So it keeps getting your controller. Click to restart PiP Studio as administrator, which fixes that.", "لذا تستمر في استقبال وحدة التحكم. انقر لإعادة تشغيل PiP Studio كمسؤول لحل ذلك." },
                { "Always start as administrator", "التشغيل كمسؤول دائمًا" },
                { "Without asking each time, also at sign-in. For games and apps that run as administrator: PiP Studio can then show their windows and take their focus for controller controls. Windows asks once to set it up.", "دون السؤال في كل مرة، وعند تسجيل الدخول أيضًا. للألعاب والتطبيقات التي تعمل كمسؤول: يمكن لـ PiP Studio حينها عرض نوافذها وأخذ التركيز منها لعناصر تحكم وحدة التحكم. يسأل Windows مرة واحدة لإعداد ذلك." },
                { "Restart as administrator now?", "هل تريد إعادة التشغيل كمسؤول الآن؟" },
                { "From now on PiP Studio starts as administrator without asking, also when it starts at sign-in.", "من الآن فصاعدًا يبدأ PiP Studio كمسؤول دون السؤال، وكذلك عند بدء التشغيل مع تسجيل الدخول." },
                { "Phone", "الهاتف" },
