                { "Rename", "إعادة تسمية" },
                { "Rename phone", "إعادة تسمية الهاتف" },
                { "The name shows here, so you can tell your phones apart.", "يظهر الاسم هنا حتى تميّز بين هواتفك." },
                { "Save", "حفظ" },
                { "Not in the Microsoft Store version", "غير متوفر في إصدار Microsoft Store" },
                { "The phone companion needs network access the Store version doesn't have. The installer and portable versions from GitHub include it.", "يحتاج تطبيق الهاتف المرافق إلى وصول للشبكة غير متوفر في إصدار المتجر. يتضمنه إصدار المثبّت والإصدار المحمول من GitHub." },
                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "يصبح هاتفك جهاز تحكم عن بُعد لـ PiP Studio: حرّك النوافذ العائمة وغيّر حجمها وبدّل ما تعرضه واضبط صوت كل تطبيق، من متصفح الهاتف عبر شبكة Wi-Fi المنزلية. لا شيء يمر عبر الإنترنت، وكل ما بين الهاتف والكمبيوتر مشفّر." },
                { "Pairing a phone", "إقران هاتف" },
                { "Like pairing Moonlight with Sunshine: scan the code, tap Pair on your phone, and type the PIN it shows into PiP Studio. The PIN only matches when nothing sits between the two, and only paired phones can connect. Remove a phone any time.", "مثل إقران Moonlight مع Sunshine: امسح الرمز، واضغط «إقران» على هاتفك، واكتب رمز PIN الظاهر فيه في PiP Studio. لا يتطابق الرمز إلا إذا لم يكن هناك وسيط بين الجهازين، ولا يمكن الاتصال إلا للهواتف المقترنة. يمكنك إزالة أي هاتف في أي وقت." },
                { "Type the phone's PIN", "اكتب رمز PIN الظاهر في الهاتف" },
                { "Light, dark or OLED (black instead of grey, great on OLED screens) for PiP Studio's windows and menus, or follow Windows.", "فاتح أو داكن أو OLED (أسود بدل الرمادي، رائع على شاشات OLED) لنوافذ PiP Studio وقوائمه، أو اتبع إعداد Windows." },
                { "Light, dark or OLED black, for PiP Studio's windows and menus", "فاتح أو داكن أو أسود OLED لنوافذ PiP Studio وقوائمه" },
