                { "Match accent color", "匹配主题色" },
                { "Used when Match accent color is off", "关闭“匹配主题色”时使用" },
                { "Width", "宽度" },
                { "Messages under the PiP", "画中画下方的消息" },
                { "When you switch sources or change a mode, the message shows below the PiP instead of over the picture", "切换来源或更改模式时，消息显示在画中画下方，而不是画面上" },
                { "When you switch sources or change a mode, the message shows in a small caption below the PiP instead of over the picture. Volume changes show a level bar there too.", "切换来源或更改模式时，消息以小标签显示在画中画下方，而不是画面上。调节音量时，那里也会显示音量条。" },
                { "Show messages below the PiP, not on it", "在画中画下方显示消息，而不是在画面上" },
                { "Lite mode", "精简模式" },
                { "For slower PCs: turns off animations, the Mica background, shadows and live previews", "适用于较慢的电脑：关闭动画、Mica 背景、阴影和实时预览" },
                { "For slower PCs: turns off animations, the Mica background, shadows and live previews. PiPs themselves work the same.", "适用于较慢的电脑：关闭动画、Mica 背景、阴影和实时预览。画中画本身的功能不变。" },
                { "Fewer effects, for slower PCs", "减少效果，适合较慢的电脑" },
                { "Animation effects", "动画效果" },
                { "Glide, fade and slide effects in PiP Studio and on PiPs", "PiP Studio 和画中画中的滑动与淡入淡出效果" },
                { "Glide, fade and slide effects in PiP Studio and on PiPs. Off, things jump straight into place.", "PiP Studio 和画中画中的滑动与淡入淡出效果。关闭后，元素会直接跳到位。" },
