                { "Size limits", "尺寸限制" },
                { "Keep tall or wide apps from getting too big. Applies to new PiPs, size presets, resizing and source changes (theater mode ignores them).", "防止过高或过宽的应用变得太大。适用于新画中画、预设大小、调整大小和更换来源（影院模式除外）。" },
                { "Tall or wide apps stop growing at the size you set, as a share of the screen. Applies to new PiPs, size presets, resizing and source changes. Theater mode ignores them.", "过高或过宽的应用会在你设定的大小（屏幕比例）处停止变大。适用于新画中画、预设大小、调整大小和更换来源。影院模式不受限制。" },
                { "Stop tall or wide apps getting too big", "防止过高或过宽的应用变得太大" },
