                { "Share of the screen", "占屏幕的比例" },
                { "Control other apps' PiP windows", "控制其他应用的画中画窗口" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture window of Chrome, Edge, Firefox and other apps.", "当没有打开 PiP Studio 画中画时，你的快捷键和控制器可以移动、缩放、淡化、静音和关闭 Chrome、Edge、Firefox 等应用的画中画窗口。" },
                { "Steer browser and app PiPs too", "也可控制浏览器和应用的画中画" },
                { "Snap other apps' PiPs to spots", "将其他应用的画中画吸附到位置" },
                { "Other apps' PiP windows land on the same corners and edge spots as PiP Studio's PiPs, when they open and when you let go of them after dragging.", "其他应用的画中画窗口在打开时以及拖动后松开时，会停靠到与 PiP Studio 画中画相同的角落和边缘位置。" },
                { "They land on the same spots as yours", "它们会停靠在与你的画中画相同的位置" },
                { "Allow more than one PiP at a time", "允许同时打开多个画中画" },
                { "When off, opening a new PiP switches the one that's already open", "关闭后，打开新画中画会切换已打开的那个" },
                { "Off: a new PiP replaces the open one", "关闭：新画中画会替换已打开的" },
                { "Follow the window I just left", "跟随我刚离开的窗口" },
                { "When you switch windows, the PiP switches to the one you were on", "切换窗口时，画中画会切换到你刚才所在的窗口" },
                { "The PiP shows the window you just left", "画中画显示你刚离开的窗口" },
                { "Snap after moving", "移动后吸附" },
                { "Glides to the nearest spot when you let go", "松开时滑到最近的位置" },
                { "Middle of each edge too", "也包括每条边的中点" },
                { "8 spots instead of 4 corners — also used by the arrow keys and D-pad", "8 个位置而不是 4 个角 — 方向键和十字键也使用这些位置" },
                { "Gap from the screen edges", "与屏幕边缘的间距" },
                { "Gap from the edges", "与边缘的间距" },
                { "Stay on one display", "保持在一个显示器上" },
                { "Moving past the edge won't hop to the next display", "移过边缘时不会跳到下一个显示器" },
                { "Don't hop to the next display", "不跳到下一个显示器" },
                { "When the pointer is over a PiP", "当指针位于画中画上时" },
                { "What a PiP does when you point at it", "指针指向画中画时它会怎么做" },
                { "Move out of the way slides it aside — hold Ctrl to grab it instead", "“让开”会把它移到一边 — 按住 Ctrl 可以抓住它" },
                { "Show controls", "显示控件" },
