                { "Move out of the way", "让开" },
                { "Show move arrows", "显示移动箭头" },
                { "Arrow buttons send the PiP to the next spot — or the next display", "箭头按钮把画中画移到下一个位置 — 或下一个显示器" },
                { "Arrow buttons that hop to the next spot", "跳到下一个位置的箭头按钮" },
                { "Fade-out opacity", "淡出不透明度" },
                { "How visible a PiP stays while it fades under the pointer", "指针下淡出时画中画的可见程度" },
                { "How see-through it gets", "它变得多透明" },
                { "Click-through opacity", "点击穿透不透明度" },
