                { "It would only repeat what's already on screen", "它只会重复屏幕上已有的内容" },
                { "Hide PiPs while a fullscreen app is on the same display", "同一显示器上有全屏应用时隐藏画中画" },
                { "Borderless games still show PiPs unless this is on", "除非打开此项，否则无边框游戏仍会显示画中画" },
                { "Includes borderless games", "包括无边框游戏" },
