                { "Bigger layout and button hints", "更大的布局和按钮提示" },
                { "Bigger layout, a focus ring and button hints, so you can use this window with a controller. Pressing a key on the keyboard switches back.", "更大的布局、焦点框和按钮提示，方便用控制器操作此窗口。按下键盘上的任意键即可切换回来。" },
