                { "Hints fade after a few seconds", "提示会在几秒后淡出" },
                { "The PiP's name and button hints fade after a few seconds without input. Any button brings them back. Less for Windows to draw over your game.", "无输入几秒后，画中画名称和按钮提示会淡出。按任意按钮即可恢复。Windows 在游戏上需要绘制的内容更少。" },
