                { "Switch controller", "Switch 控制器" },
                { "These work anywhere in Windows. Click a shortcut, then press the new keys (Backspace clears, Esc cancels). Right-click clears it. They act on the PiP you used or pointed at most recently.", "这些快捷键在 Windows 中任何地方都可用。点击一个快捷键，然后按下新按键（Backspace 清除，Esc 取消）。右键单击可清除。它们作用于你最近使用或指向的画中画。" },
                { "Open and choose", "打开和选择" },
