                { "Reset shortcuts", "重置快捷键" },
                { "Puts every shortcut back to its default", "将所有快捷键恢复为默认值" },
                { "Start PiP Studio when I sign in", "登录时启动 PiP Studio" },
                { "It starts quietly in the tray", "它会在托盘中静默启动" },
                { "Bring back my PiPs when PiP Studio starts", "PiP Studio 启动时恢复我的画中画" },
                { "Tips and alerts from the tray icon", "来自托盘图标的提示和提醒" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "在截图、录屏和屏幕共享中隐藏画中画" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "OBS、Discord、Teams 和截图工具都看不到它们。会稍微影响性能，除非你在直播或共享屏幕，否则请保持关闭。" },
                { "Costs a little performance", "会稍微影响性能" },
                { "Keep running in the tray when I close this window", "关闭此窗口时继续在托盘中运行" },
                { "Otherwise closing this window quits PiP Studio", "否则关闭此窗口会退出 PiP Studio" },
                { "Release memory while idle", "空闲时释放内存" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "PiP Studio 在托盘中时将未使用的内存归还给 Windows" },
