                { "Picture-in-picture for any window or part of the screen", "为任意窗口或屏幕区域开启画中画" },
                { "Uses Windows' own live thumbnails", "使用 Windows 自带的实时缩略图" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "实时窗口镜像使用 Windows 自带的缩略图系统，因此几乎不占资源。" },
                { "Select", "选择" },
