                { "Space", "空格" },
                { "Clear", "清除" },
                { "Done", "完成" },
                { "Snap spots", "吸附位置" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "松开画中画时，它会滑到最近的位置：4 个角，开启 8 个位置时还包括每条边的中点。方向键和十字键使用相同的位置。" },
                { "How far a PiP sits from the edges of the screen.", "画中画与屏幕边缘的距离。" },
                { "Where new PiPs open", "新画中画的打开位置" },
                { "A new PiP pops up in the corner you pick here.", "新画中画会出现在你在这里选择的位置。" },
                { "Size of new PiPs", "新画中画的大小" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "指针移到画中画上时，它可以显示控件、淡出、不做任何事，或滑开让路。滑开时，按住 Ctrl 可以抓住它。“淡出不透明度”决定它的透明程度。" },
                { "Move arrows", "移动箭头" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "画中画上的箭头按钮可将其移到下一个位置，或移到下一个显示器。" },
                { "Ghost mode", "幽灵模式" },
                { "Clicks go straight through the PiP to the window behind it.", "点击会直接穿过画中画，作用于其后面的窗口。" },
                { "Follow the window you left", "跟随你离开的窗口" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "切换窗口时，画中画会切换到你刚才所在的窗口，让你离开的窗口保持可见。自动画中画始终如此。" },
                { "Hide while its window is in front", "当其窗口在前台时隐藏" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "没必要显示两次同一个窗口：当你在其窗口中时，画中画会让开。" },
                { "Hide over full-screen apps", "在全屏应用上方隐藏" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "当显示器上运行全屏应用或游戏时，该显示器上的画中画会让开。" },
                { "How see-through a new PiP is.", "新画中画的透明程度。" },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "一个居中的大画中画，适合认真观看。再按一次即可返回。" },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "最小化来源时会将其移到屏幕外，让画中画继续更新。在任务栏中点击它即可恢复。" },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "右键单击画中画时的操作：打开菜单、关闭、显示其窗口、影院模式或不执行任何操作。" },
                { "More than one PiP", "多个画中画" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "开启：每个新画中画都会与其他画中画并存。关闭：打开新画中画会把已打开的那个切换到新窗口。" },
                { "Other apps' PiPs", "其他应用的画中画" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "当没有打开 PiP Studio 画中画时，你的快捷键和控制器可以移动、缩放、淡化、静音和关闭 Chrome、Edge、Firefox、Discord 等应用的画中画窗口。它们在打开时以及拖动后松开时，也会停靠到与你的画中画相同的位置。" },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "用 Xbox、PlayStation、Switch 或大多数其他控制器移动、缩放和切换画中画。开启“释放游戏的焦点”后，你操作画中画时游戏会忽略控制器，之后重新获得焦点。提示会显示每个按钮的作用，空闲几秒后淡出。" },
                { "Shows controls", "显示控件" },
                { "Fades to {0}%", "淡出至 {0}%" },
                { "Nothing happens", "什么也不发生" },
                { "Moves out of the way", "让开" },
                { "Glides into place", "滑动到位" },
                { "Jumps into place", "直接跳到位" },
