                { "The download was damaged (its fingerprint doesn't match). Please try again.", "下载的文件已损坏（校验值不匹配）。请重试。" },
                { "Show controls on other apps' PiPs", "在其他应用的画中画上显示控件" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "将指针移到其他应用的画中画上，即可在其上方显示 PiP Studio 的标题栏：拖动它可移动画中画，在其上滚动可调节音量，还可使用你选择的标题栏按钮。" },
                { "Controls on other apps' PiPs", "其他应用画中画上的控件" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "将指针移到 Chrome、Firefox、Discord 或其他应用的画中画窗口上，PiP Studio 的标题栏就会出现在其顶部。拖动标题栏可移动画中画，在其上滚动可调节音量，可最小化，还可使用与你自己的画中画标题栏相同的按钮：显示应用、影院模式、放大、缩小、下一个角落、关闭等。画中画的其余部分照常工作。" },
                { "Show {0}", "显示 {0}" },
