                { "Remove", "移除" },
                { "Remove all", "全部移除" },
                { "Marked as PiPs", "标记为画中画的窗口" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "你选择当作画中画的窗口。移除后，它会变回普通窗口，并取消置顶。" },
                { "Treat this window as a PiP?", "将此窗口当作画中画？" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "PiP Studio 会像对待其他应用的画中画窗口一样处理它：" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  它会出现在“正在运行的画中画”中，并吸附到画中画位置" },
                { "•  It stays on top of your other windows once you move or steer it", "•  移动或操控它之后，它会保持在其他窗口之上" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  你的画中画快捷键和手柄可以移动、调整大小、淡化和关闭它" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "这适用于 {0} 中所有与此类似的窗口，包括以后打开的。你可以随时在“正在运行的画中画 > 标记为画中画的窗口”中撤销，同时也会取消置顶。" },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "这仅适用于此窗口，直到它关闭。你可以随时在“正在运行的画中画 > 标记为画中画的窗口”中撤销，同时也会取消置顶。" },
                { "Remove every mark?", "移除所有标记？" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "你用“当作画中画”标记的每个窗口都会变回普通窗口，并取消置顶。" },
                { "Every window like this from {0}", "{0} 中所有与此类似的窗口" },
                { "{0} · this window only, until it closes", "{0} · 仅此窗口，直到它关闭" },
                { "Phone companion", "手机伴侣" },
                { "Control PiP Studio from your phone", "用手机控制 PiP Studio" },
                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "通过家庭 Wi-Fi，在手机浏览器中管理画中画和每个应用的音量。Windows 可能会请你允许 PiP Studio 访问专用网络。" },
                { "Pair a phone", "配对手机" },
                { "Turn on the switch above first", "请先打开上方的开关" },
                { "This PC isn't on a network right now", "此电脑当前未连接网络" },
                { "Your phone opens {0}", "手机将打开 {0}" },
