                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "手机变成 PiP Studio 的遥控器：通过家庭 Wi-Fi，在手机浏览器中移动和调整画中画、切换其显示内容，并设置每个应用的音量。不会经过互联网，手机与电脑之间的一切都经过加密。" },
                { "Pairing a phone", "配对手机" },
