                { "Other apps' PiP windows land on the same corners and edge spots as PiP Studio's PiPs, when they open and when you let go of them after dragging.", "PiP-Fenster anderer Apps landen in denselben Ecken und an denselben Rändern wie die PiPs von PiP Studio, wenn sie sich öffnen und wenn du sie nach dem Ziehen loslässt." },
                { "They land on the same spots as yours", "Sie landen an denselben Positionen wie deine" },
                { "Allow more than one PiP at a time", "Mehr als ein PiP gleichzeitig erlauben" },
                { "When off, opening a new PiP switches the one that's already open", "Wenn aus, wechselt ein neues PiP das bereits offene" },
                { "Off: a new PiP replaces the open one", "Aus: ein neues PiP ersetzt das offene" },
                { "Follow the window I just left", "Dem Fenster folgen, das ich gerade verlassen habe" },
                { "When you switch windows, the PiP switches to the one you were on", "Wenn du das Fenster wechselst, wechselt das PiP zu dem, in dem du warst" },
                { "The PiP shows the window you just left", "Das PiP zeigt das Fenster, das du gerade verlassen hast" },
                { "Snap after moving", "Nach dem Verschieben einrasten" },
                { "Glides to the nearest spot when you let go", "Gleitet beim Loslassen zur nächsten Position" },
                { "Middle of each edge too", "Auch die Mitte jedes Rands" },
                { "8 spots instead of 4 corners — also used by the arrow keys and D-pad", "8 Positionen statt 4 Ecken – auch für die Pfeiltasten und das Steuerkreuz" },
                { "Gap from the screen edges", "Abstand zu den Bildschirmrändern" },
                { "Gap from the edges", "Abstand zu den Rändern" },
                { "Stay on one display", "Auf einem Bildschirm bleiben" },
                { "Moving past the edge won't hop to the next display", "Über den Rand hinaus springt es nicht auf den nächsten Bildschirm" },
                { "Don't hop to the next display", "Nicht auf den nächsten Bildschirm springen" },
                { "When the pointer is over a PiP", "Wenn der Mauszeiger über einem PiP ist" },
                { "What a PiP does when you point at it", "Was ein PiP tut, wenn du darauf zeigst" },
                { "Move out of the way slides it aside — hold Ctrl to grab it instead", "Ausweichen schiebt es zur Seite – halte Strg gedrückt, um es zu greifen" },
                { "Show controls", "Bedienelemente zeigen" },
                { "Fade out", "Ausblenden" },
                { "Do nothing", "Nichts tun" },
                { "Move out of the way", "Ausweichen" },
                { "Show move arrows", "Verschiebepfeile zeigen" },
                { "Arrow buttons send the PiP to the next spot — or the next display", "Pfeiltasten schicken das PiP zur nächsten Position – oder auf den nächsten Bildschirm" },
                { "Arrow buttons that hop to the next spot", "Pfeiltasten, die zur nächsten Position springen" },
                { "Fade-out opacity", "Deckkraft beim Ausblenden" },
                { "How visible a PiP stays while it fades under the pointer", "Wie sichtbar ein PiP bleibt, während es unter dem Mauszeiger ausblendet" },
                { "How see-through it gets", "Wie durchsichtig es wird" },
                { "Click-through opacity", "Deckkraft beim Durchklicken" },
                { "How visible a ghost-mode PiP is under the pointer", "Wie sichtbar ein PiP im Geistmodus unter dem Mauszeiger ist" },
                { "How see-through ghost mode is", "Wie durchsichtig der Geistmodus ist" },
                { "Right-click on a PiP", "Rechtsklick auf ein PiP" },
                { "Show the menu", "Menü zeigen" },
                { "Close it", "Schließen" },
                { "Bring its source to the front", "Quelle in den Vordergrund holen" },
                { "Theater mode", "Kinomodus" },
                { "Middle-click closes a PiP", "Mittelklick schließt ein PiP" },
                { "Hide a PiP while its window is in front", "Ein PiP ausblenden, während sein Fenster vorne ist" },
                { "It would only repeat what's already on screen", "Es würde nur wiederholen, was schon auf dem Bildschirm ist" },
                { "Hide PiPs while a fullscreen app is on the same display", "PiPs ausblenden, während eine Vollbild-App auf demselben Bildschirm läuft" },
                { "Borderless games still show PiPs unless this is on", "Randlose Spiele zeigen weiter PiPs, außer das hier ist an" },
                { "Includes borderless games", "Auch randlose Spiele" },
                { "Keep minimized sources playing", "Minimierte Quellen weiterlaufen lassen" },
                { "The PiP keeps moving when you minimize", "Das PiP bewegt sich weiter, wenn du minimierst" },
                { "Reconnect when a closed app opens again", "Wieder verbinden, wenn eine geschlossene App wieder geöffnet wird" },
                { "Window sources always run at full speed", "Fensterquellen laufen immer mit voller Geschwindigkeit" },
                { "Frame rate", "Bildrate" },
                { "Show the pointer", "Mauszeiger zeigen" },
                { "Use game controllers", "Gamecontroller verwenden" },
                { "Xbox, PlayStation, Switch and most others", "Xbox, PlayStation, Switch und die meisten anderen" },
                { "Turn controls on when PiP Studio starts", "Steuerung beim Start von PiP Studio einschalten" },
                { "Release the game's focus while controls are on", "Dem Spiel den Fokus nehmen, solange die Steuerung an ist" },
                { "The game ignores the controller while you move the PiP, and gets focus back afterwards", "Das Spiel ignoriert den Controller, während du das PiP bewegst, und bekommt den Fokus danach zurück" },
                { "The game ignores the controller meanwhile", "Das Spiel ignoriert den Controller solange" },
                { "Show button hints on the PiP", "Tastenhinweise auf dem PiP zeigen" },
                { "Controller-friendly mode", "Controller-Modus" },
                { "Bigger layout and button hints", "Größeres Layout und Tastenhinweise" },
                { "Bigger layout, a focus ring and button hints, so you can use this window with a controller. Pressing a key on the keyboard switches back.", "Ein größeres Layout, ein Fokusrahmen und Tastenhinweise, damit du dieses Fenster mit einem Controller bedienen kannst. Ein Tastendruck auf der Tastatur schaltet zurück." },
                { "When I use a controller", "Wenn ich einen Controller benutze" },
                { "Always", "Immer" },
                { "Off", "Aus" },
                { "Fade controller hints when idle", "Controller-Hinweise im Leerlauf ausblenden" },
                { "Hints fade after a few seconds", "Hinweise blenden nach ein paar Sekunden aus" },
                { "The PiP's name and button hints fade after a few seconds without input. Any button brings them back. Less for Windows to draw over your game.", "Der Name des PiP und die Tastenhinweise blenden nach ein paar Sekunden ohne Eingabe aus. Jede Taste holt sie zurück. So muss Windows weniger über dein Spiel zeichnen." },
                { "Controller options", "Controller-Optionen" },
                { "Button assignments", "Tastenbelegung" },
                { "Click, then press a button. Right-click clears it.", "Klicken, dann eine Taste drücken. Rechtsklick löscht sie." },
                { "Click a binding, then press the button or combination. Right-click clears it. Trigger: press, double press or hold.", "Klick auf eine Belegung, dann drück die Taste oder Kombination. Rechtsklick löscht sie. Auslöser: drücken, doppelt drücken oder halten." },
                { "Click, then press the button(s). Right-click to clear.", "Klicken, dann die Taste(n) drücken. Rechtsklick zum Löschen." },
                { "Press once, press twice quickly, or hold", "Einmal drücken, zweimal schnell drücken oder halten" },
                { "Press", "Drücken" },
                { "Double press", "Doppelt drücken" },
                { "Hold", "Halten" },
                { "Reset", "Zurücksetzen" },
                { "Connect a controller", "Controller verbinden" },
                { "Press button(s)…", "Taste(n) drücken…" },
                { "No controller connected", "Kein Controller verbunden" },
                { "No controller found", "Kein Controller gefunden" },
                { "Connect an Xbox, PlayStation or Switch controller by USB or Bluetooth.", "Verbinde einen Xbox-, PlayStation- oder Switch-Controller per USB oder Bluetooth." },
                { "Connect an Xbox, PlayStation or Switch controller to use controller controls.", "Verbinde einen Xbox-, PlayStation- oder Switch-Controller, um die Controller-Steuerung zu nutzen." },
                { "Controls are on — the PiP has an accent outline. {0} turns them off.", "Die Steuerung ist an – das PiP hat einen Rand in der Akzentfarbe. {0} schaltet sie aus." },
                { "Press {0} to turn controls on.", "Drück {0}, um die Steuerung einzuschalten." },
                { "Controller controls", "Controller-Steuerung" },
                { "Controller controls on · {0} turns them off", "Controller-Steuerung an · {0} schaltet sie aus" },
                { "Controller controls off", "Controller-Steuerung aus" },
                { "Controller controls ({0})", "Controller-Steuerung ({0})" },
                { "Xbox controller", "Xbox-Controller" },
                { "PlayStation controller", "PlayStation-Controller" },
                { "Switch controller", "Switch-Controller" },
                { "These work anywhere in Windows. Click a shortcut, then press the new keys (Backspace clears, Esc cancels). Right-click clears it. They act on the PiP you used or pointed at most recently.", "Sie funktionieren überall in Windows. Klick auf ein Tastenkürzel und drück dann die neuen Tasten (Rücktaste löscht, Esc bricht ab). Rechtsklick löscht es. Sie wirken auf das PiP, das du zuletzt benutzt oder auf das du gezeigt hast." },
                { "Open and choose", "Öffnen und auswählen" },
                { "Move and size", "Verschieben und Größe" },
                { "Look and visibility", "Aussehen und Sichtbarkeit" },
                { "Source and media", "Quelle und Medien" },
                { "Click, then press keys. Right-click to clear.", "Klicken, dann Tasten drücken. Rechtsklick zum Löschen." },
                { "Reset shortcuts", "Tastenkürzel zurücksetzen" },
                { "Puts every shortcut back to its default", "Setzt jedes Tastenkürzel auf den Standard zurück" },
                { "Start PiP Studio when I sign in", "PiP Studio bei der Anmeldung starten" },
                { "It starts quietly in the tray", "Es startet still im Infobereich" },
                { "Bring back my PiPs when PiP Studio starts", "Meine PiPs beim Start von PiP Studio zurückholen" },
                { "Tips and alerts from the tray icon", "Tipps und Hinweise vom Symbol im Infobereich" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "PiPs in Screenshots, Aufnahmen und Bildschirmfreigaben verbergen" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "OBS, Discord, Teams und das Snipping Tool sehen sie nicht. Kostet etwas Leistung, lass es also aus, außer du streamst oder teilst deinen Bildschirm." },
                { "Costs a little performance", "Kostet etwas Leistung" },
                { "Keep running in the tray when I close this window", "Im Infobereich weiterlaufen, wenn ich dieses Fenster schließe" },
                { "Otherwise closing this window quits PiP Studio", "Sonst beendet das Schließen dieses Fensters PiP Studio" },
                { "Release memory while idle", "Speicher im Leerlauf freigeben" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "Gibt ungenutzten Speicher an Windows zurück, während PiP Studio im Infobereich ist" },
                { "Give memory back while in the tray", "Speicher im Infobereich zurückgeben" },
                { "Running as administrator", "Läuft als Administrator" },
                { "PiP Studio can show windows of apps that run as administrator", "PiP Studio kann Fenster von Apps zeigen, die als Administrator laufen" },
                { "Can show admin apps' windows", "Kann Fenster von Administrator-Apps zeigen" },
                { "Restart as administrator", "Als Administrator neu starten" },
                { "Needed only to show windows of apps that run as administrator", "Nur nötig, um Fenster von Apps zu zeigen, die als Administrator laufen" },
                { "Only needed for admin apps' windows", "Nur für Fenster von Administrator-Apps nötig" },
                { "Needs administrator", "Braucht Administratorrechte" },
                { "Version {0}", "Version {0}" },
                { "Exit PiP Studio", "PiP Studio beenden" },
                { "Settings folder", "Einstellungsordner" },
                { "Open", "Öffnen" },
                { "Picture-in-picture for any window or part of the screen", "Bild-in-Bild für jedes Fenster oder jeden Bildschirmbereich" },
                { "Uses Windows' own live thumbnails", "Nutzt die Live-Miniaturen von Windows" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "Das Live-Spiegeln von Fenstern nutzt das Miniaturansichtssystem von Windows und kostet deshalb fast nichts." },
                { "Select", "Auswählen" },
                { "Back", "Zurück" },
                { "Tabs", "Tabs" },
                { "Search", "Suchen" },
                { "Scroll", "Scrollen" },
                { "Type", "Tippen" },
                { "Space", "Leerzeichen" },
                { "Clear", "Löschen" },
                { "Done", "Fertig" },
                { "Snap spots", "Einrastpositionen" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "Wenn du ein PiP loslässt, gleitet es zur nächsten Position: die 4 Ecken, plus die Mitte jedes Rands, wenn 8 Positionen an sind. Pfeiltasten und Steuerkreuz nutzen dieselben Positionen." },
                { "How far a PiP sits from the edges of the screen.", "Wie weit ein PiP von den Bildschirmrändern entfernt ist." },
                { "Where new PiPs open", "Wo neue PiPs aufgehen" },
                { "A new PiP pops up in the corner you pick here.", "Ein neues PiP erscheint in der Ecke, die du hier wählst." },
                { "Size of new PiPs", "Größe neuer PiPs" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "Ein PiP kann seine Bedienelemente zeigen, ausblenden, nichts tun oder ausweichen, wenn der Mauszeiger es erreicht. Weicht es aus, halte Strg gedrückt, um es zu greifen. Die Deckkraft beim Ausblenden bestimmt, wie durchsichtig es wird." },
                { "Move arrows", "Verschiebepfeile" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "Pfeiltasten auf dem PiP schicken es zur nächsten Position oder auf den nächsten Bildschirm." },
                { "Ghost mode", "Geistmodus" },
                { "Clicks go straight through the PiP to the window behind it.", "Klicks gehen direkt durch das PiP auf das Fenster dahinter." },
                { "Follow the window you left", "Dem verlassenen Fenster folgen" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "Wenn du das Fenster wechselst, wechselt das PiP zu dem, in dem du gerade warst, so bleibt das verlassene Fenster im Blick. Automatische PiPs machen das immer." },
                { "Hide while its window is in front", "Ausblenden, während sein Fenster vorne ist" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "Ein Fenster zweimal zu zeigen bringt nichts: Das PiP tritt zurück, während du in seinem Fenster bist." },
                { "Hide over full-screen apps", "Über Vollbild-Apps ausblenden" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "PiPs auf einem Bildschirm machen Platz, während dort eine Vollbild-App oder ein Spiel läuft." },
                { "How see-through a new PiP is.", "Wie durchsichtig ein neues PiP ist." },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "Ein großes, zentriertes PiP, wenn du richtig zuschauen willst. Nochmal drücken, um zurückzugehen." },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "Eine minimierte Quelle wird außerhalb des Bildschirms geparkt, damit das PiP in Bewegung bleibt. Klick sie in der Taskleiste an, um sie zurückzuholen." },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "Was ein Rechtsklick auf ein PiP tut: sein Menü öffnen, es schließen, sein Fenster zeigen, Kinomodus oder nichts." },
                { "More than one PiP", "Mehr als ein PiP" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "An: Jedes neue PiP öffnet sich neben den anderen. Aus: Ein neues PiP wechselt das bereits offene auf das neue Fenster." },
                { "Other apps' PiPs", "PiPs anderer Apps" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "Wenn kein PiP von PiP Studio offen ist, steuern deine Tastenkürzel und dein Controller die Bild-in-Bild-Fenster von Chrome, Edge, Firefox, Discord und anderen Apps: verschieben, Größe ändern, ausblenden, stummschalten und schließen. Sie landen auch an denselben Positionen wie deine PiPs, wenn sie sich öffnen und wenn du sie nach dem Ziehen loslässt." },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "Verschieb, skalier und wechsle PiPs mit einem Xbox-, PlayStation-, Switch- oder fast jedem anderen Controller. Mit „Dem Spiel den Fokus nehmen“ ignoriert das Spiel den Controller, während du das PiP steuerst, und bekommt den Fokus danach zurück. Hinweise zeigen, welche Taste was macht, und blenden nach ein paar Sekunden ohne Eingabe aus." },
                { "Shows controls", "Zeigt Bedienelemente" },
