                { "Controls", "Steuerung" },
                { "Start", "Start" },
                { "Move", "Bewegen" },
                { "D-pad", "Steuerkreuz" },
                { "Click any window to open it in PiP  ·  Esc to cancel", "Klick auf ein Fenster, um es als PiP zu öffnen  ·  Esc zum Abbrechen" },
                { "Enter opens the selected window  ·  Arrow keys move  ·  Type to search  ·  Esc closes", "Eingabe öffnet das ausgewählte Fenster  ·  Pfeiltasten bewegen  ·  Tippen zum Suchen  ·  Esc schließt" },
                { "Free", "Frei" },
                { "Screen region {0}", "Bildschirmbereich {0}" },
                { "Can't show this window", "Dieses Fenster kann nicht gezeigt werden" },
                { "Windows refused to mirror this window (error 0x{0}). Try another window.", "Windows hat das Spiegeln dieses Fensters abgelehnt (Fehler 0x{0}). Versuch ein anderes Fenster." },
                { "This PiP shows a screen region", "Dieses PiP zeigt einen Bildschirmbereich" },
                { "No other windows", "Keine anderen Fenster" },
                { "Auto off", "Automatisch aus" },
