                { "Source closed — waiting for it to come back", "Quelle geschlossen – wartet auf ihre Rückkehr" },
                { "Source hidden — still playing", "Quelle verborgen – läuft weiter" },
                { "Source restored", "Quelle wiederhergestellt" },
                { "Original size", "Originalgröße" },
                { "Only one display", "Nur ein Bildschirm" },
                { "Locked to this display", "An diesen Bildschirm gebunden" },
                { "No source to crop", "Keine Quelle zum Zuschneiden" },
                { "Couldn't capture the source to crop it", "Die Quelle konnte zum Zuschneiden nicht erfasst werden" },
                { "Crop — drag to choose the part of {0} to show", "Zuschneiden – zieh, um den Teil von {0} zu wählen, der gezeigt wird" },
                { "Full view", "Ganze Ansicht" },
                { "Zoom {0}", "Zoom {0}" },
                { "Click-through on · {0} turns it off", "Durchklicken an · {0} schaltet es aus" },
                { "Click-through off", "Durchklicken aus" },
                { "Always on top", "Immer im Vordergrund" },
                { "Not on top", "Nicht im Vordergrund" },
                { "Fit", "Einpassen" },
                { "Fill", "Füllen" },
                { "Stretch", "Strecken" },
                { "Position locked", "Position gesperrt" },
                { "Position unlocked", "Position entsperrt" },
                { "No app audio for this source", "Kein App-Ton für diese Quelle" },
                { "Waiting for {0}…", "Warte auf {0}…" },
                { "Source closed", "Quelle geschlossen" },
                { "It will reconnect automatically when it reopens.", "Es verbindet sich automatisch wieder, wenn es neu geöffnet wird." },
                { "Right-click › Source › Change source…", "Rechtsklick › Quelle › Quelle wechseln…" },
                { "Source is minimized", "Die Quelle ist minimiert" },
                { "Restore it, or use right-click › Source › Hide source window to keep it playing out of sight.", "Stell sie wieder her oder nutze Rechtsklick › Quelle › Quellfenster verbergen, damit sie unsichtbar weiterläuft." },
                { "Mirror a screen region instead…", "Stattdessen einen Bildschirmbereich spiegeln…" },
                { "Show everything (reset crop & zoom)", "Alles zeigen (Zuschnitt und Zoom zurücksetzen)" },
                { "Hide the source's title bar", "Titelleiste der Quelle ausblenden" },
                { "Bring source to front", "Quelle in den Vordergrund holen" },
                { "Hide source window (keeps playing)", "Quellfenster verbergen (läuft weiter)" },
                { "Previous window", "Vorheriges Fenster" },
                { "Next window", "Nächstes Fenster" },
                { "Auto (first window, then the one you just left)", "Automatisch (erstes Fenster, dann das, das du gerade verlassen hast)" },
                { "Fix frozen picture (restart {0})…", "Eingefrorenes Bild beheben ({0} neu starten)…" },
                { "Previous display", "Vorheriger Bildschirm" },
                { "Next display", "Nächster Bildschirm" },
                { "Original size (1:1 pixels)", "Originalgröße (1:1 Pixel)" },
                { "Move to next display", "Auf den nächsten Bildschirm" },
                { "Snap to the middle of edges too", "Auch an der Mitte der Ränder einrasten" },
                { "Move out of the mouse's way", "Der Maus ausweichen" },
                { "Lock position & size", "Position und Größe sperren" },
                { "Scaling", "Skalierung" },
                { "Fit (keep shape)", "Einpassen (Form behalten)" },
                { "Fill (crop edges to fill)", "Füllen (Ränder zum Füllen abschneiden)" },
                { "Media & audio", "Medien und Ton" },
                { "Play / pause", "Abspielen / Pause" },
                { "Next track", "Nächster Titel" },
                { "Previous track", "Vorheriger Titel" },
                { "Mute {0}", "{0} stummschalten" },
                { "Duplicate this PiP", "Dieses PiP duplizieren" },
                { "More options", "Weitere Optionen" },
                { "Exit theater mode", "Kinomodus beenden" },
                { "Mute — scroll to change volume", "Stumm – scrollen, um die Lautstärke zu ändern" },
                { "Move left", "Nach links" },
                { "Move right", "Nach rechts" },
                { "Move up", "Nach oben" },
                { "Move down", "Nach unten" },
                { "Change what this PiP shows", "Ändern, was dieses PiP zeigt" },
                { "Tools", "Werkzeuge" },
                { "PiP controls", "PiP-Steuerung" },
                { "Unbound", "Nicht belegt" },
                { "Enter or double-click to confirm  ·  Esc to cancel  ·  F = everything  ·  Shape: 1 Free  2 16:9  3 4:3  4 1:1  5 9:16  (now: {0})", "Eingabe oder Doppelklick zum Bestätigen  ·  Esc zum Abbrechen  ·  F = alles  ·  Form: 1 Frei  2 16:9  3 4:3  4 1:1  5 9:16  (jetzt: {0})" },
                { "8 spots instead of 4 corners", "8 Positionen statt 4 Ecken" },
                { "Small+", "Klein+" },
                { "Medium+", "Mittel+" },
                { "Large+", "Groß+" },
                { "Largest size", "Größte Größe" },
                { "Smallest size", "Kleinste Größe" },
                { "Eight sizes from Extra small to Extra large, set by width so a PiP keeps its shape. Bigger and Smaller step through the same sizes. Your choice is highlighted.", "Acht Größen von Sehr klein bis Sehr groß, nach Breite festgelegt, damit ein PiP seine Form behält. Größer und Kleiner gehen dieselben Größen durch. Deine Wahl ist hervorgehoben." },
                { "Extra small", "Sehr klein" },
                { "Pick a window or a display for this PiP", "Wähle ein Fenster oder einen Bildschirm für dieses PiP" },
                { "Show in this PiP", "In diesem PiP zeigen" },
                { "No preview for this window", "Keine Vorschau für dieses Fenster" },
                { "This window has closed", "Dieses Fenster wurde geschlossen" },
                { "It opens in a floating picture-in-picture window", "Es öffnet sich in einem schwebenden Bild-in-Bild-Fenster" },
                { "No matching windows", "Keine passenden Fenster" },
                { "Choose a window", "Fenster auswählen" },
                { "Title bar buttons", "Titelleisten-Tasten" },
                { "Pick the buttons on a PiP's title bar and their order", "Wähle die Tasten in der Titelleiste eines PiP und ihre Reihenfolge" },
                { "Always shown, so the full menu is never out of reach", "Immer da, damit das ganze Menü immer erreichbar ist" },
                { "Reset title bar buttons", "Titelleisten-Tasten zurücksetzen" },
                { "Back to the default buttons and order", "Zurück zu den Standardtasten und ihrer Reihenfolge" },
                { "The buttons a PiP's title bar shows when you point at it, in your order. Previous and Next window switch what the PiP shows, and Bigger and Smaller step through the sizes. More options always stays, so the full menu is never out of reach. On a narrow PiP, buttons on the left make room first.", "Die Tasten, die die Titelleiste eines PiP zeigt, wenn du darauf zeigst, in deiner Reihenfolge. Vorheriges und Nächstes Fenster wechseln, was das PiP zeigt, und Größer und Kleiner gehen die Größen durch. Weitere Optionen bleibt immer, damit das ganze Menü immer erreichbar ist. Auf einem schmalen PiP machen die Tasten links zuerst Platz." },
                { "Treat as a PiP", "Als PiP behandeln" },
                { "Not a PiP", "Kein PiP" },
                { "Find other apps' PiPs automatically", "PiPs anderer Apps automatisch finden" },
                { "Small always-on-top windows, like video players' mini modes, count as PiPs. Mark one as Not a PiP on the Running PiPs page.", "Kleine Fenster, die immer im Vordergrund sind, wie Mini-Modi von Videoplayern, zählen als PiPs. Markiere eins auf der Seite Offene PiPs als Kein PiP." },
                { "Windows you marked", "Von dir markierte Fenster" },
                { "Forget every Treat as a PiP and Not a PiP you chose", "Alle Als PiP behandeln und Kein PiP vergessen, die du gewählt hast" },
                { "Find other apps' PiPs", "PiPs anderer Apps finden" },
                { "PiP options", "PiP-Optionen" },
                { "Shape", "Form" },
                { "Black bars", "Schwarze Balken" },
                { "Snapping", "Einrasten" },
                { "Match the picture", "Wie das Bild" },
                { "Follow my setting", "Meiner Einstellung folgen" },
                { "Always snap to spots", "Immer an Positionen einrasten" },
                { "Never snap", "Nie einrasten" },
                { "No sound from this app right now", "Gerade kein Ton von dieser App" },
                { "Crops away the bars around the video", "Schneidet die Balken um das Video ab" },
                { "Fits the window to the video so the bars disappear", "Passt das Fenster an das Video an, damit die Balken verschwinden" },
                { "Snapping follows Settings", "Einrasten folgt den Einstellungen" },
                { "Snaps to spots", "Rastet an Positionen ein" },
                { "Doesn't snap", "Rastet nicht ein" },
                { "Showing the whole picture", "Zeigt das ganze Bild" },
                { "Couldn't look at the source right now", "Die Quelle konnte gerade nicht geprüft werden" },
                { "No black bars found", "Keine schwarzen Balken gefunden" },
                { "Black bars removed", "Schwarze Balken entfernt" },
                { "Removing black bars", "Entferne schwarze Balken" },
                { "Black bars left alone", "Schwarze Balken bleiben" },
                { "Updates", "Updates" },
                { "What's new", "Neuigkeiten" },
                { "Check now", "Jetzt prüfen" },
                { "Update now", "Jetzt aktualisieren" },
                { "Check for updates automatically", "Automatisch nach Updates suchen" },
                { "Once a day, on GitHub. Nothing about you or your PC is sent.", "Einmal am Tag, auf GitHub. Es wird nichts über dich oder deinen PC gesendet." },
                { "Checking for updates…", "Suche nach Updates…" },
                { "You're up to date (version {0})", "Du bist auf dem neuesten Stand (Version {0})" },
                { "Version {0} is available", "Version {0} ist verfügbar" },
                { "Downloading the update… {0}%", "Update wird heruntergeladen… {0} %" },
                { "Installing the update…", "Update wird installiert…" },
                { "You have version {0}", "Du hast Version {0}" },
                { "The update didn't work", "Das Update hat nicht funktioniert" },
                { "Update available", "Update verfügbar" },
                { "PiP Studio {0} is out. Click to update.", "PiP Studio {0} ist da. Klick zum Aktualisieren." },
                { "PiP Studio was updated", "PiP Studio wurde aktualisiert" },
                { "You're now on version {0}.", "Du hast jetzt Version {0}." },
                { "Update to version {0}…", "Auf Version {0} aktualisieren…" },
                { "Couldn't reach GitHub. Check your internet connection and try again.", "GitHub ist nicht erreichbar. Prüf deine Internetverbindung und versuch es noch einmal." },
                { "The download was damaged (its fingerprint doesn't match). Please try again.", "Der Download ist beschädigt (sein Fingerabdruck stimmt nicht). Bitte versuch es noch einmal." },
                { "Show controls on other apps' PiPs", "Bedienelemente auf PiPs anderer Apps zeigen" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "Zeig auf das PiP einer anderen App, damit die Titelleiste von PiP Studio darüber erscheint: Zieh sie, um das PiP zu bewegen, scroll darauf, um die Lautstärke zu ändern, und nutze die Titelleisten-Tasten, die du gewählt hast." },
                { "Controls on other apps' PiPs", "Bedienelemente auf PiPs anderer Apps" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "Zeig auf das PiP-Fenster von Chrome, Firefox, Discord oder einer anderen App, und die Titelleiste von PiP Studio erscheint an seinem oberen Rand. Zieh die Leiste, um das PiP zu bewegen, scroll darauf, um die Lautstärke zu ändern, minimier es und nutze dieselben Tasten wie in der Titelleiste deiner eigenen PiPs: App zeigen, Kinomodus, größer, kleiner, nächste Ecke, schließen und mehr. Der Rest des PiP funktioniert wie gewohnt." },
                { "Show {0}", "{0} zeigen" },
                { "Options in PiP Studio", "Optionen in PiP Studio" },
                { "Minimize", "Minimieren" },
                { "Restore", "Wiederherstellen" },
                { "Restore {0}'s PiP", "PiP von {0} wiederherstellen" },
                { "PiP Studio's title bar appears", "Die Titelleiste von PiP Studio erscheint" },
                { "Your video", "Dein Video" },
                { "Remove", "Entfernen" },
                { "Remove all", "Alle entfernen" },
                { "Marked as PiPs", "Als PiPs markiert" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "Fenster, die du als PiPs behandeln lässt. Entfernst du eins, wird es wieder ein normales Fenster und ist nicht mehr immer im Vordergrund." },
                { "Treat this window as a PiP?", "Dieses Fenster als PiP behandeln?" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "PiP Studio behandelt es wie das Bild-in-Bild-Fenster einer anderen App:" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  Es kommt zu Offene PiPs und rastet an PiP-Positionen ein" },
                { "•  It stays on top of your other windows once you move or steer it", "•  Es bleibt über deinen anderen Fenstern, sobald du es bewegst oder steuerst" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  Deine PiP-Tastenkürzel und dein Controller verschieben es, ändern seine Größe, blenden es aus und schließen es" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Das gilt für jedes solche Fenster von {0}, jetzt und später. Du kannst es jederzeit unter Offene PiPs > Als PiPs markiert rückgängig machen, dann ist es auch nicht mehr immer im Vordergrund." },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Das gilt nur für dieses Fenster, bis es geschlossen wird. Du kannst es jederzeit unter Offene PiPs > Als PiPs markiert rückgängig machen, dann ist es auch nicht mehr immer im Vordergrund." },
                { "Remove every mark?", "Alle Markierungen entfernen?" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "Jedes Fenster, das du mit Als PiP behandeln markiert hast, wird wieder ein normales Fenster und ist nicht mehr immer im Vordergrund." },
                { "Every window like this from {0}", "Jedes solche Fenster von {0}" },
                { "{0} · this window only, until it closes", "{0} · nur dieses Fenster, bis es geschlossen wird" },
                { "Phone companion", "Handy-Begleiter" },
                { "Control PiP Studio from your phone", "PiP Studio vom Handy aus steuern" },
                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "Verwalte deine PiPs und die Lautstärke jeder App im Browser deines Handys, über dein WLAN zu Hause. Windows fragt vielleicht, ob PiP Studio in privaten Netzwerken erlaubt sein soll." },
                { "Pair a phone", "Handy koppeln" },
                { "Turn on the switch above first", "Schalte zuerst den Schalter oben ein" },
                { "This PC isn't on a network right now", "Dieser PC ist gerade mit keinem Netzwerk verbunden" },
                { "Your phone opens {0}", "Dein Handy öffnet {0}" },
                { "Not used since PiP Studio started", "Seit dem Start von PiP Studio nicht benutzt" },
                { "Last used {0}", "Zuletzt benutzt {0}" },
                { "Remove {0}?", "{0} entfernen?" },
                { "It stops working right away. You can pair it again any time.", "Es funktioniert sofort nicht mehr. Du kannst es jederzeit wieder koppeln." },
                { "No network", "Kein Netzwerk" },
                { "PiP Studio can't find this PC's address on your local network. Connect to Wi-Fi or Ethernet and try again.", "PiP Studio findet die Adresse dieses PCs in deinem lokalen Netzwerk nicht. Verbinde dich mit WLAN oder Ethernet und versuch es noch einmal." },
                { "Paired with {0}. You can close this.", "Mit {0} gekoppelt. Du kannst das hier schließen." },
                { "Couldn't open a network port. Another app may be using it.", "Ein Netzwerkport konnte nicht geöffnet werden. Vielleicht nutzt ihn eine andere App." },
                { "Or open {0} on your phone", "Oder öffne {0} auf deinem Handy" },
                { "Waiting for your phone…", "Warte auf dein Handy…" },
                { "That PIN doesn't match. Check the PIN on your phone.", "Diese PIN stimmt nicht. Prüf die PIN auf deinem Handy." },
                { "Too many wrong PINs. Start pairing again on your phone.", "Zu viele falsche PINs. Starte das Koppeln auf deinem Handy neu." },
                { "No phone is showing a PIN yet. Open the page on your phone and tap Pair.", "Noch zeigt kein Handy eine PIN. Öffne die Seite auf deinem Handy und tippe auf Koppeln." },
                { "Your phone is showing a PIN. Type it here.", "Dein Handy zeigt eine PIN. Gib sie hier ein." },
                { "1. Scan this code with your phone's camera (it needs to be on the same Wi-Fi as this PC) and tap Pair.", "1. Scanne diesen Code mit der Kamera deines Handys (es muss im selben WLAN wie dieser PC sein) und tippe auf Koppeln." },
                { "2. Your phone shows a 6-digit PIN. Type it below.", "2. Dein Handy zeigt eine 6-stellige PIN. Gib sie unten ein." },
                { "Pair", "Koppeln" },
                { "PiP Studio closed unexpectedly", "PiP Studio wurde unerwartet beendet" },
                { "Click to send a crash report, so it can be fixed.", "Klick, um einen Absturzbericht zu senden, damit es behoben werden kann." },
                { "Sending this report helps get it fixed. It opens a new issue on GitHub in your browser with this already filled in, so you can check it, add what you were doing, and send it yourself. Your Windows user name and PC name are left out.", "Dieser Bericht hilft, es zu beheben. Er öffnet in deinem Browser ein neues Issue auf GitHub, in dem das schon ausgefüllt ist, damit du es prüfen, ergänzen, was du gerade gemacht hast, und selbst senden kannst. Dein Windows-Benutzername und der PC-Name werden weggelassen." },
                { "Send report", "Bericht senden" },
                { "Copy report", "Bericht kopieren" },
                { "Report a problem", "Problem melden" },
                { "Opens a bug report on GitHub with your PiP Studio and Windows versions and recent errors filled in", "Öffnet einen Fehlerbericht auf GitHub mit deinen Versionen von PiP Studio und Windows und den letzten Fehlern schon ausgefüllt" },
                { "Report", "Melden" },
                { "Copied", "Kopiert" },
                { "Controller controls on · The game runs as admin, so it still gets the controller", "Controller-Steuerung an · Das Spiel läuft als Administrator und bekommt den Controller deshalb trotzdem" },
                { "The game runs as administrator", "Das Spiel läuft als Administrator" },
                { "So it keeps getting your controller. Click to restart PiP Studio as administrator, which fixes that.", "Deshalb bekommt es weiter deinen Controller. Klick, um PiP Studio als Administrator neu zu starten, das behebt es." },
                { "Always start as administrator", "Immer als Administrator starten" },
                { "Without asking each time, also at sign-in. For games and apps that run as administrator: PiP Studio can then show their windows and take their focus for controller controls. Windows asks once to set it up.", "Ohne jedes Mal zu fragen, auch bei der Anmeldung. Für Spiele und Apps, die als Administrator laufen: PiP Studio kann dann ihre Fenster zeigen und ihnen für die Controller-Steuerung den Fokus nehmen. Windows fragt einmal zur Einrichtung." },
                { "Restart as administrator now?", "Jetzt als Administrator neu starten?" },
                { "From now on PiP Studio starts as administrator without asking, also when it starts at sign-in.", "Ab jetzt startet PiP Studio ohne Nachfrage als Administrator, auch beim Start nach der Anmeldung." },
                { "Phone", "Handy" },
                { "Paired phones", "Gekoppelte Handys" },
                { "No phones are paired yet. Press Pair a phone above to add one.", "Noch keine Handys gekoppelt. Drück oben auf Handy koppeln, um eins hinzuzufügen." },
                { "Rename", "Umbenennen" },
                { "Rename phone", "Handy umbenennen" },
                { "The name shows here, so you can tell your phones apart.", "Der Name wird hier angezeigt, damit du deine Handys auseinanderhalten kannst." },
                { "Save", "Speichern" },
                { "Not in the Microsoft Store version", "Nicht in der Microsoft Store-Version" },
                { "The phone companion needs network access the Store version doesn't have. The installer and portable versions from GitHub include it.", "Der Handy-Begleiter braucht Netzwerkzugriff, den die Store-Version nicht hat. Die Installer- und die portable Version von GitHub enthalten ihn." },
                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "Dein Handy wird zur Fernbedienung für PiP Studio: PiPs bewegen und skalieren, wechseln, was sie zeigen, und die Lautstärke jeder App einstellen, im Browser deines Handys über dein WLAN zu Hause. Nichts geht über das Internet, und alles zwischen Handy und PC ist verschlüsselt." },
                { "Pairing a phone", "Ein Handy koppeln" },
                { "Like pairing Moonlight with Sunshine: scan the code, tap Pair on your phone, and type the PIN it shows into PiP Studio. The PIN only matches when nothing sits between the two, and only paired phones can connect. Remove a phone any time.", "Wie das Koppeln von Moonlight mit Sunshine: Code scannen, auf dem Handy auf Koppeln tippen und die angezeigte PIN in PiP Studio eingeben. Die PIN passt nur, wenn nichts zwischen beiden sitzt, und nur gekoppelte Handys können sich verbinden. Entferne ein Handy jederzeit." },
                { "Type the phone's PIN", "Gib die PIN des Handys ein" },
                { "Light, dark or OLED (black instead of grey, great on OLED screens) for PiP Studio's windows and menus, or follow Windows.", "Hell, dunkel oder OLED (Schwarz statt Grau, ideal für OLED-Bildschirme) für die Fenster und Menüs von PiP Studio, oder Windows folgen." },
                { "Light, dark or OLED black, for PiP Studio's windows and menus", "Hell, dunkel oder OLED-Schwarz, für die Fenster und Menüs von PiP Studio" },
                { "OLED", "OLED" },
                { "Full-screen windows can't be PiPs", "Vollbildfenster können keine PiPs sein" },
                { "It would stay on top of everything else on that display. Switch it to windowed mode first, then try again.", "Es würde auf diesem Bildschirm über allem anderen bleiben. Schalte es zuerst in den Fenstermodus und versuch es dann noch einmal." },
                { "Press {0} any time to put a window in picture-in-picture. Start PiP Studio again to open its window.", "Drück jederzeit {0}, um ein Fenster als Bild-in-Bild zu zeigen. Starte PiP Studio erneut, um sein Fenster zu öffnen." },
                { "Your shortcuts and controller keep working. Start PiP Studio again to open this window.", "Deine Tastenkürzel und dein Controller funktionieren weiter. Starte PiP Studio erneut, um dieses Fenster zu öffnen." },
                { "Utility PiP", "Hilfs-PiP" },
                { "Utility PiPs", "Hilfs-PiPs" },
                { "System monitor", "Systemmonitor" },
                { "Clock", "Uhr" },
                { "Now playing", "Läuft gerade" },
                { "Main volume", "Gesamtlautstärke" },
                { "No app is making sound right now", "Gerade gibt keine App Ton aus" },
                { "CPU", "CPU" },
                { "GPU", "GPU" },
                { "Memory", "Arbeitsspeicher" },
                { "Network", "Netzwerk" },
                { "Nothing is playing", "Gerade läuft nichts" },
