                { "Look and visibility", "Aspecto y visibilidad" },
                { "Source and media", "Origen y multimedia" },
                { "Click, then press keys. Right-click to clear.", "Haz clic y luego pulsa las teclas. Clic derecho para borrar." },
                { "Reset shortcuts", "Restablecer atajos" },
                { "Puts every shortcut back to its default", "Devuelve cada atajo a su valor predeterminado" },
                { "Start PiP Studio when I sign in", "Iniciar PiP Studio al iniciar sesión" },
                { "It starts quietly in the tray", "Se inicia discretamente en la bandeja" },
                { "Bring back my PiPs when PiP Studio starts", "Recuperar mis PiP al iniciar PiP Studio" },
                { "Tips and alerts from the tray icon", "Consejos y avisos desde el icono de la bandeja" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "Ocultar los PiP de capturas, grabaciones y pantalla compartida" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "OBS, Discord, Teams y la Herramienta Recortes no los verán. Consume un poco de rendimiento, así que déjalo desactivado salvo que transmitas o compartas pantalla." },
                { "Costs a little performance", "Consume un poco de rendimiento" },
                { "Keep running in the tray when I close this window", "Seguir en la bandeja al cerrar esta ventana" },
                { "Otherwise closing this window quits PiP Studio", "Si no, cerrar esta ventana cierra PiP Studio" },
                { "Release memory while idle", "Liberar memoria en reposo" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "Devuelve a Windows la memoria que no se usa mientras PiP Studio está en la bandeja" },
                { "Give memory back while in the tray", "Liberar memoria mientras está en la bandeja" },
                { "Running as administrator", "Ejecutándose como administrador" },
                { "PiP Studio can show windows of apps that run as administrator", "PiP Studio puede mostrar ventanas de aplicaciones que se ejecutan como administrador" },
                { "Can show admin apps' windows", "Puede mostrar ventanas de aplicaciones de administrador" },
                { "Restart as administrator", "Reiniciar como administrador" },
                { "Needed only to show windows of apps that run as administrator", "Solo hace falta para mostrar ventanas de aplicaciones que se ejecutan como administrador" },
                { "Only needed for admin apps' windows", "Solo hace falta para aplicaciones de administrador" },
                { "Needs administrator", "Requiere administrador" },
                { "Version {0}", "Versión {0}" },
                { "Exit PiP Studio", "Salir de PiP Studio" },
                { "Settings folder", "Carpeta de configuración" },
                { "Open", "Abrir" },
                { "Picture-in-picture for any window or part of the screen", "Imagen en imagen para cualquier ventana o parte de la pantalla" },
                { "Uses Windows' own live thumbnails", "Usa las miniaturas en directo de Windows" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "El reflejo de ventanas en directo usa el sistema de miniaturas de Windows, así que apenas consume recursos." },
                { "Select", "Seleccionar" },
                { "Back", "Atrás" },
                { "Tabs", "Pestañas" },
                { "Search", "Buscar" },
                { "Scroll", "Desplazar" },
                { "Type", "Escribir" },
                { "Space", "Espacio" },
                { "Clear", "Borrar" },
                { "Done", "Listo" },
                { "Snap spots", "Posiciones de ajuste" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "Cuando sueltas un PiP, se desliza a la posición más cercana: las 4 esquinas, más el centro de cada borde con 8 posiciones activadas. Las flechas y la cruceta usan las mismas posiciones." },
                { "How far a PiP sits from the edges of the screen.", "A qué distancia de los bordes de la pantalla se sitúa un PiP." },
                { "Where new PiPs open", "Dónde se abren los PiP nuevos" },
                { "A new PiP pops up in the corner you pick here.", "Un PiP nuevo aparece en la esquina que elijas aquí." },
                { "Size of new PiPs", "Tamaño de los PiP nuevos" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "Un PiP puede mostrar sus controles, atenuarse, no hacer nada o apartarse cuando llega el puntero. Cuando se aparta, mantén pulsado Ctrl para agarrarlo. La opacidad al atenuarse indica lo transparente que se vuelve." },
                { "Move arrows", "Flechas de movimiento" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "Los botones de flecha del PiP lo envían a la siguiente posición o a la siguiente pantalla." },
                { "Ghost mode", "Modo fantasma" },
                { "Clicks go straight through the PiP to the window behind it.", "Los clics atraviesan el PiP y llegan a la ventana de detrás." },
                { "Follow the window you left", "Seguir la ventana que dejaste" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "Cuando cambias de ventana, el PiP cambia a la que estabas usando, así que la ventana que dejaste sigue a la vista. Los PiP automáticos siempre lo hacen." },
                { "Hide while its window is in front", "Ocultar mientras su ventana está delante" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "No tiene sentido mostrar una ventana dos veces: el PiP se aparta mientras estás en su ventana." },
                { "Hide over full-screen apps", "Ocultar sobre aplicaciones a pantalla completa" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "Los PiP de una pantalla se apartan mientras una aplicación o un juego a pantalla completa se ejecuta en ella." },
                { "How see-through a new PiP is.", "Lo transparente que es un PiP nuevo." },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "Un PiP grande y centrado para cuando quieres verlo bien. Vuelve a pulsar para volver." },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "Al minimizar un origen, se oculta fuera de la pantalla para que el PiP siga moviéndose. Haz clic en él en la barra de tareas para recuperarlo." },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "Qué hace el clic derecho en un PiP: abrir su menú, cerrarlo, mostrar su ventana, modo cine o nada." },
                { "More than one PiP", "Más de un PiP" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "Activado: cada PiP nuevo se abre junto a los demás. Desactivado: abrir un PiP nuevo cambia el que ya está abierto a la nueva ventana." },
                { "Other apps' PiPs", "PiP de otras aplicaciones" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "Cuando no hay ningún PiP de PiP Studio abierto, tus atajos y tu mando mueven, cambian de tamaño, atenúan, silencian y cierran las ventanas de imagen en imagen de Chrome, Edge, Firefox, Discord y otras aplicaciones. También se colocan en las mismas posiciones que tus PiP, al abrirse y al soltarlas después de arrastrarlas." },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "Mueve, cambia de tamaño y cambia los PiP con un mando de Xbox, PlayStation, Switch o casi cualquier otro. Con Quitar el foco al juego activado, el juego ignora el mando mientras manejas el PiP y recupera el foco después. Las pistas muestran qué hace cada botón y se atenúan tras unos segundos de inactividad." },
                { "Shows controls", "Muestra controles" },
                { "Fades to {0}%", "Se atenúa al {0} %" },
                { "Nothing happens", "No pasa nada" },
                { "Moves out of the way", "Se aparta" },
                { "Glides into place", "Se desliza a su sitio" },
