                { "Eight sizes from Extra small to Extra large, set by width so a PiP keeps its shape. Bigger and Smaller step through the same sizes. Your choice is highlighted.", "Ocho tamaños, de Muy pequeño a Muy grande, definidos por el ancho para que un PiP mantenga su forma. Más grande y Más pequeño recorren los mismos tamaños. Tu elección aparece resaltada." },
