                { "No matching windows", "No hay ventanas que coincidan" },
                { "Choose a window", "Elegir una ventana" },
                { "Title bar buttons", "Botones de la barra de título" },
                { "Pick the buttons on a PiP's title bar and their order", "Elige los botones de la barra de título de un PiP y su orden" },
                { "Always shown, so the full menu is never out of reach", "Siempre visible, para que el menú completo esté siempre a mano" },
                { "Reset title bar buttons", "Restablecer los botones de la barra de título" },
                { "Back to the default buttons and order", "Vuelve a los botones y el orden predeterminados" },
                { "The buttons a PiP's title bar shows when you point at it, in your order. Previous and Next window switch what the PiP shows, and Bigger and Smaller step through the sizes. More options always stays, so the full menu is never out of reach. On a narrow PiP, buttons on the left make room first.", "Los botones que muestra la barra de título de un PiP al señalarlo, en tu orden. Ventana anterior y siguiente cambian lo que muestra el PiP, y Más grande y Más pequeño recorren los tamaños. Más opciones siempre se queda, para que el menú completo esté siempre a mano. En un PiP estrecho, los botones de la izquierda dejan sitio primero." },
                { "Treat as a PiP", "Tratar como PiP" },
                { "Not a PiP", "No es un PiP" },
                { "Find other apps' PiPs automatically", "Detectar automáticamente los PiP de otras aplicaciones" },
                { "Small always-on-top windows, like video players' mini modes, count as PiPs. Mark one as Not a PiP on the Running PiPs page.", "Las ventanas pequeñas siempre visibles, como los minirreproductores de vídeo, cuentan como PiP. Marca una como No es un PiP en la página PiP abiertos." },
                { "Windows you marked", "Ventanas que marcaste" },
                { "Forget every Treat as a PiP and Not a PiP you chose", "Olvidar todos los Tratar como PiP y No es un PiP que elegiste" },
                { "Find other apps' PiPs", "Detectar PiP de otras aplicaciones" },
