                { "Couldn't reach GitHub. Check your internet connection and try again.", "No se pudo conectar con GitHub. Comprueba tu conexión a Internet y vuelve a intentarlo." },
                { "The download was damaged (its fingerprint doesn't match). Please try again.", "La descarga está dañada (su huella no coincide). Vuelve a intentarlo." },
                { "Show controls on other apps' PiPs", "Mostrar controles en los PiP de otras aplicaciones" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "Señala el PiP de otra aplicación para que aparezca la barra de título de PiP Studio encima: arrástrala para mover el PiP, desplaza sobre ella para cambiar el volumen y usa los botones de la barra de título que elegiste." },
                { "Controls on other apps' PiPs", "Controles en los PiP de otras aplicaciones" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "Señala la ventana PiP de Chrome, Firefox, Discord u otra aplicación y aparecerá la barra de título de PiP Studio sobre su borde superior. Arrastra la barra para mover el PiP, desplaza sobre ella para cambiar el volumen, minimízalo y usa los mismos botones que la barra de título de tus PiP: mostrar la aplicación, modo cine, más grande, más pequeño, siguiente esquina, cerrar y más. El resto del PiP sigue funcionando como siempre." },
                { "Show {0}", "Mostrar {0}" },
                { "Options in PiP Studio", "Opciones en PiP Studio" },
                { "Minimize", "Minimizar" },
                { "Restore", "Restaurar" },
                { "Restore {0}'s PiP", "Restaurar el PiP de {0}" },
                { "PiP Studio's title bar appears", "Aparece la barra de título de PiP Studio" },
                { "Your video", "Tu vídeo" },
                { "Remove", "Quitar" },
                { "Remove all", "Quitar todo" },
                { "Marked as PiPs", "Marcadas como PiP" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "Ventanas que elegiste tratar como PiP. Quitar una la convierte de nuevo en una ventana normal y deja de estar siempre visible." },
                { "Treat this window as a PiP?", "¿Tratar esta ventana como un PiP?" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "PiP Studio la tratará como la ventana de imagen en imagen de otra aplicación:" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  Pasa a PiP abiertos y se ajusta a las posiciones de PiP" },
                { "•  It stays on top of your other windows once you move or steer it", "•  Queda por encima de tus otras ventanas en cuanto la mueves o la manejas" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  Tus atajos de PiP y tu mando la mueven, cambian de tamaño, atenúan y cierran" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Esto se aplica a todas las ventanas como esta de {0}, ahora y en el futuro. Puedes deshacerlo en cualquier momento en PiP abiertos > Marcadas como PiP, que también deja de mantenerla siempre visible." },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Esto solo se aplica a esta ventana, hasta que se cierre. Puedes deshacerlo en cualquier momento en PiP abiertos > Marcadas como PiP, que también deja de mantenerla siempre visible." },
                { "Remove every mark?", "¿Quitar todas las marcas?" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "Todas las ventanas que marcaste con Tratar como PiP vuelven a ser ventanas normales y dejan de estar siempre visibles." },
                { "Every window like this from {0}", "Todas las ventanas como esta de {0}" },
                { "{0} · this window only, until it closes", "{0} · solo esta ventana, hasta que se cierre" },
                { "Phone companion", "Compañero para el móvil" },
                { "Control PiP Studio from your phone", "Controla PiP Studio desde tu móvil" },
                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "Gestiona tus PiP y el volumen de cada aplicación desde el navegador de tu móvil, a través de la Wi-Fi de casa. Puede que Windows te pida permitir PiP Studio en redes privadas." },
                { "Pair a phone", "Vincular un móvil" },
                { "Turn on the switch above first", "Activa primero el interruptor de arriba" },
                { "This PC isn't on a network right now", "Este PC no está conectado a ninguna red ahora mismo" },
                { "Your phone opens {0}", "Tu móvil abre {0}" },
                { "Not used since PiP Studio started", "Sin usar desde que se inició PiP Studio" },
                { "Last used {0}", "Usado por última vez {0}" },
                { "Remove {0}?", "¿Quitar {0}?" },
                { "It stops working right away. You can pair it again any time.", "Deja de funcionar enseguida. Puedes volver a vincularlo cuando quieras." },
                { "No network", "Sin red" },
                { "PiP Studio can't find this PC's address on your local network. Connect to Wi-Fi or Ethernet and try again.", "PiP Studio no encuentra la dirección de este PC en tu red local. Conéctate a la Wi-Fi o a Ethernet y vuelve a intentarlo." },
                { "Paired with {0}. You can close this.", "Vinculado con {0}. Ya puedes cerrar esto." },
                { "Couldn't open a network port. Another app may be using it.", "No se pudo abrir un puerto de red. Puede que otra aplicación lo esté usando." },
                { "Or open {0} on your phone", "O abre {0} en tu móvil" },
                { "Waiting for your phone…", "Esperando a tu móvil…" },
                { "That PIN doesn't match. Check the PIN on your phone.", "Ese PIN no coincide. Comprueba el PIN de tu móvil." },
                { "Too many wrong PINs. Start pairing again on your phone.", "Demasiados PIN incorrectos. Vuelve a empezar la vinculación en tu móvil." },
                { "No phone is showing a PIN yet. Open the page on your phone and tap Pair.", "Ningún móvil muestra un PIN todavía. Abre la página en tu móvil y toca Vincular." },
                { "Your phone is showing a PIN. Type it here.", "Tu móvil muestra un PIN. Escríbelo aquí." },
                { "1. Scan this code with your phone's camera (it needs to be on the same Wi-Fi as this PC) and tap Pair.", "1. Escanea este código con la cámara de tu móvil (tiene que estar en la misma Wi-Fi que este PC) y toca Vincular." },
                { "2. Your phone shows a 6-digit PIN. Type it below.", "2. Tu móvil muestra un PIN de 6 dígitos. Escríbelo abajo." },
                { "Pair", "Vincular" },
                { "PiP Studio closed unexpectedly", "PiP Studio se cerró inesperadamente" },
                { "Click to send a crash report, so it can be fixed.", "Haz clic para enviar un informe de error y que se pueda arreglar." },
                { "Sending this report helps get it fixed. It opens a new issue on GitHub in your browser with this already filled in, so you can check it, add what you were doing, and send it yourself. Your Windows user name and PC name are left out.", "Enviar este informe ayuda a arreglarlo. Abre una nueva incidencia en GitHub en tu navegador con esto ya rellenado, para que puedas revisarlo, añadir lo que estabas haciendo y enviarlo tú mismo. Tu nombre de usuario de Windows y el nombre del PC no se incluyen." },
                { "Send report", "Enviar informe" },
                { "Copy report", "Copiar informe" },
                { "Report a problem", "Informar de un problema" },
                { "Opens a bug report on GitHub with your PiP Studio and Windows versions and recent errors filled in", "Abre un informe de error en GitHub con tus versiones de PiP Studio y Windows y los errores recientes ya rellenados" },
                { "Report", "Informar" },
                { "Copied", "Copiado" },
                { "Controller controls on · The game runs as admin, so it still gets the controller", "Controles con mando activados · El juego se ejecuta como administrador, así que sigue recibiendo el mando" },
                { "The game runs as administrator", "El juego se ejecuta como administrador" },
                { "So it keeps getting your controller. Click to restart PiP Studio as administrator, which fixes that.", "Así que sigue recibiendo tu mando. Haz clic para reiniciar PiP Studio como administrador, lo que lo soluciona." },
                { "Always start as administrator", "Iniciar siempre como administrador" },
                { "Without asking each time, also at sign-in. For games and apps that run as administrator: PiP Studio can then show their windows and take their focus for controller controls. Windows asks once to set it up.", "Sin preguntar cada vez, también al iniciar sesión. Para juegos y aplicaciones que se ejecutan como administrador: así PiP Studio puede mostrar sus ventanas y quitarles el foco para los controles con mando. Windows lo pregunta una vez para configurarlo." },
                { "Restart as administrator now?", "¿Reiniciar como administrador ahora?" },
                { "From now on PiP Studio starts as administrator without asking, also when it starts at sign-in.", "A partir de ahora PiP Studio se inicia como administrador sin preguntar, también cuando se inicia al iniciar sesión." },
                { "Phone", "Móvil" },
                { "Paired phones", "Móviles vinculados" },
                { "No phones are paired yet. Press Pair a phone above to add one.", "Todavía no hay ningún móvil vinculado. Pulsa Vincular un móvil arriba para añadir uno." },
                { "Rename", "Cambiar nombre" },
                { "Rename phone", "Cambiar el nombre del móvil" },
                { "The name shows here, so you can tell your phones apart.", "El nombre aparece aquí, para que puedas distinguir tus móviles." },
                { "Save", "Guardar" },
                { "Not in the Microsoft Store version", "No está en la versión de Microsoft Store" },
                { "The phone companion needs network access the Store version doesn't have. The installer and portable versions from GitHub include it.", "El compañero para el móvil necesita acceso a la red que la versión de la Store no tiene. Las versiones con instalador y portátil de GitHub lo incluyen." },
                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "Tu móvil se convierte en un mando a distancia para PiP Studio: mueve y cambia el tamaño de los PiP, cambia lo que muestran y ajusta el volumen de cada aplicación desde el navegador del móvil en la Wi-Fi de casa. Nada pasa por Internet y todo lo que va entre el móvil y el PC está cifrado." },
                { "Pairing a phone", "Vincular un móvil" },
                { "Like pairing Moonlight with Sunshine: scan the code, tap Pair on your phone, and type the PIN it shows into PiP Studio. The PIN only matches when nothing sits between the two, and only paired phones can connect. Remove a phone any time.", "Como vincular Moonlight con Sunshine: escanea el código, toca Vincular en tu móvil y escribe en PiP Studio el PIN que muestra. El PIN solo coincide si no hay nada entre los dos, y solo los móviles vinculados pueden conectarse. Quita un móvil cuando quieras." },
                { "Type the phone's PIN", "Escribe el PIN del móvil" },
                { "Light, dark or OLED (black instead of grey, great on OLED screens) for PiP Studio's windows and menus, or follow Windows.", "Claro, oscuro u OLED (negro en lugar de gris, ideal para pantallas OLED) para las ventanas y los menús de PiP Studio, o seguir a Windows." },
                { "Light, dark or OLED black, for PiP Studio's windows and menus", "Claro, oscuro o negro OLED, para las ventanas y los menús de PiP Studio" },
