                { "Accent color", "Couleur d'accentuation" },
                { "The color of highlights, switches, the focus ring and borders. Use Windows' color or pick your own.", "La couleur des surbrillances, interrupteurs, du contour de focus et des bordures. Utilisez la couleur de Windows ou choisissez la vôtre." },
                { "Borders, highlights and controller hints", "Bordures, surbrillances et indications de la manette" },
                { "Use my Windows accent color", "Utiliser la couleur d'accentuation de Windows" },
                { "Custom accent color", "Couleur d'accentuation personnalisée" },
                { "Used when the Windows accent color is off", "Utilisée quand la couleur d'accentuation de Windows est désactivée" },
                { "Rounded corners", "Coins arrondis" },
                { "Square or rounded corners, like other Windows 11 windows.", "Coins droits ou arrondis, comme les autres fenêtres de Windows 11." },
                { "Windows 11 only", "Windows 11 uniquement" },
                { "Border", "Bordure" },
                { "A thin outline around each PiP, in your accent color or one you pick.", "Un fin contour autour de chaque PiP, dans votre couleur d'accentuation ou celle de votre choix." },
                { "A thin outline around each PiP, in your accent color or one you pick", "Un fin contour autour de chaque PiP, dans votre couleur d'accentuation ou celle de votre choix" },
                { "An outline around each PiP", "Un contour autour de chaque PiP" },
                { "Border color", "Couleur de la bordure" },
                { "Match accent color", "Comme la couleur d'accentuation" },
                { "Used when Match accent color is off", "Utilisée quand Comme la couleur d'accentuation est désactivé" },
                { "Width", "Épaisseur" },
                { "Messages under the PiP", "Messages sous le PiP" },
                { "When you switch sources or change a mode, the message shows below the PiP instead of over the picture", "Quand vous changez de source ou de mode, le message s'affiche sous le PiP plutôt que sur l'image" },
                { "When you switch sources or change a mode, the message shows in a small caption below the PiP instead of over the picture. Volume changes show a level bar there too.", "Quand vous changez de source ou de mode, le message s'affiche dans une petite légende sous le PiP plutôt que sur l'image. Les changements de volume y affichent aussi une barre de niveau." },
                { "Show messages below the PiP, not on it", "Afficher les messages sous le PiP, pas dessus" },
                { "Lite mode", "Mode léger" },
                { "For slower PCs: turns off animations, the Mica background, shadows and live previews", "Pour les PC plus lents : désactive les animations, le fond Mica, les ombres et les aperçus en direct" },
                { "For slower PCs: turns off animations, the Mica background, shadows and live previews. PiPs themselves work the same.", "Pour les PC plus lents : désactive les animations, le fond Mica, les ombres et les aperçus en direct. Les PiP fonctionnent de la même façon." },
                { "Fewer effects, for slower PCs", "Moins d'effets, pour les PC plus lents" },
                { "Animation effects", "Animations" },
                { "Glide, fade and slide effects in PiP Studio and on PiPs", "Effets de glissement et de fondu dans PiP Studio et sur les PiP" },
                { "Glide, fade and slide effects in PiP Studio and on PiPs. Off, things jump straight into place.", "Effets de glissement et de fondu dans PiP Studio et sur les PiP. Désactivés, tout se met directement en place." },
                { "Glide and fade effects", "Effets de glissement et de fondu" },
