                { "Size limits", "Limites de taille" },
                { "Keep tall or wide apps from getting too big. Applies to new PiPs, size presets, resizing and source changes (theater mode ignores them).", "Empêche les applications hautes ou larges de devenir trop grandes. S'applique aux nouveaux PiP, aux tailles prédéfinies, au redimensionnement et aux changements de source (le mode cinéma les ignore)." },
                { "Tall or wide apps stop growing at the size you set, as a share of the screen. Applies to new PiPs, size presets, resizing and source changes. Theater mode ignores them.", "Les applications hautes ou larges arrêtent de grandir à la taille choisie, en part de l'écran. S'applique aux nouveaux PiP, aux tailles prédéfinies, au redimensionnement et aux changements de source. Le mode cinéma les ignore." },
                { "Stop tall or wide apps getting too big", "Empêcher les applications hautes ou larges de devenir trop grandes" },
                { "Limit width", "Limiter la largeur" },
                { "Maximum width", "Largeur maximale" },
                { "Limit height", "Limiter la hauteur" },
                { "Maximum height", "Hauteur maximale" },
                { "Share of the screen", "Part de l'écran" },
                { "Control other apps' PiP windows", "Contrôler les fenêtres PiP des autres applications" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture window of Chrome, Edge, Firefox and other apps.", "Quand aucun PiP de PiP Studio n'est ouvert, vos raccourcis et votre manette déplacent, redimensionnent, estompent, coupent le son et ferment la fenêtre picture-in-picture de Chrome, Edge, Firefox et d'autres applications." },
                { "Steer browser and app PiPs too", "Contrôle aussi les PiP des navigateurs et des applications" },
                { "Snap other apps' PiPs to spots", "Aimanter les PiP des autres applications aux emplacements" },
                { "Other apps' PiP windows land on the same corners and edge spots as PiP Studio's PiPs, when they open and when you let go of them after dragging.", "Les fenêtres PiP des autres applications se placent dans les mêmes coins et bords que les PiP de PiP Studio, à leur ouverture et quand vous les lâchez après les avoir déplacées." },
                { "They land on the same spots as yours", "Elles se placent aux mêmes emplacements que les vôtres" },
                { "Allow more than one PiP at a time", "Autoriser plusieurs PiP à la fois" },
                { "When off, opening a new PiP switches the one that's already open", "Désactivé, ouvrir un nouveau PiP change celui qui est déjà ouvert" },
                { "Off: a new PiP replaces the open one", "Désactivé : un nouveau PiP remplace celui qui est ouvert" },
                { "Follow the window I just left", "Suivre la fenêtre que je viens de quitter" },
                { "When you switch windows, the PiP switches to the one you were on", "Quand vous changez de fenêtre, le PiP passe à celle que vous utilisiez" },
                { "The PiP shows the window you just left", "Le PiP affiche la fenêtre que vous venez de quitter" },
                { "Snap after moving", "Aimanter après un déplacement" },
                { "Glides to the nearest spot when you let go", "Glisse vers l'emplacement le plus proche quand vous le lâchez" },
                { "Middle of each edge too", "Aussi le milieu de chaque bord" },
                { "8 spots instead of 4 corners — also used by the arrow keys and D-pad", "8 emplacements au lieu de 4 coins — utilisés aussi par les flèches et la croix directionnelle" },
                { "Gap from the screen edges", "Écart avec les bords de l'écran" },
                { "Gap from the edges", "Écart avec les bords" },
                { "Stay on one display", "Rester sur un seul écran" },
                { "Moving past the edge won't hop to the next display", "Dépasser le bord ne fait pas passer à l'écran suivant" },
                { "Don't hop to the next display", "Ne pas passer à l'écran suivant" },
                { "When the pointer is over a PiP", "Quand le pointeur est sur un PiP" },
                { "What a PiP does when you point at it", "Ce que fait un PiP quand vous le pointez" },
                { "Move out of the way slides it aside — hold Ctrl to grab it instead", "S'écarter le fait glisser de côté — maintenez Ctrl pour l'attraper" },
                { "Show controls", "Afficher les commandes" },
                { "Fade out", "S'estomper" },
                { "Do nothing", "Ne rien faire" },
                { "Move out of the way", "S'écarter" },
                { "Show move arrows", "Afficher les flèches de déplacement" },
                { "Arrow buttons send the PiP to the next spot — or the next display", "Les boutons fléchés envoient le PiP à l'emplacement suivant — ou à l'écran suivant" },
                { "Arrow buttons that hop to the next spot", "Boutons fléchés qui passent à l'emplacement suivant" },
                { "Fade-out opacity", "Opacité estompée" },
                { "How visible a PiP stays while it fades under the pointer", "À quel point un PiP reste visible quand il s'estompe sous le pointeur" },
                { "How see-through it gets", "À quel point il devient transparent" },
                { "Click-through opacity", "Opacité en mode clics traversants" },
                { "How visible a ghost-mode PiP is under the pointer", "À quel point un PiP en mode fantôme est visible sous le pointeur" },
                { "How see-through ghost mode is", "À quel point le mode fantôme est transparent" },
                { "Right-click on a PiP", "Clic droit sur un PiP" },
                { "Show the menu", "Afficher le menu" },
                { "Close it", "Le fermer" },
                { "Bring its source to the front", "Mettre sa source au premier plan" },
                { "Theater mode", "Mode cinéma" },
                { "Middle-click closes a PiP", "Le clic du milieu ferme un PiP" },
                { "Hide a PiP while its window is in front", "Masquer un PiP quand sa fenêtre est au premier plan" },
                { "It would only repeat what's already on screen", "Il ne ferait que répéter ce qui est déjà à l'écran" },
                { "Hide PiPs while a fullscreen app is on the same display", "Masquer les PiP quand une application plein écran est sur le même écran" },
                { "Borderless games still show PiPs unless this is on", "Les jeux sans bordure affichent toujours les PiP sauf si ceci est activé" },
                { "Includes borderless games", "Y compris les jeux sans bordure" },
                { "Keep minimized sources playing", "Garder les sources réduites en lecture" },
                { "The PiP keeps moving when you minimize", "Le PiP continue de bouger quand vous réduisez la fenêtre" },
                { "Reconnect when a closed app opens again", "Se reconnecter quand une application fermée se rouvre" },
                { "Window sources always run at full speed", "Les sources de fenêtre tournent toujours à pleine vitesse" },
                { "Frame rate", "Fréquence d'images" },
                { "Show the pointer", "Afficher le pointeur" },
                { "Use game controllers", "Utiliser les manettes de jeu" },
                { "Xbox, PlayStation, Switch and most others", "Xbox, PlayStation, Switch et la plupart des autres" },
                { "Turn controls on when PiP Studio starts", "Activer les commandes au démarrage de PiP Studio" },
                { "Release the game's focus while controls are on", "Retirer le focus au jeu pendant que les commandes sont activées" },
                { "The game ignores the controller while you move the PiP, and gets focus back afterwards", "Le jeu ignore la manette pendant que vous déplacez le PiP, puis récupère le focus" },
                { "The game ignores the controller meanwhile", "Le jeu ignore la manette pendant ce temps" },
                { "Show button hints on the PiP", "Afficher les indications de boutons sur le PiP" },
                { "Controller-friendly mode", "Mode adapté à la manette" },
                { "Bigger layout and button hints", "Mise en page plus grande et indications de boutons" },
                { "Bigger layout, a focus ring and button hints, so you can use this window with a controller. Pressing a key on the keyboard switches back.", "Une mise en page plus grande, un contour de focus et des indications de boutons, pour utiliser cette fenêtre avec une manette. Appuyer sur une touche du clavier revient à la normale." },
                { "When I use a controller", "Quand j'utilise une manette" },
                { "Always", "Toujours" },
                { "Off", "Désactivé" },
                { "Fade controller hints when idle", "Estomper les indications de la manette au repos" },
                { "Hints fade after a few seconds", "Les indications s'estompent après quelques secondes" },
                { "The PiP's name and button hints fade after a few seconds without input. Any button brings them back. Less for Windows to draw over your game.", "Le nom du PiP et les indications de boutons s'estompent après quelques secondes sans action. N'importe quel bouton les fait revenir. Windows a moins à dessiner par-dessus votre jeu." },
                { "Controller options", "Options de la manette" },
                { "Button assignments", "Affectation des boutons" },
                { "Click, then press a button. Right-click clears it.", "Cliquez, puis appuyez sur un bouton. Le clic droit l'efface." },
                { "Click a binding, then press the button or combination. Right-click clears it. Trigger: press, double press or hold.", "Cliquez sur une affectation, puis appuyez sur le bouton ou la combinaison. Le clic droit l'efface. Déclenchement : appui, double appui ou maintien." },
                { "Click, then press the button(s). Right-click to clear.", "Cliquez, puis appuyez sur le ou les boutons. Clic droit pour effacer." },
                { "Press once, press twice quickly, or hold", "Appuyer une fois, deux fois rapidement, ou maintenir" },
                { "Press", "Appui" },
                { "Double press", "Double appui" },
                { "Hold", "Maintien" },
                { "Reset", "Réinitialiser" },
                { "Connect a controller", "Connectez une manette" },
                { "Press button(s)…", "Appuyez sur le ou les boutons…" },
                { "No controller connected", "Aucune manette connectée" },
                { "No controller found", "Aucune manette trouvée" },
                { "Connect an Xbox, PlayStation or Switch controller by USB or Bluetooth.", "Connectez une manette Xbox, PlayStation ou Switch en USB ou en Bluetooth." },
                { "Connect an Xbox, PlayStation or Switch controller to use controller controls.", "Connectez une manette Xbox, PlayStation ou Switch pour utiliser les commandes à la manette." },
                { "Controls are on — the PiP has an accent outline. {0} turns them off.", "Les commandes sont activées — le PiP a un contour de couleur d'accentuation. {0} les désactive." },
                { "Press {0} to turn controls on.", "Appuyez sur {0} pour activer les commandes." },
                { "Controller controls", "Commandes à la manette" },
                { "Controller controls on · {0} turns them off", "Commandes à la manette activées · {0} les désactive" },
                { "Controller controls off", "Commandes à la manette désactivées" },
                { "Controller controls ({0})", "Commandes à la manette ({0})" },
                { "Xbox controller", "Manette Xbox" },
                { "PlayStation controller", "Manette PlayStation" },
                { "Switch controller", "Manette Switch" },
                { "These work anywhere in Windows. Click a shortcut, then press the new keys (Backspace clears, Esc cancels). Right-click clears it. They act on the PiP you used or pointed at most recently.", "Ils fonctionnent partout dans Windows. Cliquez sur un raccourci, puis appuyez sur les nouvelles touches (Retour arrière efface, Échap annule). Le clic droit l'efface. Ils agissent sur le PiP que vous avez utilisé ou pointé en dernier." },
                { "Open and choose", "Ouvrir et choisir" },
                { "Move and size", "Déplacer et redimensionner" },
                { "Look and visibility", "Aspect et visibilité" },
                { "Source and media", "Source et médias" },
                { "Click, then press keys. Right-click to clear.", "Cliquez, puis appuyez sur les touches. Clic droit pour effacer." },
                { "Reset shortcuts", "Réinitialiser les raccourcis" },
                { "Puts every shortcut back to its default", "Remet chaque raccourci à sa valeur par défaut" },
                { "Start PiP Studio when I sign in", "Démarrer PiP Studio à l'ouverture de session" },
                { "It starts quietly in the tray", "Il démarre discrètement dans la zone de notification" },
                { "Bring back my PiPs when PiP Studio starts", "Rétablir mes PiP au démarrage de PiP Studio" },
                { "Tips and alerts from the tray icon", "Conseils et alertes de l'icône de la zone de notification" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "Masquer les PiP des captures, enregistrements et partages d'écran" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "OBS, Discord, Teams et l'Outil Capture d'écran ne les verront pas. Cela coûte un peu de performances, laissez-le donc désactivé sauf si vous diffusez ou partagez votre écran." },
                { "Costs a little performance", "Coûte un peu de performances" },
                { "Keep running in the tray when I close this window", "Rester dans la zone de notification quand je ferme cette fenêtre" },
                { "Otherwise closing this window quits PiP Studio", "Sinon, fermer cette fenêtre quitte PiP Studio" },
                { "Release memory while idle", "Libérer la mémoire au repos" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "Rend à Windows la mémoire inutilisée pendant que PiP Studio est dans la zone de notification" },
                { "Give memory back while in the tray", "Rendre la mémoire dans la zone de notification" },
                { "Running as administrator", "Exécution en tant qu'administrateur" },
                { "PiP Studio can show windows of apps that run as administrator", "PiP Studio peut afficher les fenêtres des applications exécutées en administrateur" },
                { "Can show admin apps' windows", "Peut afficher les fenêtres des applications administrateur" },
                { "Restart as administrator", "Redémarrer en tant qu'administrateur" },
                { "Needed only to show windows of apps that run as administrator", "Nécessaire uniquement pour afficher les fenêtres des applications exécutées en administrateur" },
                { "Only needed for admin apps' windows", "Nécessaire uniquement pour les fenêtres des applications administrateur" },
                { "Needs administrator", "Nécessite l'administrateur" },
                { "Version {0}", "Version {0}" },
                { "Exit PiP Studio", "Quitter PiP Studio" },
                { "Settings folder", "Dossier des paramètres" },
                { "Open", "Ouvrir" },
                { "Picture-in-picture for any window or part of the screen", "Picture-in-picture pour n'importe quelle fenêtre ou partie de l'écran" },
                { "Uses Windows' own live thumbnails", "Utilise les miniatures en direct de Windows" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "La recopie de fenêtres en direct utilise le système de miniatures de Windows, elle ne coûte donc presque rien." },
                { "Select", "Sélectionner" },
                { "Back", "Retour" },
                { "Tabs", "Onglets" },
                { "Search", "Rechercher" },
                { "Scroll", "Défiler" },
                { "Type", "Saisir" },
                { "Space", "Espace" },
                { "Clear", "Effacer" },
                { "Done", "Terminé" },
                { "Snap spots", "Emplacements d'aimantation" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "Quand vous lâchez un PiP, il glisse vers l'emplacement le plus proche : les 4 coins, plus le milieu de chaque bord avec 8 emplacements activés. Les flèches et la croix directionnelle utilisent les mêmes emplacements." },
                { "How far a PiP sits from the edges of the screen.", "À quelle distance des bords de l'écran se place un PiP." },
                { "Where new PiPs open", "Où s'ouvrent les nouveaux PiP" },
                { "A new PiP pops up in the corner you pick here.", "Un nouveau PiP apparaît dans le coin que vous choisissez ici." },
                { "Size of new PiPs", "Taille des nouveaux PiP" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "Un PiP peut afficher ses commandes, s'estomper, ne rien faire ou s'écarter quand le pointeur l'atteint. Quand il s'écarte, maintenez Ctrl pour l'attraper. L'opacité estompée règle sa transparence." },
                { "Move arrows", "Flèches de déplacement" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "Les boutons fléchés du PiP l'envoient à l'emplacement suivant ou sur l'écran suivant." },
                { "Ghost mode", "Mode fantôme" },
                { "Clicks go straight through the PiP to the window behind it.", "Les clics traversent le PiP jusqu'à la fenêtre derrière." },
                { "Follow the window you left", "Suivre la fenêtre quittée" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "Quand vous changez de fenêtre, le PiP passe à celle que vous utilisiez, pour que la fenêtre quittée reste visible. Les PiP Auto le font toujours." },
                { "Hide while its window is in front", "Masquer quand sa fenêtre est au premier plan" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "Inutile d'afficher une fenêtre deux fois : le PiP s'efface pendant que vous êtes dans sa fenêtre." },
                { "Hide over full-screen apps", "Masquer sur les applications plein écran" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "Les PiP d'un écran s'effacent pendant qu'une application ou un jeu plein écran y tourne." },
                { "How see-through a new PiP is.", "À quel point un nouveau PiP est transparent." },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "Un grand PiP centré pour bien regarder. Appuyez de nouveau pour revenir." },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "Réduire une source la place hors de l'écran pour que le PiP continue de bouger. Cliquez dessus dans la barre des tâches pour la faire revenir." },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "Ce que fait un clic droit sur un PiP : ouvrir son menu, le fermer, afficher sa fenêtre, le mode cinéma, ou rien." },
                { "More than one PiP", "Plusieurs PiP" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "Activé : chaque nouveau PiP s'ouvre à côté des autres. Désactivé : ouvrir un nouveau PiP fait passer celui qui est ouvert à la nouvelle fenêtre." },
                { "Other apps' PiPs", "PiP des autres applications" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "Quand aucun PiP de PiP Studio n'est ouvert, vos raccourcis et votre manette déplacent, redimensionnent, estompent, coupent le son et ferment les fenêtres picture-in-picture de Chrome, Edge, Firefox, Discord et d'autres applications. Elles se placent aussi aux mêmes emplacements que vos PiP, à leur ouverture et quand vous les lâchez après les avoir déplacées." },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "Déplacez, redimensionnez et changez les PiP avec une manette Xbox, PlayStation, Switch ou presque n'importe quelle autre. Avec Retirer le focus au jeu activé, le jeu ignore la manette pendant que vous pilotez le PiP, puis récupère le focus. Les indications montrent ce que fait chaque bouton et s'estompent après quelques secondes d'inactivité." },
                { "Shows controls", "Affiche les commandes" },
                { "Fades to {0}%", "S'estompe à {0} %" },
                { "Nothing happens", "Rien ne se passe" },
                { "Moves out of the way", "S'écarte" },
                { "Glides into place", "Glisse en place" },
                { "Jumps into place", "Se met en place directement" },
                { "Max height {0}%", "Hauteur max. {0} %" },
                { "Max width {0}%", "Largeur max. {0} %" },
