                { "Right-click: close", "Clic droit : fermer" },
                { "Right-click: show its window", "Clic droit : afficher sa fenêtre" },
                { "Right-click: theater mode", "Clic droit : mode cinéma" },
                { "Right-click: nothing", "Clic droit : rien" },
