                { "Enter or double-click to confirm  ·  Esc to cancel  ·  F = everything  ·  Shape: 1 Free  2 16:9  3 4:3  4 1:1  5 9:16  (now: {0})", "Entrée ou double-clic pour confirmer  ·  Échap pour annuler  ·  F = tout  ·  Forme : 1 Libre  2 16:9  3 4:3  4 1:1  5 9:16  (actuellement : {0})" },
                { "8 spots instead of 4 corners", "8 emplacements au lieu de 4 coins" },
