                { "Largest size", "Taille maximale" },
                { "Smallest size", "Taille minimale" },
                { "Eight sizes from Extra small to Extra large, set by width so a PiP keeps its shape. Bigger and Smaller step through the same sizes. Your choice is highlighted.", "Huit tailles, de Très petit à Très grand, définies par la largeur pour que le PiP garde sa forme. Plus grand et Plus petit parcourent les mêmes tailles. Votre choix est mis en évidence." },
                { "Extra small", "Très petit" },
                { "Pick a window or a display for this PiP", "Choisissez une fenêtre ou un écran pour ce PiP" },
                { "Show in this PiP", "Afficher dans ce PiP" },
                { "No preview for this window", "Pas d'aperçu pour cette fenêtre" },
                { "This window has closed", "Cette fenêtre a été fermée" },
                { "It opens in a floating picture-in-picture window", "Elle s'ouvre dans une fenêtre picture-in-picture flottante" },
                { "No matching windows", "Aucune fenêtre correspondante" },
                { "Choose a window", "Choisir une fenêtre" },
                { "Title bar buttons", "Boutons de la barre de titre" },
                { "Pick the buttons on a PiP's title bar and their order", "Choisissez les boutons de la barre de titre d'un PiP et leur ordre" },
                { "Always shown, so the full menu is never out of reach", "Toujours affiché, pour que le menu complet reste toujours accessible" },
                { "Reset title bar buttons", "Réinitialiser les boutons de la barre de titre" },
                { "Back to the default buttons and order", "Revenir aux boutons et à l'ordre par défaut" },
                { "The buttons a PiP's title bar shows when you point at it, in your order. Previous and Next window switch what the PiP shows, and Bigger and Smaller step through the sizes. More options always stays, so the full menu is never out of reach. On a narrow PiP, buttons on the left make room first.", "Les boutons qu'affiche la barre de titre d'un PiP quand vous le pointez, dans votre ordre. Fenêtre précédente et suivante changent ce qu'affiche le PiP, et Plus grand et Plus petit parcourent les tailles. Plus d'options reste toujours là, pour que le menu complet soit toujours accessible. Sur un PiP étroit, les boutons de gauche laissent la place en premier." },
                { "Treat as a PiP", "Traiter comme un PiP" },
                { "Not a PiP", "Pas un PiP" },
                { "Find other apps' PiPs automatically", "Détecter automatiquement les PiP des autres applications" },
                { "Small always-on-top windows, like video players' mini modes, count as PiPs. Mark one as Not a PiP on the Running PiPs page.", "Les petites fenêtres toujours au premier plan, comme les mini-lecteurs vidéo, comptent comme des PiP. Marquez-en une comme Pas un PiP dans la page PiP ouverts." },
                { "Windows you marked", "Fenêtres que vous avez marquées" },
                { "Forget every Treat as a PiP and Not a PiP you chose", "Oublier tous les Traiter comme un PiP et Pas un PiP que vous avez choisis" },
                { "Find other apps' PiPs", "Détecter les PiP des autres applications" },
                { "PiP options", "Options du PiP" },
                { "Shape", "Forme" },
                { "Black bars", "Bandes noires" },
                { "Snapping", "Aimantation" },
                { "Match the picture", "Comme l'image" },
                { "Follow my setting", "Suivre mon réglage" },
                { "Always snap to spots", "Toujours aimanter aux emplacements" },
                { "Never snap", "Ne jamais aimanter" },
                { "No sound from this app right now", "Aucun son de cette application pour l'instant" },
                { "Crops away the bars around the video", "Rogne les bandes autour de la vidéo" },
                { "Fits the window to the video so the bars disappear", "Ajuste la fenêtre à la vidéo pour faire disparaître les bandes" },
                { "Snapping follows Settings", "L'aimantation suit les paramètres" },
                { "Snaps to spots", "S'aimante aux emplacements" },
                { "Doesn't snap", "Ne s'aimante pas" },
                { "Showing the whole picture", "Affichage de l'image entière" },
                { "Couldn't look at the source right now", "Impossible d'examiner la source pour l'instant" },
                { "No black bars found", "Aucune bande noire trouvée" },
                { "Black bars removed", "Bandes noires retirées" },
                { "Removing black bars", "Retrait des bandes noires" },
                { "Black bars left alone", "Bandes noires laissées telles quelles" },
                { "Updates", "Mises à jour" },
                { "What's new", "Nouveautés" },
                { "Check now", "Vérifier maintenant" },
                { "Update now", "Mettre à jour maintenant" },
                { "Check for updates automatically", "Rechercher les mises à jour automatiquement" },
                { "Once a day, on GitHub. Nothing about you or your PC is sent.", "Une fois par jour, sur GitHub. Rien sur vous ou votre PC n'est envoyé." },
                { "Checking for updates…", "Recherche de mises à jour…" },
                { "You're up to date (version {0})", "Vous êtes à jour (version {0})" },
                { "Version {0} is available", "La version {0} est disponible" },
                { "Downloading the update… {0}%", "Téléchargement de la mise à jour… {0} %" },
                { "Installing the update…", "Installation de la mise à jour…" },
                { "You have version {0}", "Vous avez la version {0}" },
                { "The update didn't work", "La mise à jour n'a pas fonctionné" },
                { "Update available", "Mise à jour disponible" },
                { "PiP Studio {0} is out. Click to update.", "PiP Studio {0} est sorti. Cliquez pour mettre à jour." },
                { "PiP Studio was updated", "PiP Studio a été mis à jour" },
                { "You're now on version {0}.", "Vous êtes maintenant en version {0}." },
                { "Update to version {0}…", "Mettre à jour vers la version {0}…" },
                { "Couldn't reach GitHub. Check your internet connection and try again.", "Impossible de joindre GitHub. Vérifiez votre connexion Internet et réessayez." },
                { "The download was damaged (its fingerprint doesn't match). Please try again.", "Le téléchargement est endommagé (son empreinte ne correspond pas). Veuillez réessayer." },
                { "Show controls on other apps' PiPs", "Afficher les commandes sur les PiP des autres applications" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "Pointez le PiP d'une autre application pour faire apparaître la barre de titre de PiP Studio dessus : faites-la glisser pour déplacer le PiP, faites défiler dessus pour changer le volume, et utilisez les boutons de barre de titre que vous avez choisis." },
                { "Controls on other apps' PiPs", "Commandes sur les PiP des autres applications" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "Pointez la fenêtre PiP de Chrome, Firefox, Discord ou d'une autre application et la barre de titre de PiP Studio apparaît sur son bord supérieur. Faites glisser la barre pour déplacer le PiP, faites défiler dessus pour changer le volume, réduisez-le, et utilisez les mêmes boutons que la barre de titre de vos PiP : afficher l'application, mode cinéma, plus grand, plus petit, coin suivant, fermer et plus. Le reste du PiP fonctionne comme d'habitude." },
                { "Show {0}", "Afficher {0}" },
                { "Options in PiP Studio", "Options dans PiP Studio" },
                { "Minimize", "Réduire" },
                { "Restore", "Restaurer" },
                { "Restore {0}'s PiP", "Restaurer le PiP de {0}" },
                { "PiP Studio's title bar appears", "La barre de titre de PiP Studio apparaît" },
                { "Your video", "Votre vidéo" },
                { "Remove", "Retirer" },
                { "Remove all", "Tout retirer" },
                { "Marked as PiPs", "Marquées comme PiP" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "Les fenêtres que vous avez choisi de traiter comme des PiP. En retirer une en refait une fenêtre normale, qui ne reste plus au premier plan." },
                { "Treat this window as a PiP?", "Traiter cette fenêtre comme un PiP ?" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "PiP Studio la gérera comme la fenêtre picture-in-picture d'une autre application :" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  Elle passe dans PiP ouverts et s'aimante aux emplacements de PiP" },
                { "•  It stays on top of your other windows once you move or steer it", "•  Elle reste au-dessus de vos autres fenêtres dès que vous la déplacez ou la pilotez" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  Vos raccourcis de PiP et votre manette la déplacent, la redimensionnent, l'estompent et la ferment" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Cela s'applique à toutes les fenêtres de ce type de {0}, maintenant et plus tard. Vous pouvez l'annuler à tout moment dans PiP ouverts > Marquées comme PiP, ce qui la retire aussi du premier plan permanent." },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Cela s'applique uniquement à cette fenêtre, jusqu'à sa fermeture. Vous pouvez l'annuler à tout moment dans PiP ouverts > Marquées comme PiP, ce qui la retire aussi du premier plan permanent." },
                { "Remove every mark?", "Retirer toutes les marques ?" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "Toutes les fenêtres marquées avec Traiter comme un PiP redeviennent des fenêtres normales et ne restent plus au premier plan." },
                { "Every window like this from {0}", "Toutes les fenêtres de ce type de {0}" },
                { "{0} · this window only, until it closes", "{0} · cette fenêtre seulement, jusqu'à sa fermeture" },
                { "Phone companion", "Compagnon sur téléphone" },
                { "Control PiP Studio from your phone", "Contrôler PiP Studio depuis votre téléphone" },
                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "Gérez vos PiP et le volume de chaque application depuis le navigateur de votre téléphone, sur le Wi-Fi de la maison. Windows peut vous demander d'autoriser PiP Studio sur les réseaux privés." },
                { "Pair a phone", "Associer un téléphone" },
                { "Turn on the switch above first", "Activez d'abord l'interrupteur ci-dessus" },
                { "This PC isn't on a network right now", "Ce PC n'est connecté à aucun réseau pour l'instant" },
                { "Your phone opens {0}", "Votre téléphone ouvre {0}" },
                { "Not used since PiP Studio started", "Pas utilisé depuis le démarrage de PiP Studio" },
                { "Last used {0}", "Dernière utilisation {0}" },
                { "Remove {0}?", "Retirer {0} ?" },
                { "It stops working right away. You can pair it again any time.", "Il cesse de fonctionner tout de suite. Vous pouvez l'associer de nouveau quand vous voulez." },
                { "No network", "Pas de réseau" },
                { "PiP Studio can't find this PC's address on your local network. Connect to Wi-Fi or Ethernet and try again.", "PiP Studio ne trouve pas l'adresse de ce PC sur votre réseau local. Connectez-vous au Wi-Fi ou à Ethernet et réessayez." },
                { "Paired with {0}. You can close this.", "Associé à {0}. Vous pouvez fermer ceci." },
                { "Couldn't open a network port. Another app may be using it.", "Impossible d'ouvrir un port réseau. Une autre application l'utilise peut-être." },
                { "Or open {0} on your phone", "Ou ouvrez {0} sur votre téléphone" },
                { "Waiting for your phone…", "En attente de votre téléphone…" },
                { "That PIN doesn't match. Check the PIN on your phone.", "Ce PIN ne correspond pas. Vérifiez le PIN sur votre téléphone." },
                { "Too many wrong PINs. Start pairing again on your phone.", "Trop de PIN erronés. Recommencez l'association sur votre téléphone." },
                { "No phone is showing a PIN yet. Open the page on your phone and tap Pair.", "Aucun téléphone n'affiche encore de PIN. Ouvrez la page sur votre téléphone et touchez Associer." },
                { "Your phone is showing a PIN. Type it here.", "Votre téléphone affiche un PIN. Saisissez-le ici." },
                { "1. Scan this code with your phone's camera (it needs to be on the same Wi-Fi as this PC) and tap Pair.", "1. Scannez ce code avec l'appareil photo de votre téléphone (il doit être sur le même Wi-Fi que ce PC) et touchez Associer." },
                { "2. Your phone shows a 6-digit PIN. Type it below.", "2. Votre téléphone affiche un PIN à 6 chiffres. Saisissez-le ci-dessous." },
                { "Pair", "Associer" },
                { "PiP Studio closed unexpectedly", "PiP Studio s'est fermé de façon inattendue" },
                { "Click to send a crash report, so it can be fixed.", "Cliquez pour envoyer un rapport de plantage, afin que le problème soit corrigé." },
                { "Sending this report helps get it fixed. It opens a new issue on GitHub in your browser with this already filled in, so you can check it, add what you were doing, and send it yourself. Your Windows user name and PC name are left out.", "Envoyer ce rapport aide à corriger le problème. Il ouvre un nouveau ticket sur GitHub dans votre navigateur avec ceci déjà rempli, pour que vous puissiez le vérifier, ajouter ce que vous faisiez et l'envoyer vous-même. Votre nom d'utilisateur Windows et le nom de votre PC ne sont pas inclus." },
                { "Send report", "Envoyer le rapport" },
                { "Copy report", "Copier le rapport" },
                { "Report a problem", "Signaler un problème" },
                { "Opens a bug report on GitHub with your PiP Studio and Windows versions and recent errors filled in", "Ouvre un rapport de bug sur GitHub avec vos versions de PiP Studio et de Windows et les erreurs récentes déjà remplies" },
                { "Report", "Signaler" },
                { "Copied", "Copié" },
                { "Controller controls on · The game runs as admin, so it still gets the controller", "Commandes à la manette activées · Le jeu tourne en administrateur, il reçoit donc toujours la manette" },
                { "The game runs as administrator", "Le jeu tourne en administrateur" },
                { "So it keeps getting your controller. Click to restart PiP Studio as administrator, which fixes that.", "Il continue donc de recevoir votre manette. Cliquez pour redémarrer PiP Studio en administrateur, ce qui règle le problème." },
                { "Always start as administrator", "Toujours démarrer en tant qu'administrateur" },
                { "Without asking each time, also at sign-in. For games and apps that run as administrator: PiP Studio can then show their windows and take their focus for controller controls. Windows asks once to set it up.", "Sans demander à chaque fois, y compris à l'ouverture de session. Pour les jeux et applications qui tournent en administrateur : PiP Studio peut alors afficher leurs fenêtres et leur retirer le focus pour les commandes à la manette. Windows le demande une fois pour le configurer." },
                { "Restart as administrator now?", "Redémarrer en tant qu'administrateur maintenant ?" },
                { "From now on PiP Studio starts as administrator without asking, also when it starts at sign-in.", "Désormais, PiP Studio démarre en administrateur sans demander, y compris quand il démarre à l'ouverture de session." },
                { "Phone", "Téléphone" },
                { "Paired phones", "Téléphones associés" },
                { "No phones are paired yet. Press Pair a phone above to add one.", "Aucun téléphone n'est encore associé. Appuyez sur Associer un téléphone ci-dessus pour en ajouter un." },
                { "Rename", "Renommer" },
                { "Rename phone", "Renommer le téléphone" },
                { "The name shows here, so you can tell your phones apart.", "Le nom s'affiche ici, pour distinguer vos téléphones." },
                { "Save", "Enregistrer" },
                { "Not in the Microsoft Store version", "Pas dans la version Microsoft Store" },
                { "The phone companion needs network access the Store version doesn't have. The installer and portable versions from GitHub include it.", "Le compagnon sur téléphone a besoin d'un accès réseau que la version du Store n'a pas. Les versions installateur et portable de GitHub l'incluent." },
                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "Votre téléphone devient une télécommande pour PiP Studio : déplacez et redimensionnez les PiP, changez ce qu'ils affichent et réglez le volume de chaque application, depuis le navigateur du téléphone sur le Wi-Fi de la maison. Rien ne passe par Internet, et tout ce qui circule entre le téléphone et le PC est chiffré." },
                { "Pairing a phone", "Associer un téléphone" },
                { "Like pairing Moonlight with Sunshine: scan the code, tap Pair on your phone, and type the PIN it shows into PiP Studio. The PIN only matches when nothing sits between the two, and only paired phones can connect. Remove a phone any time.", "Comme pour associer Moonlight à Sunshine : scannez le code, touchez Associer sur votre téléphone et saisissez dans PiP Studio le PIN qu'il affiche. Le PIN ne correspond que si rien ne s'interpose entre les deux, et seuls les téléphones associés peuvent se connecter. Retirez un téléphone quand vous voulez." },
                { "Type the phone's PIN", "Saisissez le PIN du téléphone" },
                { "Light, dark or OLED (black instead of grey, great on OLED screens) for PiP Studio's windows and menus, or follow Windows.", "Clair, sombre ou OLED (noir au lieu de gris, idéal sur les écrans OLED) pour les fenêtres et les menus de PiP Studio, ou suivre Windows." },
