                { "The game ignores the controller while you move the PiP, and gets focus back afterwards", "PiP を動かしている間はゲームがコントローラーを無視し、その後フォーカスが戻ります" },
                { "The game ignores the controller meanwhile", "その間、ゲームはコントローラーを無視します" },
