                { "Bigger layout and button hints", "大きなレイアウトとボタンのヒント" },
                { "Bigger layout, a focus ring and button hints, so you can use this window with a controller. Pressing a key on the keyboard switches back.", "大きなレイアウト、フォーカス枠、ボタンのヒントで、このウィンドウをコントローラーで操作できます。キーボードのキーを押すと元に戻ります。" },
