                { "Hints fade after a few seconds", "数秒後にヒントが薄くなります" },
                { "The PiP's name and button hints fade after a few seconds without input. Any button brings them back. Less for Windows to draw over your game.", "操作がないと、数秒後に PiP の名前とボタンのヒントが薄くなります。どのボタンでも元に戻ります。ゲームの上に Windows が描くものが減ります。" },
