                { "Click, then press a button. Right-click clears it.", "クリックしてからボタンを押します。右クリックで解除します。" },
                { "Click a binding, then press the button or combination. Right-click clears it. Trigger: press, double press or hold.", "割り当てをクリックしてから、ボタンまたは組み合わせを押します。右クリックで解除します。操作: 押す、2 回押す、長押し。" },
