                { "Switch controller", "Switch コントローラー" },
                { "These work anywhere in Windows. Click a shortcut, then press the new keys (Backspace clears, Esc cancels). Right-click clears it. They act on the PiP you used or pointed at most recently.", "Windows のどこでも使えます。ショートカットをクリックして新しいキーを押します (Backspace で解除、Esc でキャンセル)。右クリックで解除します。最後に使った、またはポインターを合わせた PiP に対して動作します。" },
