                { "Start PiP Studio when I sign in", "サインイン時に PiP Studio を起動" },
                { "It starts quietly in the tray", "トレイで静かに起動します" },
                { "Bring back my PiPs when PiP Studio starts", "PiP Studio の起動時に PiP を復元" },
                { "Tips and alerts from the tray icon", "トレイ アイコンからのヒントとお知らせ" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "スクリーンショット、録画、画面共有に PiP を映さない" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "OBS、Discord、Teams、Snipping Tool には映りません。少しパフォーマンスを使うので、配信や画面共有をしない場合はオフのままにしてください。" },
                { "Costs a little performance", "少しパフォーマンスを使います" },
                { "Keep running in the tray when I close this window", "このウィンドウを閉じてもトレイで動作し続ける" },
                { "Otherwise closing this window quits PiP Studio", "オフの場合、このウィンドウを閉じると PiP Studio が終了します" },
                { "Release memory while idle", "アイドル時にメモリを解放" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "PiP Studio がトレイにある間、使っていないメモリを Windows に返します" },
