                { "Open", "開く" },
                { "Picture-in-picture for any window or part of the screen", "あらゆるウィンドウや画面の一部をピクチャー イン ピクチャーで" },
                { "Uses Windows' own live thumbnails", "Windows 自体のライブ サムネイルを使います" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "ウィンドウのライブ表示には Windows 自体のサムネイルの仕組みを使うので、負荷はほとんどありません。" },
                { "Select", "選択" },
