                { "Space", "スペース" },
                { "Clear", "クリア" },
                { "Done", "完了" },
                { "Snap spots", "スナップ位置" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "PiP を離すと、最も近い位置へスライドします: 4 つの隅に加え、8 か所がオンなら各辺の中央も使います。矢印キーと十字キーも同じ位置を使います。" },
                { "How far a PiP sits from the edges of the screen.", "PiP を画面の端からどれだけ離すか。" },
                { "Where new PiPs open", "新しい PiP を開く場所" },
                { "A new PiP pops up in the corner you pick here.", "新しい PiP はここで選んだ隅に表示されます。" },
                { "Size of new PiPs", "新しい PiP のサイズ" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "ポインターが来たとき、PiP はコントロールを表示する、薄くなる、何もしない、横によける、のいずれかを選べます。よけたときは Ctrl を押したままにするとつかめます。薄くしたときの不透明度で透け具合を決めます。" },
                { "Move arrows", "移動用の矢印" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "PiP の矢印ボタンで、次の位置または次のディスプレイに移動します。" },
                { "Ghost mode", "ゴースト モード" },
                { "Clicks go straight through the PiP to the window behind it.", "クリックが PiP を通り抜けて後ろのウィンドウに届きます。" },
                { "Follow the window you left", "離れたウィンドウに追従" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "ウィンドウを切り替えると、PiP は直前まで使っていたウィンドウに切り替わるので、離れたウィンドウが見えたままになります。自動の PiP は常にこう動作します。" },
                { "Hide while its window is in front", "元のウィンドウが前面にある間は隠す" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "同じウィンドウを 2 回表示しても意味がないので、そのウィンドウを使っている間は PiP が引っ込みます。" },
                { "Hide over full-screen apps", "全画面アプリの上では隠す" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "ディスプレイで全画面のアプリやゲームが動いている間、そのディスプレイの PiP はよけます。" },
                { "How see-through a new PiP is.", "新しい PiP の透け具合。" },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "しっかり見たいときの、大きく中央に表示される PiP。もう一度押すと元に戻ります。" },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "ソースを最小化すると画面外に置かれ、PiP は動き続けます。タスク バーでクリックすると元に戻ります。" },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "PiP を右クリックしたときの動作: メニューを開く、閉じる、元のウィンドウを表示、シアター モード、何もしない。" },
                { "More than one PiP", "複数の PiP" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "オン: 新しい PiP は他の PiP と並んで開きます。オフ: 新しい PiP を開くと、すでに開いている PiP が新しいウィンドウに切り替わります。" },
                { "Other apps' PiPs", "他のアプリの PiP" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "PiP Studio の PiP が開いていないとき、ショートカットとコントローラーで Chrome、Edge、Firefox、Discord などのアプリのピクチャー イン ピクチャー ウィンドウを移動、サイズ変更、フェード、ミュート、終了できます。開いたときやドラッグして離したときも、自分の PiP と同じ位置に移動します。" },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "Xbox、PlayStation、Switch など、ほとんどのコントローラーで PiP を移動、サイズ変更、切り替えできます。「ゲームのフォーカスを外す」がオンなら、PiP を操作している間はゲームがコントローラーを無視し、その後フォーカスが戻ります。ヒントで各ボタンの役割がわかり、数秒操作がないと薄くなります。" },
                { "Shows controls", "コントロールを表示" },
