                { "Always shown, so the full menu is never out of reach", "常に表示されるので、すべてのメニューにいつでもアクセスできます" },
                { "Reset title bar buttons", "タイトル バーのボタンをリセット" },
                { "Back to the default buttons and order", "既定のボタンと順番に戻します" },
                { "The buttons a PiP's title bar shows when you point at it, in your order. Previous and Next window switch what the PiP shows, and Bigger and Smaller step through the sizes. More options always stays, so the full menu is never out of reach. On a narrow PiP, buttons on the left make room first.", "PiP にポインターを合わせたときにタイトル バーに表示されるボタンです (並びは自分で決めた順)。「前のウィンドウ」と「次のウィンドウ」は PiP の表示内容を切り替え、「大きく」と「小さく」はサイズを順に切り替えます。「その他のオプション」は常に表示されるので、すべてのメニューにいつでもアクセスできます。幅の狭い PiP では、左側のボタンから順に省かれます。" },
