                { "The download was damaged (its fingerprint doesn't match). Please try again.", "ダウンロードしたファイルが壊れています (指紋が一致しません)。もう一度お試しください。" },
                { "Show controls on other apps' PiPs", "他のアプリの PiP にコントロールを表示" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "他のアプリの PiP にポインターを合わせると、その上に PiP Studio のタイトル バーが表示されます。ドラッグで PiP を移動、スクロールで音量を変更でき、選んだタイトル バーのボタンも使えます。" },
                { "Controls on other apps' PiPs", "他のアプリの PiP のコントロール" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "Chrome、Firefox、Discord などのアプリの PiP ウィンドウにポインターを合わせると、その上端に PiP Studio のタイトル バーが表示されます。バーをドラッグして PiP を移動、スクロールして音量を変更、最小化でき、自分の PiP のタイトル バーと同じボタン (アプリを表示、シアター モード、大きく、小さく、次の隅、閉じるなど) も使えます。PiP のその他の部分はいつもどおり動作します。" },
                { "Show {0}", "{0} を表示" },
