                { "Your video", "あなたの動画" },
                { "Remove", "削除" },
                { "Remove all", "すべて削除" },
                { "Marked as PiPs", "PiP として指定したウィンドウ" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "PiP として扱うように指定したウィンドウです。削除すると通常のウィンドウに戻り、常に手前に表示されなくなります。" },
                { "Treat this window as a PiP?", "このウィンドウを PiP として扱いますか?" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "PiP Studio はこのウィンドウを他のアプリのピクチャー イン ピクチャー ウィンドウと同じように扱います:" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  「実行中の PiP」に移り、PiP の定位置にスナップします" },
                { "•  It stays on top of your other windows once you move or steer it", "•  移動したり操作したりすると、他のウィンドウより手前に表示されます" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  PiP のショートカットとコントローラーで移動、サイズ変更、フェード、終了ができます" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "これは {0} の同じ種類のすべてのウィンドウに今後も適用されます。「実行中の PiP」>「PiP として指定したウィンドウ」でいつでも元に戻せます。その際、常に手前に表示されなくなります。" },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "これはこのウィンドウが閉じるまで、このウィンドウにのみ適用されます。「実行中の PiP」>「PiP として指定したウィンドウ」でいつでも元に戻せます。その際、常に手前に表示されなくなります。" },
                { "Remove every mark?", "すべての指定を削除しますか?" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "「PiP として扱う」に指定したすべてのウィンドウが通常のウィンドウに戻り、常に手前に表示されなくなります。" },
                { "Every window like this from {0}", "{0} の同じ種類のすべてのウィンドウ" },
                { "{0} · this window only, until it closes", "{0} · このウィンドウのみ (閉じるまで)" },
                { "Phone companion", "スマホ コンパニオン" },
                { "Control PiP Studio from your phone", "スマホから PiP Studio を操作" },
                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "自宅の Wi-Fi 経由で、スマホのブラウザーから PiP と各アプリの音量を操作できます。プライベート ネットワークでの PiP Studio の許可を Windows に求められる場合があります。" },
                { "Pair a phone", "スマホをペアリング" },
                { "Turn on the switch above first", "まず上のスイッチをオンにしてください" },
                { "This PC isn't on a network right now", "この PC は現在ネットワークに接続されていません" },
                { "Your phone opens {0}", "スマホで {0} が開きます" },
                { "Not used since PiP Studio started", "PiP Studio の起動後は未使用" },
                { "Last used {0}", "最終使用: {0}" },
                { "Remove {0}?", "{0} を削除しますか?" },
                { "It stops working right away. You can pair it again any time.", "すぐに使えなくなります。いつでも再びペアリングできます。" },
                { "No network", "ネットワークがありません" },
                { "PiP Studio can't find this PC's address on your local network. Connect to Wi-Fi or Ethernet and try again.", "ローカル ネットワーク上でこの PC のアドレスが見つかりません。Wi-Fi か有線 LAN に接続して、もう一度お試しください。" },
                { "Paired with {0}. You can close this.", "{0} とペアリングしました。これは閉じてかまいません。" },
                { "Couldn't open a network port. Another app may be using it.", "ネットワーク ポートを開けませんでした。別のアプリが使用している可能性があります。" },
                { "Or open {0} on your phone", "またはスマホで {0} を開いてください" },
                { "Waiting for your phone…", "スマホを待っています…" },
                { "That PIN doesn't match. Check the PIN on your phone.", "PIN が一致しません。スマホの PIN を確認してください。" },
                { "Too many wrong PINs. Start pairing again on your phone.", "PIN の誤りが多すぎます。スマホでペアリングをやり直してください。" },
                { "No phone is showing a PIN yet. Open the page on your phone and tap Pair.", "まだ PIN を表示しているスマホはありません。スマホでページを開いて「ペアリング」をタップしてください。" },
                { "Your phone is showing a PIN. Type it here.", "スマホに PIN が表示されています。ここに入力してください。" },
                { "1. Scan this code with your phone's camera (it needs to be on the same Wi-Fi as this PC) and tap Pair.", "1. スマホのカメラでこのコードを読み取り (この PC と同じ Wi-Fi に接続している必要があります)、「ペアリング」をタップします。" },
                { "2. Your phone shows a 6-digit PIN. Type it below.", "2. スマホに 6 桁の PIN が表示されます。下に入力してください。" },
                { "Pair", "ペアリング" },
                { "PiP Studio closed unexpectedly", "PiP Studio が予期せず終了しました" },
                { "Click to send a crash report, so it can be fixed.", "クリックするとクラッシュ レポートを送信して、修正に役立てられます。" },
                { "Sending this report helps get it fixed. It opens a new issue on GitHub in your browser with this already filled in, so you can check it, add what you were doing, and send it yourself. Your Windows user name and PC name are left out.", "このレポートを送ると修正に役立ちます。内容が入力済みの新しい Issue がブラウザーで GitHub に開くので、確認して何をしていたかを書き足し、自分で送信できます。Windows のユーザー名と PC 名は含まれません。" },
                { "Send report", "レポートを送信" },
                { "Copy report", "レポートをコピー" },
                { "Report a problem", "問題を報告" },
                { "Opens a bug report on GitHub with your PiP Studio and Windows versions and recent errors filled in", "PiP Studio と Windows のバージョン、最近のエラーが入力済みのバグ報告を GitHub で開きます" },
                { "Report", "報告" },
                { "Copied", "コピーしました" },
                { "Controller controls on · The game runs as admin, so it still gets the controller", "コントローラー操作オン · ゲームが管理者として実行されているため、コントローラーの入力はゲームにも届きます" },
                { "The game runs as administrator", "ゲームが管理者として実行されています" },
                { "So it keeps getting your controller. Click to restart PiP Studio as administrator, which fixes that.", "そのため、コントローラーの入力がゲームにも届きます。クリックして PiP Studio を管理者として再起動すると解決します。" },
                { "Always start as administrator", "常に管理者として起動" },
                { "Without asking each time, also at sign-in. For games and apps that run as administrator: PiP Studio can then show their windows and take their focus for controller controls. Windows asks once to set it up.", "毎回確認せず、サインイン時も同様です。管理者として実行されるゲームやアプリ向けです: PiP Studio がそのウィンドウを表示し、コントローラー操作のためにフォーカスを外せるようになります。設定時に Windows が一度だけ確認します。" },
                { "Restart as administrator now?", "今すぐ管理者として再起動しますか?" },
                { "From now on PiP Studio starts as administrator without asking, also when it starts at sign-in.", "今後、PiP Studio はサインイン時の起動も含め、確認なしで管理者として起動します。" },
                { "Phone", "スマホ" },
                { "Paired phones", "ペアリング済みのスマホ" },
                { "No phones are paired yet. Press Pair a phone above to add one.", "ペアリング済みのスマホはまだありません。上の「スマホをペアリング」を押して追加してください。" },
                { "Rename", "名前を変更" },
                { "Rename phone", "スマホの名前を変更" },
                { "The name shows here, so you can tell your phones apart.", "ここに表示される名前です。スマホを見分けるのに使えます。" },
                { "Save", "保存" },
                { "Not in the Microsoft Store version", "Microsoft Store 版にはありません" },
                { "The phone companion needs network access the Store version doesn't have. The installer and portable versions from GitHub include it.", "スマホ コンパニオンには Store 版にはないネットワーク アクセスが必要です。GitHub のインストーラー版とポータブル版には含まれています。" },
                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "スマホが PiP Studio のリモコンになります: 自宅の Wi-Fi で、スマホのブラウザーから PiP の移動やサイズ変更、表示内容の切り替え、各アプリの音量調整ができます。インターネットは経由せず、スマホと PC の間の通信はすべて暗号化されます。" },
                { "Pairing a phone", "スマホのペアリング" },
                { "Like pairing Moonlight with Sunshine: scan the code, tap Pair on your phone, and type the PIN it shows into PiP Studio. The PIN only matches when nothing sits between the two, and only paired phones can connect. Remove a phone any time.", "Moonlight と Sunshine のペアリングと同じです: コードを読み取り、スマホで「ペアリング」をタップして、表示された PIN を PiP Studio に入力します。PIN は間に何も入っていない場合にのみ一致し、接続できるのはペアリング済みのスマホだけです。スマホはいつでも削除できます。" },
                { "Type the phone's PIN", "スマホの PIN を入力" },
                { "Light, dark or OLED (black instead of grey, great on OLED screens) for PiP Studio's windows and menus, or follow Windows.", "PiP Studio のウィンドウとメニューをライト、ダーク、OLED (グレーの代わりに黒。OLED 画面に最適) にするか、Windows に合わせます。" },
                { "Light, dark or OLED black, for PiP Studio's windows and menus", "ライト、ダーク、OLED の黒 (PiP Studio のウィンドウとメニュー)" },
                { "OLED", "OLED" },
                { "Full-screen windows can't be PiPs", "全画面のウィンドウは PiP にできません" },
                { "It would stay on top of everything else on that display. Switch it to windowed mode first, then try again.", "そのディスプレイの他のすべてより手前に表示されたままになってしまいます。先にウィンドウ モードに切り替えてから、もう一度お試しください。" },
                { "Press {0} any time to put a window in picture-in-picture. Start PiP Studio again to open its window.", "いつでも {0} を押すと、ウィンドウをピクチャー イン ピクチャーにできます。もう一度 PiP Studio を起動するとウィンドウが開きます。" },
