                { "How see-through ghost mode is", "O quanto o modo fantasma é transparente" },
                { "Right-click on a PiP", "Clique direito em um PiP" },
                { "Show the menu", "Mostrar o menu" },
                { "Close it", "Fechar" },
                { "Bring its source to the front", "Trazer a origem para a frente" },
                { "Theater mode", "Modo cinema" },
                { "Middle-click closes a PiP", "Clique do meio fecha um PiP" },
                { "Hide a PiP while its window is in front", "Ocultar um PiP enquanto a janela dele está na frente" },
                { "It would only repeat what's already on screen", "Ele só repetiria o que já está na tela" },
                { "Hide PiPs while a fullscreen app is on the same display", "Ocultar PiPs enquanto um app em tela cheia está na mesma tela" },
                { "Borderless games still show PiPs unless this is on", "Jogos sem borda continuam mostrando PiPs, a menos que isto esteja ativado" },
                { "Includes borderless games", "Inclui jogos sem borda" },
                { "Keep minimized sources playing", "Manter origens minimizadas reproduzindo" },
                { "The PiP keeps moving when you minimize", "O PiP continua se movendo quando você minimiza" },
                { "Reconnect when a closed app opens again", "Reconectar quando um app fechado abrir de novo" },
                { "Window sources always run at full speed", "Origens de janela sempre rodam na velocidade máxima" },
                { "Frame rate", "Taxa de quadros" },
                { "Show the pointer", "Mostrar o ponteiro" },
                { "Use game controllers", "Usar controles de jogo" },
                { "Xbox, PlayStation, Switch and most others", "Xbox, PlayStation, Switch e a maioria dos outros" },
                { "Turn controls on when PiP Studio starts", "Ativar os controles quando o PiP Studio iniciar" },
                { "Release the game's focus while controls are on", "Tirar o foco do jogo enquanto os controles estão ativados" },
                { "The game ignores the controller while you move the PiP, and gets focus back afterwards", "O jogo ignora o controle enquanto você move o PiP e recebe o foco de volta depois" },
                { "The game ignores the controller meanwhile", "O jogo ignora o controle enquanto isso" },
                { "Show button hints on the PiP", "Mostrar dicas de botões no PiP" },
                { "Controller-friendly mode", "Modo para controle" },
                { "Bigger layout and button hints", "Layout maior e dicas de botões" },
                { "Bigger layout, a focus ring and button hints, so you can use this window with a controller. Pressing a key on the keyboard switches back.", "Um layout maior, um anel de foco e dicas de botões, para usar esta janela com um controle. Pressionar uma tecla do teclado volta ao normal." },
                { "When I use a controller", "Quando eu uso um controle" },
                { "Always", "Sempre" },
                { "Off", "Desativado" },
                { "Fade controller hints when idle", "Esmaecer as dicas do controle quando ocioso" },
                { "Hints fade after a few seconds", "As dicas esmaecem depois de alguns segundos" },
                { "The PiP's name and button hints fade after a few seconds without input. Any button brings them back. Less for Windows to draw over your game.", "O nome do PiP e as dicas de botões esmaecem depois de alguns segundos sem uso. Qualquer botão as traz de volta. Menos coisa para o Windows desenhar sobre o seu jogo." },
                { "Controller options", "Opções do controle" },
                { "Button assignments", "Atribuição de botões" },
                { "Click, then press a button. Right-click clears it.", "Clique e pressione um botão. O clique direito limpa." },
                { "Click a binding, then press the button or combination. Right-click clears it. Trigger: press, double press or hold.", "Clique em uma atribuição e pressione o botão ou a combinação. O clique direito limpa. Acionamento: pressionar, pressionar duas vezes ou segurar." },
                { "Click, then press the button(s). Right-click to clear.", "Clique e pressione o(s) botão(ões). Clique direito para limpar." },
                { "Press once, press twice quickly, or hold", "Pressionar uma vez, pressionar duas vezes rápido ou segurar" },
                { "Press", "Pressionar" },
                { "Double press", "Pressionar duas vezes" },
                { "Hold", "Segurar" },
                { "Reset", "Redefinir" },
                { "Connect a controller", "Conecte um controle" },
                { "Press button(s)…", "Pressione o(s) botão(ões)…" },
                { "No controller connected", "Nenhum controle conectado" },
                { "No controller found", "Nenhum controle encontrado" },
                { "Connect an Xbox, PlayStation or Switch controller by USB or Bluetooth.", "Conecte um controle de Xbox, PlayStation ou Switch por USB ou Bluetooth." },
                { "Connect an Xbox, PlayStation or Switch controller to use controller controls.", "Conecte um controle de Xbox, PlayStation ou Switch para usar os controles pelo controle." },
                { "Controls are on — the PiP has an accent outline. {0} turns them off.", "Os controles estão ativados — o PiP tem um contorno na cor de destaque. {0} os desativa." },
                { "Press {0} to turn controls on.", "Pressione {0} para ativar os controles." },
                { "Controller controls", "Controles pelo controle" },
                { "Controller controls on · {0} turns them off", "Controles pelo controle ativados · {0} os desativa" },
                { "Controller controls off", "Controles pelo controle desativados" },
                { "Controller controls ({0})", "Controles pelo controle ({0})" },
                { "Xbox controller", "Controle de Xbox" },
                { "PlayStation controller", "Controle de PlayStation" },
                { "Switch controller", "Controle de Switch" },
                { "These work anywhere in Windows. Click a shortcut, then press the new keys (Backspace clears, Esc cancels). Right-click clears it. They act on the PiP you used or pointed at most recently.", "Funcionam em qualquer lugar do Windows. Clique em um atalho e pressione as novas teclas (Backspace limpa, Esc cancela). O clique direito limpa. Eles agem no PiP que você usou ou apontou por último." },
                { "Open and choose", "Abrir e escolher" },
                { "Move and size", "Mover e redimensionar" },
                { "Look and visibility", "Aparência e visibilidade" },
                { "Source and media", "Origem e mídia" },
                { "Click, then press keys. Right-click to clear.", "Clique e pressione as teclas. Clique direito para limpar." },
                { "Reset shortcuts", "Redefinir atalhos" },
                { "Puts every shortcut back to its default", "Volta cada atalho ao padrão" },
                { "Start PiP Studio when I sign in", "Iniciar o PiP Studio quando eu entrar" },
                { "It starts quietly in the tray", "Ele inicia discretamente na bandeja" },
                { "Bring back my PiPs when PiP Studio starts", "Trazer meus PiPs de volta quando o PiP Studio iniciar" },
                { "Tips and alerts from the tray icon", "Dicas e avisos do ícone da bandeja" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "Ocultar PiPs de capturas de tela, gravações e compartilhamento de tela" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "OBS, Discord, Teams e a Ferramenta de Captura não vão vê-los. Custa um pouco de desempenho, então deixe desativado a menos que você transmita ou compartilhe a tela." },
                { "Costs a little performance", "Custa um pouco de desempenho" },
                { "Keep running in the tray when I close this window", "Continuar na bandeja quando eu fechar esta janela" },
                { "Otherwise closing this window quits PiP Studio", "Senão, fechar esta janela encerra o PiP Studio" },
                { "Release memory while idle", "Liberar memória quando ocioso" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "Devolve ao Windows a memória sem uso enquanto o PiP Studio está na bandeja" },
                { "Give memory back while in the tray", "Devolver memória enquanto está na bandeja" },
                { "Running as administrator", "Executando como administrador" },
                { "PiP Studio can show windows of apps that run as administrator", "O PiP Studio pode mostrar janelas de apps executados como administrador" },
                { "Can show admin apps' windows", "Pode mostrar janelas de apps de administrador" },
                { "Restart as administrator", "Reiniciar como administrador" },
                { "Needed only to show windows of apps that run as administrator", "Só é necessário para mostrar janelas de apps executados como administrador" },
                { "Only needed for admin apps' windows", "Só é necessário para janelas de apps de administrador" },
                { "Needs administrator", "Requer administrador" },
                { "Version {0}", "Versão {0}" },
                { "Exit PiP Studio", "Sair do PiP Studio" },
                { "Settings folder", "Pasta de configurações" },
                { "Open", "Abrir" },
                { "Picture-in-picture for any window or part of the screen", "Picture-in-picture para qualquer janela ou parte da tela" },
                { "Uses Windows' own live thumbnails", "Usa as miniaturas ao vivo do próprio Windows" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "O espelhamento de janelas ao vivo usa o sistema de miniaturas do próprio Windows, então quase não gasta recursos." },
                { "Select", "Selecionar" },
                { "Back", "Voltar" },
                { "Tabs", "Abas" },
                { "Search", "Pesquisar" },
                { "Scroll", "Rolar" },
                { "Type", "Digitar" },
                { "Space", "Espaço" },
                { "Clear", "Limpar" },
                { "Done", "Concluído" },
                { "Snap spots", "Posições de encaixe" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "Quando você solta um PiP, ele desliza para a posição mais próxima: os 4 cantos, mais o meio de cada borda com 8 posições ativadas. As setas e o direcional usam as mesmas posições." },
                { "How far a PiP sits from the edges of the screen.", "A que distância das bordas da tela um PiP fica." },
                { "Where new PiPs open", "Onde os novos PiPs abrem" },
                { "A new PiP pops up in the corner you pick here.", "Um novo PiP aparece no canto que você escolher aqui." },
                { "Size of new PiPs", "Tamanho dos novos PiPs" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "Um PiP pode mostrar seus controles, esmaecer, não fazer nada ou sair do caminho quando o ponteiro chega nele. Quando ele sai do caminho, segure Ctrl para pegá-lo. A opacidade ao esmaecer define o quanto ele fica transparente." },
                { "Move arrows", "Setas de movimento" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "Os botões de seta no PiP o mandam para a próxima posição ou para a próxima tela." },
                { "Ghost mode", "Modo fantasma" },
                { "Clicks go straight through the PiP to the window behind it.", "Os cliques atravessam o PiP direto para a janela atrás dele." },
                { "Follow the window you left", "Seguir a janela que você deixou" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "Quando você troca de janela, o PiP muda para a que você estava usando, então a janela que você deixou continua à vista. PiPs automáticos sempre fazem isso." },
                { "Hide while its window is in front", "Ocultar enquanto a janela dele está na frente" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "Não faz sentido mostrar uma janela duas vezes: o PiP sai de cena enquanto você está na janela dele." },
                { "Hide over full-screen apps", "Ocultar sobre apps em tela cheia" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "Os PiPs de uma tela saem do caminho enquanto um app ou jogo em tela cheia roda nela." },
                { "How see-through a new PiP is.", "O quanto um novo PiP é transparente." },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "Um PiP grande e centralizado para quando você quer assistir direito. Pressione de novo para voltar." },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "Minimizar uma origem a esconde fora da tela para que o PiP continue se movendo. Clique nela na barra de tarefas para trazê-la de volta." },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "O que um clique direito em um PiP faz: abrir o menu, fechá-lo, mostrar a janela dele, modo cinema ou nada." },
                { "More than one PiP", "Mais de um PiP" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "Ativado: cada novo PiP abre ao lado dos outros. Desativado: abrir um novo PiP troca o que já está aberto para a nova janela." },
                { "Other apps' PiPs", "PiPs de outros apps" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "Quando nenhum PiP do PiP Studio está aberto, seus atalhos e seu controle movem, redimensionam, esmaecem, silenciam e fecham as janelas picture-in-picture do Chrome, Edge, Firefox, Discord e outros apps. Elas também vão para as mesmas posições que os seus PiPs, ao abrir e quando você as solta depois de arrastar." },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "Mova, redimensione e troque PiPs com um controle de Xbox, PlayStation, Switch ou quase qualquer outro. Com Tirar o foco do jogo ativado, o jogo ignora o controle enquanto você move o PiP e recebe o foco de volta depois. As dicas mostram o que cada botão faz e esmaecem depois de alguns segundos parado." },
