                { "The buttons a PiP's title bar shows when you point at it, in your order. Previous and Next window switch what the PiP shows, and Bigger and Smaller step through the sizes. More options always stays, so the full menu is never out of reach. On a narrow PiP, buttons on the left make room first.", "Os botões que a barra de título de um PiP mostra quando você aponta para ele, na sua ordem. Janela anterior e Próxima janela mudam o que o PiP mostra, e Maior e Menor passam pelos tamanhos. Mais opções sempre fica, para que o menu completo esteja sempre ao alcance. Em um PiP estreito, os botões da esquerda abrem espaço primeiro." },
