                { "The download was damaged (its fingerprint doesn't match). Please try again.", "O download veio danificado (a impressão digital não confere). Tente de novo." },
                { "Show controls on other apps' PiPs", "Mostrar controles nos PiPs de outros apps" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "Aponte para o PiP de outro app para que a barra de título do PiP Studio apareça sobre ele: arraste-a para mover o PiP, role sobre ela para mudar o volume e use os botões da barra de título que você escolheu." },
                { "Controls on other apps' PiPs", "Controles nos PiPs de outros apps" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "Aponte para a janela PiP do Chrome, Firefox, Discord ou outro app e a barra de título do PiP Studio aparece sobre a borda superior dela. Arraste a barra para mover o PiP, role sobre ela para mudar o volume, minimize-o e use os mesmos botões da barra de título dos seus PiPs: mostrar o app, modo cinema, maior, menor, próximo canto, fechar e mais. O resto do PiP continua funcionando normalmente." },
                { "Show {0}", "Mostrar {0}" },
