                { "Remove all", "Remover todos" },
                { "Marked as PiPs", "Marcadas como PiPs" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "Janelas que você escolheu tratar como PiPs. Remover uma a torna uma janela normal de novo e ela deixa de ficar sempre visível." },
                { "Treat this window as a PiP?", "Tratar esta janela como um PiP?" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "O PiP Studio vai lidar com ela como a janela picture-in-picture de outro app:" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  Ela vai para PiPs abertos e se encaixa nas posições de PiP" },
                { "•  It stays on top of your other windows once you move or steer it", "•  Ela fica acima das suas outras janelas assim que você a move ou a controla" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  Seus atalhos de PiP e seu controle a movem, redimensionam, esmaecem e fecham" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Isso vale para todas as janelas como esta de {0}, agora e depois. Você pode desfazer a qualquer momento em PiPs abertos > Marcadas como PiPs, o que também tira ela de sempre visível." },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Isso vale só para esta janela, até ela fechar. Você pode desfazer a qualquer momento em PiPs abertos > Marcadas como PiPs, o que também tira ela de sempre visível." },
                { "Remove every mark?", "Remover todas as marcações?" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "Todas as janelas que você marcou com Tratar como PiP voltam a ser janelas normais e deixam de ficar sempre visíveis." },
                { "Every window like this from {0}", "Todas as janelas como esta de {0}" },
                { "{0} · this window only, until it closes", "{0} · só esta janela, até ela fechar" },
                { "Phone companion", "Companheiro no celular" },
                { "Control PiP Studio from your phone", "Controle o PiP Studio pelo celular" },
                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "Gerencie seus PiPs e o volume de cada app pelo navegador do celular, pelo Wi-Fi de casa. O Windows pode pedir para permitir o PiP Studio em redes privadas." },
                { "Pair a phone", "Parear um celular" },
                { "Turn on the switch above first", "Ative primeiro a opção acima" },
                { "This PC isn't on a network right now", "Este PC não está em nenhuma rede agora" },
                { "Your phone opens {0}", "Seu celular abre {0}" },
                { "Not used since PiP Studio started", "Não usado desde que o PiP Studio iniciou" },
                { "Last used {0}", "Usado pela última vez {0}" },
                { "Remove {0}?", "Remover {0}?" },
                { "It stops working right away. You can pair it again any time.", "Ele para de funcionar na hora. Você pode pareá-lo de novo quando quiser." },
                { "No network", "Sem rede" },
                { "PiP Studio can't find this PC's address on your local network. Connect to Wi-Fi or Ethernet and try again.", "O PiP Studio não encontra o endereço deste PC na sua rede local. Conecte-se ao Wi-Fi ou à Ethernet e tente de novo." },
                { "Paired with {0}. You can close this.", "Pareado com {0}. Você já pode fechar isto." },
                { "Couldn't open a network port. Another app may be using it.", "Não foi possível abrir uma porta de rede. Outro app pode estar usando." },
