                { "Your phone is showing a PIN. Type it here.", "Seu celular está mostrando um PIN. Digite-o aqui." },
                { "1. Scan this code with your phone's camera (it needs to be on the same Wi-Fi as this PC) and tap Pair.", "1. Escaneie este código com a câmera do celular (ele precisa estar no mesmo Wi-Fi que este PC) e toque em Parear." },
                { "2. Your phone shows a 6-digit PIN. Type it below.", "2. Seu celular mostra um PIN de 6 dígitos. Digite-o abaixo." },
