                { "Click to send a crash report, so it can be fixed.", "Clique para enviar um relatório de erro, para que isso possa ser corrigido." },
                { "Sending this report helps get it fixed. It opens a new issue on GitHub in your browser with this already filled in, so you can check it, add what you were doing, and send it yourself. Your Windows user name and PC name are left out.", "Enviar este relatório ajuda a corrigir o problema. Ele abre uma nova issue no GitHub no seu navegador com isto já preenchido, para que você confira, conte o que estava fazendo e envie você mesmo. Seu nome de usuário do Windows e o nome do PC ficam de fora." },
                { "Send report", "Enviar relatório" },
                { "Copy report", "Copiar relatório" },
                { "Report a problem", "Relatar um problema" },
                { "Opens a bug report on GitHub with your PiP Studio and Windows versions and recent errors filled in", "Abre um relatório de bug no GitHub com as versões do PiP Studio e do Windows e os erros recentes já preenchidos" },
                { "Report", "Relatar" },
                { "Copied", "Copiado" },
                { "Controller controls on · The game runs as admin, so it still gets the controller", "Controles pelo controle ativados · O jogo roda como administrador, então ele ainda recebe o controle" },
                { "The game runs as administrator", "O jogo roda como administrador" },
                { "So it keeps getting your controller. Click to restart PiP Studio as administrator, which fixes that.", "Por isso ele continua recebendo o seu controle. Clique para reiniciar o PiP Studio como administrador, o que resolve isso." },
                { "Always start as administrator", "Sempre iniciar como administrador" },
                { "Without asking each time, also at sign-in. For games and apps that run as administrator: PiP Studio can then show their windows and take their focus for controller controls. Windows asks once to set it up.", "Sem perguntar toda vez, também ao entrar. Para jogos e apps que rodam como administrador: assim o PiP Studio pode mostrar as janelas deles e tirar o foco deles para os controles pelo controle. O Windows pergunta uma vez para configurar." },
                { "Restart as administrator now?", "Reiniciar como administrador agora?" },
                { "From now on PiP Studio starts as administrator without asking, also when it starts at sign-in.", "De agora em diante o PiP Studio inicia como administrador sem perguntar, também quando inicia ao entrar." },
                { "Phone", "Celular" },
                { "Paired phones", "Celulares pareados" },
                { "No phones are paired yet. Press Pair a phone above to add one.", "Nenhum celular pareado ainda. Pressione Parear um celular acima para adicionar um." },
                { "Rename", "Renomear" },
                { "Rename phone", "Renomear celular" },
                { "The name shows here, so you can tell your phones apart.", "O nome aparece aqui, para você distinguir seus celulares." },
                { "Save", "Salvar" },
                { "Not in the Microsoft Store version", "Não está na versão da Microsoft Store" },
                { "The phone companion needs network access the Store version doesn't have. The installer and portable versions from GitHub include it.", "O companheiro no celular precisa de um acesso à rede que a versão da Store não tem. As versões instalador e portátil do GitHub o incluem." },
                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "Seu celular vira um controle remoto do PiP Studio: mova e redimensione PiPs, troque o que eles mostram e ajuste o volume de cada app, pelo navegador do celular no Wi-Fi de casa. Nada passa pela internet, e tudo entre o celular e o PC é criptografado." },
                { "Pairing a phone", "Pareando um celular" },
                { "Like pairing Moonlight with Sunshine: scan the code, tap Pair on your phone, and type the PIN it shows into PiP Studio. The PIN only matches when nothing sits between the two, and only paired phones can connect. Remove a phone any time.", "Como parear o Moonlight com o Sunshine: escaneie o código, toque em Parear no celular e digite no PiP Studio o PIN que ele mostra. O PIN só confere quando não há nada entre os dois, e só celulares pareados podem se conectar. Remova um celular quando quiser." },
                { "Type the phone's PIN", "Digite o PIN do celular" },
                { "Light, dark or OLED (black instead of grey, great on OLED screens) for PiP Studio's windows and menus, or follow Windows.", "Claro, escuro ou OLED (preto em vez de cinza, ótimo em telas OLED) para as janelas e os menus do PiP Studio, ou seguir o Windows." },
                { "Light, dark or OLED black, for PiP Studio's windows and menus", "Claro, escuro ou preto OLED, para as janelas e os menus do PiP Studio" },
                { "OLED", "OLED" },
