                { "Starts on the first available window, then switches to the one you were last using, even with Follow turned off.", "Начинает с первого доступного окна, а затем переключается на окно, которым вы пользовались, даже если «Следовать» выключено." },
                { "Nothing selected", "Ничего не выбрано" },
