                { "The picture may freeze", "Изображение может зависнуть" },
                { "This app stops drawing while another window covers it. Restart it with the fix to keep it moving.", "Это приложение перестаёт отрисовываться, когда его закрывает другое окно. Перезапустите его с исправлением, чтобы оно продолжало двигаться." },
                { "Restart with the fix", "Перезапустить с исправлением" },
