                { "No desktop, Start or taskbar shortcut was found for this app.", "Ярлыки этого приложения не найдены ни на рабочем столе, ни в меню «Пуск», ни на панели задач." },
                { "Adding the fix to the shortcuts…", "Добавление исправления в ярлыки…" },
