                { "Added the fix to {0} shortcuts.", "Исправление добавлено в ярлыков: {0}." },
                { "Removed the fix from {0} shortcut.", "Исправление удалено из ярлыков: {0}." },
                { "Removed the fix from {0} shortcuts.", "Исправление удалено из ярлыков: {0}." },
                { "Restart {0}?", "Перезапустить {0}?" },
                { "Restart {0}", "Перезапустить {0}" },
                { "This closes {0} and starts it again with a setting that keeps its window drawing while other windows cover it.", "{0} будет закрыто и снова запущено с параметром, который позволяет окну отрисовываться, даже когда его закрывают другие окна." },
                { "Anything unsaved in it will be lost. It only helps Chromium-based apps (Chrome, Edge, Spotify, Discord, ...).", "Всё несохранённое будет потеряно. Помогает только приложениям на основе Chromium (Chrome, Edge, Spotify, Discord, ...)." },
                { "{0} stops drawing while other windows cover it, so its PiP can freeze. Restarting it with a fix keeps it drawing. Anything unsaved in it will be lost.", "{0} перестаёт отрисовываться, когда его закрывают другие окна, поэтому его PiP может зависнуть. Перезапуск с исправлением позволяет ему отрисовываться дальше. Всё несохранённое будет потеряно." },
                { "This app's program file can't be read (it may be running as administrator), so it can't be restarted from here.", "Не удаётся прочитать файл программы этого приложения (возможно, оно запущено от имени администратора), поэтому его нельзя перезапустить отсюда." },
