                { "When you switch sources or change a mode, the message shows below the PiP instead of over the picture", "Когда вы меняете источник или режим, сообщение появляется под PiP, а не поверх изображения" },
                { "When you switch sources or change a mode, the message shows in a small caption below the PiP instead of over the picture. Volume changes show a level bar there too.", "Когда вы меняете источник или режим, сообщение появляется в небольшой подписи под PiP, а не поверх изображения. При изменении громкости там же показывается шкала уровня." },
