                { "Keep tall or wide apps from getting too big. Applies to new PiPs, size presets, resizing and source changes (theater mode ignores them).", "Не даёт высоким или широким приложениям становиться слишком большими. Действует для новых PiP, готовых размеров, изменения размера и смены источника (режим кинотеатра их игнорирует)." },
                { "Tall or wide apps stop growing at the size you set, as a share of the screen. Applies to new PiPs, size presets, resizing and source changes. Theater mode ignores them.", "Высокие или широкие приложения перестают расти на заданном размере — доле экрана. Действует для новых PiP, готовых размеров, изменения размера и смены источника. Режим кинотеатра их игнорирует." },
