                { "Control other apps' PiP windows", "Управлять окнами PiP других приложений" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture window of Chrome, Edge, Firefox and other apps.", "Когда не открыто ни одного PiP из PiP Studio, ваши сочетания клавиш и геймпад перемещают, меняют размер, затемняют, выключают звук и закрывают окно «картинка в картинке» Chrome, Edge, Firefox и других приложений." },
                { "Steer browser and app PiPs too", "Управляет и PiP браузеров и приложений" },
                { "Snap other apps' PiPs to spots", "Привязывать PiP других приложений к позициям" },
                { "Other apps' PiP windows land on the same corners and edge spots as PiP Studio's PiPs, when they open and when you let go of them after dragging.", "Окна PiP других приложений встают в те же углы и места у краёв, что и PiP из PiP Studio, — при открытии и когда вы отпускаете их после перетаскивания." },
                { "They land on the same spots as yours", "Они встают в те же позиции, что и ваши" },
                { "Allow more than one PiP at a time", "Разрешить несколько PiP одновременно" },
                { "When off, opening a new PiP switches the one that's already open", "Если выключено, новый PiP заменяет содержимое уже открытого" },
                { "Off: a new PiP replaces the open one", "Выкл.: новый PiP заменяет открытый" },
                { "Follow the window I just left", "Следовать за окном, которое я только что покинул" },
                { "When you switch windows, the PiP switches to the one you were on", "Когда вы переключаете окна, PiP переключается на то, в котором вы были" },
                { "The PiP shows the window you just left", "PiP показывает окно, которое вы только что покинули" },
                { "Snap after moving", "Привязка после перемещения" },
                { "Glides to the nearest spot when you let go", "Скользит к ближайшей позиции, когда вы отпускаете" },
                { "Middle of each edge too", "И середина каждого края" },
                { "8 spots instead of 4 corners — also used by the arrow keys and D-pad", "8 позиций вместо 4 углов — их же используют стрелки и крестовина" },
                { "Gap from the screen edges", "Отступ от краёв экрана" },
