                { "PlayStation controller", "Геймпад PlayStation" },
                { "Switch controller", "Геймпад Switch" },
                { "These work anywhere in Windows. Click a shortcut, then press the new keys (Backspace clears, Esc cancels). Right-click clears it. They act on the PiP you used or pointed at most recently.", "Они работают везде в Windows. Щёлкните сочетание и нажмите новые клавиши (Backspace очищает, Esc отменяет). Правый щелчок очищает. Они действуют на PiP, которым вы пользовались или на который наводили последним." },
                { "Open and choose", "Открыть и выбрать" },
                { "Move and size", "Перемещение и размер" },
                { "Look and visibility", "Вид и видимость" },
                { "Source and media", "Источник и медиа" },
                { "Click, then press keys. Right-click to clear.", "Щёлкните, затем нажмите клавиши. Правый щелчок — очистить." },
                { "Reset shortcuts", "Сбросить сочетания клавиш" },
                { "Puts every shortcut back to its default", "Возвращает все сочетания клавиш к значениям по умолчанию" },
                { "Start PiP Studio when I sign in", "Запускать PiP Studio при входе в систему" },
                { "It starts quietly in the tray", "Он тихо запускается в области уведомлений" },
                { "Bring back my PiPs when PiP Studio starts", "Возвращать мои PiP при запуске PiP Studio" },
                { "Tips and alerts from the tray icon", "Советы и предупреждения из значка в области уведомлений" },
                { "Hide PiPs from screenshots, recordings and screen sharing", "Скрывать PiP со снимков экрана, записей и демонстрации экрана" },
                { "OBS, Discord, Teams and the Snipping Tool won't see them. Costs a little performance, so leave it off unless you stream or share your screen.", "OBS, Discord, Teams и «Ножницы» их не увидят. Немного снижает производительность, поэтому не включайте, если не стримите и не показываете экран." },
                { "Costs a little performance", "Немного снижает производительность" },
                { "Keep running in the tray when I close this window", "Оставаться в области уведомлений при закрытии этого окна" },
                { "Otherwise closing this window quits PiP Studio", "Иначе закрытие этого окна завершает PiP Studio" },
                { "Release memory while idle", "Освобождать память при бездействии" },
                { "Gives unused memory back to Windows while PiP Studio sits in the tray", "Возвращает Windows неиспользуемую память, пока PiP Studio находится в области уведомлений" },
                { "Give memory back while in the tray", "Освобождать память в области уведомлений" },
                { "Running as administrator", "Запущено от имени администратора" },
                { "PiP Studio can show windows of apps that run as administrator", "PiP Studio может показывать окна приложений, запущенных от имени администратора" },
                { "Can show admin apps' windows", "Может показывать окна приложений администратора" },
                { "Restart as administrator", "Перезапустить от имени администратора" },
                { "Needed only to show windows of apps that run as administrator", "Нужно только для показа окон приложений, запущенных от имени администратора" },
                { "Only needed for admin apps' windows", "Нужно только для окон приложений администратора" },
                { "Needs administrator", "Требуются права администратора" },
                { "Version {0}", "Версия {0}" },
                { "Exit PiP Studio", "Выйти из PiP Studio" },
                { "Settings folder", "Папка параметров" },
                { "Open", "Открыть" },
                { "Picture-in-picture for any window or part of the screen", "«Картинка в картинке» для любого окна или части экрана" },
                { "Uses Windows' own live thumbnails", "Использует живые миниатюры Windows" },
                { "Live window mirroring uses Windows' own thumbnail system, so it costs almost nothing to run.", "Живое отображение окон использует систему миниатюр самой Windows, поэтому почти не тратит ресурсов." },
                { "Select", "Выбрать" },
                { "Back", "Назад" },
                { "Tabs", "Вкладки" },
                { "Search", "Поиск" },
                { "Scroll", "Прокрутка" },
                { "Type", "Ввод" },
                { "Space", "Пробел" },
                { "Clear", "Очистить" },
                { "Done", "Готово" },
                { "Snap spots", "Позиции привязки" },
                { "When you let go of a PiP it glides to the nearest spot: the 4 corners, plus the middle of each edge with 8 spots on. The arrow keys and D-pad use the same spots.", "Когда вы отпускаете PiP, он скользит к ближайшей позиции: 4 угла, а с 8 позициями — ещё и середина каждого края. Стрелки и крестовина используют те же позиции." },
                { "How far a PiP sits from the edges of the screen.", "Как далеко PiP находится от краёв экрана." },
                { "Where new PiPs open", "Где открываются новые PiP" },
                { "A new PiP pops up in the corner you pick here.", "Новый PiP появляется в углу, который вы выберете здесь." },
                { "Size of new PiPs", "Размер новых PiP" },
                { "A PiP can show its controls, fade, do nothing, or slide out of the way when the pointer reaches it. When it slides aside, hold Ctrl to grab it instead. Fade-out opacity sets how see-through it gets.", "PiP может показывать свои элементы управления, затухать, ничего не делать или уходить с дороги, когда к нему подходит указатель. Когда он отъезжает, удерживайте Ctrl, чтобы взять его. Непрозрачность при затухании задаёт, насколько он становится прозрачным." },
                { "Move arrows", "Стрелки перемещения" },
                { "Arrow buttons on the PiP send it to the next spot, or across to the next display.", "Кнопки со стрелками на PiP переносят его на следующую позицию или на следующий экран." },
                { "Ghost mode", "Режим призрака" },
                { "Clicks go straight through the PiP to the window behind it.", "Щелчки проходят сквозь PiP прямо в окно за ним." },
                { "Follow the window you left", "Следовать за покинутым окном" },
                { "When you switch windows, the PiP switches to the one you were just on, so the window you left stays in view. Auto PiPs always do this.", "Когда вы переключаете окна, PiP переключается на то, в котором вы только что были, поэтому покинутое окно остаётся на виду. PiP в режиме «Авто» делают так всегда." },
                { "Hide while its window is in front", "Скрывать, пока его окно на переднем плане" },
                { "No point showing a window twice: the PiP steps away while you're in its window.", "Нет смысла показывать окно дважды: PiP отходит в сторону, пока вы в его окне." },
                { "Hide over full-screen apps", "Скрывать над полноэкранными приложениями" },
                { "PiPs on a display get out of the way while a full-screen app or game runs there.", "PiP на экране уходят с дороги, пока на нём работает полноэкранное приложение или игра." },
                { "How see-through a new PiP is.", "Насколько прозрачен новый PiP." },
                { "A big, centered PiP for when you want to watch properly. Press again to go back.", "Большой PiP по центру, когда хочется смотреть как следует. Нажмите ещё раз, чтобы вернуться." },
                { "Minimizing a source tucks it off-screen so the PiP keeps moving. Click it in the taskbar to bring it back.", "Свёрнутый источник прячется за пределами экрана, чтобы PiP продолжал двигаться. Щёлкните его на панели задач, чтобы вернуть." },
                { "What a right-click on a PiP does: open its menu, close it, show its window, theater mode, or nothing.", "Что делает щелчок правой кнопкой по PiP: открывает меню, закрывает его, показывает его окно, режим кинотеатра или ничего." },
                { "More than one PiP", "Несколько PiP" },
                { "On: each new PiP opens alongside the others. Off: opening a new PiP switches the one that's already open to the new window.", "Вкл.: каждый новый PiP открывается рядом с остальными. Выкл.: новый PiP переключает уже открытый на новое окно." },
                { "Other apps' PiPs", "PiP других приложений" },
                { "When no PiP Studio PiP is open, your shortcuts and controller move, resize, fade, mute and close the picture-in-picture windows of Chrome, Edge, Firefox, Discord and other apps. They also land on the same spots as your PiPs, when they open and when you let go after dragging them.", "Когда не открыто ни одного PiP из PiP Studio, ваши сочетания клавиш и геймпад перемещают, меняют размер, затемняют, выключают звук и закрывают окна «картинка в картинке» Chrome, Edge, Firefox, Discord и других приложений. Они также встают в те же позиции, что и ваши PiP, — при открытии и когда вы отпускаете их после перетаскивания." },
                { "Move, size and switch PiPs with an Xbox, PlayStation, Switch or most other controllers. With Release the game's focus on, the game ignores the controller while you steer the PiP and gets focus back afterwards. Hints show which button does what, and fade after a few idle seconds.", "Перемещайте, меняйте размер и переключайте PiP с геймпада Xbox, PlayStation, Switch или почти любого другого. Если «Забирать фокус у игры» включено, игра не реагирует на геймпад, пока вы управляете PiP, а затем снова получает фокус. Подсказки показывают, что делает каждая кнопка, и исчезают через несколько секунд без действий." },
                { "Shows controls", "Показывает элементы управления" },
                { "Fades to {0}%", "Затухает до {0}%" },
                { "Nothing happens", "Ничего не происходит" },
                { "Moves out of the way", "Уходит с дороги" },
                { "Glides into place", "Плавно встаёт на место" },
                { "Jumps into place", "Сразу встаёт на место" },
