                { "Press {0} any time to put a window in picture-in-picture. Click this tray icon to open PiP Studio.", "Нажмите {0} в любой момент, чтобы открыть окно в режиме «картинка в картинке». Щёлкните этот значок в области уведомлений, чтобы открыть PiP Studio." },
