                { "Fix frozen picture (restart {0})…", "Исправить зависшее изображение (перезапустить {0})…" },
                { "Previous display", "Предыдущий экран" },
                { "Next display", "Следующий экран" },
                { "Original size (1:1 pixels)", "Исходный размер (пиксели 1:1)" },
                { "Move to next display", "Переместить на следующий экран" },
                { "Snap to the middle of edges too", "Привязывать и к середине краёв" },
                { "Move out of the mouse's way", "Уходить от мыши" },
                { "Lock position & size", "Закрепить положение и размер" },
                { "Scaling", "Масштабирование" },
                { "Fit (keep shape)", "Вписать (сохранить форму)" },
                { "Fill (crop edges to fill)", "Заполнить (обрезать края)" },
                { "Media & audio", "Медиа и звук" },
                { "Play / pause", "Воспроизведение / пауза" },
                { "Next track", "Следующий трек" },
                { "Previous track", "Предыдущий трек" },
                { "Mute {0}", "Выключить звук {0}" },
                { "Duplicate this PiP", "Дублировать этот PiP" },
                { "More options", "Другие параметры" },
                { "Exit theater mode", "Выйти из режима кинотеатра" },
                { "Mute — scroll to change volume", "Без звука — прокрутите, чтобы изменить громкость" },
                { "Move left", "Влево" },
                { "Move right", "Вправо" },
                { "Move up", "Вверх" },
                { "Move down", "Вниз" },
                { "Change what this PiP shows", "Изменить, что показывает этот PiP" },
                { "Tools", "Инструменты" },
                { "PiP controls", "Управление PiP" },
                { "Unbound", "Не назначено" },
                { "Enter or double-click to confirm  ·  Esc to cancel  ·  F = everything  ·  Shape: 1 Free  2 16:9  3 4:3  4 1:1  5 9:16  (now: {0})", "Enter или двойной щелчок — подтвердить  ·  Esc — отмена  ·  F = всё  ·  Форма: 1 Свободно  2 16:9  3 4:3  4 1:1  5 9:16  (сейчас: {0})" },
                { "8 spots instead of 4 corners", "8 позиций вместо 4 углов" },
                { "Small+", "Маленький+" },
                { "Medium+", "Средний+" },
                { "Large+", "Большой+" },
                { "Largest size", "Самый большой размер" },
                { "Smallest size", "Самый маленький размер" },
                { "Eight sizes from Extra small to Extra large, set by width so a PiP keeps its shape. Bigger and Smaller step through the same sizes. Your choice is highlighted.", "Восемь размеров от «Очень маленький» до «Очень большой», заданных по ширине, чтобы PiP сохранял форму. «Больше» и «Меньше» перебирают те же размеры. Ваш выбор выделен." },
                { "Extra small", "Очень маленький" },
                { "Pick a window or a display for this PiP", "Выберите окно или экран для этого PiP" },
                { "Show in this PiP", "Показать в этом PiP" },
                { "No preview for this window", "Нет предпросмотра для этого окна" },
                { "This window has closed", "Это окно закрыто" },
                { "It opens in a floating picture-in-picture window", "Оно открывается в плавающем окне «картинка в картинке»" },
                { "No matching windows", "Нет подходящих окон" },
                { "Choose a window", "Выбрать окно" },
                { "Title bar buttons", "Кнопки заголовка" },
                { "Pick the buttons on a PiP's title bar and their order", "Выберите кнопки на заголовке PiP и их порядок" },
                { "Always shown, so the full menu is never out of reach", "Всегда видна, чтобы полное меню было под рукой" },
                { "Reset title bar buttons", "Сбросить кнопки заголовка" },
                { "Back to the default buttons and order", "Вернуть кнопки и порядок по умолчанию" },
                { "The buttons a PiP's title bar shows when you point at it, in your order. Previous and Next window switch what the PiP shows, and Bigger and Smaller step through the sizes. More options always stays, so the full menu is never out of reach. On a narrow PiP, buttons on the left make room first.", "Кнопки, которые показывает заголовок PiP при наведении, в вашем порядке. «Предыдущее окно» и «Следующее окно» меняют то, что показывает PiP, а «Больше» и «Меньше» перебирают размеры. «Другие параметры» остаётся всегда, чтобы полное меню было под рукой. На узком PiP первыми уступают место кнопки слева." },
                { "Treat as a PiP", "Считать PiP" },
                { "Not a PiP", "Не PiP" },
                { "Find other apps' PiPs automatically", "Находить PiP других приложений автоматически" },
                { "Small always-on-top windows, like video players' mini modes, count as PiPs. Mark one as Not a PiP on the Running PiPs page.", "Небольшие окна поверх всех окон, например мини-режимы видеоплееров, считаются PiP. Отметьте окно как «Не PiP» на странице «Открытые PiP»." },
                { "Windows you marked", "Отмеченные вами окна" },
                { "Forget every Treat as a PiP and Not a PiP you chose", "Забыть все «Считать PiP» и «Не PiP», которые вы выбрали" },
                { "Find other apps' PiPs", "Находить PiP других приложений" },
                { "PiP options", "Параметры PiP" },
                { "Shape", "Форма" },
                { "Black bars", "Чёрные полосы" },
                { "Snapping", "Привязка" },
                { "Match the picture", "Как у изображения" },
                { "Follow my setting", "Как в моих параметрах" },
                { "Always snap to spots", "Всегда привязывать к позициям" },
                { "Never snap", "Никогда не привязывать" },
                { "No sound from this app right now", "Сейчас нет звука из этого приложения" },
                { "Crops away the bars around the video", "Обрезает полосы вокруг видео" },
                { "Fits the window to the video so the bars disappear", "Подгоняет окно под видео, чтобы полосы исчезли" },
                { "Snapping follows Settings", "Привязка как в параметрах" },
                { "Snaps to spots", "Привязывается к позициям" },
                { "Doesn't snap", "Не привязывается" },
                { "Showing the whole picture", "Показано всё изображение" },
                { "Couldn't look at the source right now", "Сейчас не удалось посмотреть на источник" },
                { "No black bars found", "Чёрные полосы не найдены" },
                { "Black bars removed", "Чёрные полосы удалены" },
                { "Removing black bars", "Удаление чёрных полос" },
                { "Black bars left alone", "Чёрные полосы оставлены" },
                { "Updates", "Обновления" },
                { "What's new", "Что нового" },
                { "Check now", "Проверить сейчас" },
                { "Update now", "Обновить сейчас" },
                { "Check for updates automatically", "Проверять обновления автоматически" },
                { "Once a day, on GitHub. Nothing about you or your PC is sent.", "Раз в день, на GitHub. Никаких данных о вас или вашем ПК не отправляется." },
                { "Checking for updates…", "Проверка обновлений…" },
                { "You're up to date (version {0})", "У вас последняя версия ({0})" },
                { "Version {0} is available", "Доступна версия {0}" },
                { "Downloading the update… {0}%", "Загрузка обновления… {0}%" },
                { "Installing the update…", "Установка обновления…" },
                { "You have version {0}", "У вас версия {0}" },
                { "The update didn't work", "Обновление не удалось" },
                { "Update available", "Доступно обновление" },
                { "PiP Studio {0} is out. Click to update.", "Вышел PiP Studio {0}. Щёлкните, чтобы обновить." },
                { "PiP Studio was updated", "PiP Studio обновлён" },
                { "You're now on version {0}.", "Теперь у вас версия {0}." },
                { "Update to version {0}…", "Обновить до версии {0}…" },
                { "Couldn't reach GitHub. Check your internet connection and try again.", "Не удалось связаться с GitHub. Проверьте подключение к интернету и попробуйте снова." },
                { "The download was damaged (its fingerprint doesn't match). Please try again.", "Загруженный файл повреждён (контрольная сумма не совпадает). Попробуйте снова." },
                { "Show controls on other apps' PiPs", "Показывать элементы управления на PiP других приложений" },
                { "Point at another app's PiP to get PiP Studio's title bar over it: drag it to move the PiP, scroll on it to change the volume, and use the title bar buttons you picked.", "Наведите на PiP другого приложения, и над ним появится заголовок PiP Studio: перетаскивайте его, чтобы двигать PiP, прокручивайте на нём, чтобы менять громкость, и пользуйтесь выбранными кнопками заголовка." },
                { "Controls on other apps' PiPs", "Управление PiP других приложений" },
                { "Point at the PiP window of Chrome, Firefox, Discord or another app and PiP Studio's title bar appears over its top edge. Drag the bar to move the PiP, scroll on it to change the volume, minimize it, and use the same buttons as your own PiPs' title bar: show the app, theater mode, bigger, smaller, next corner, close and more. The rest of the PiP keeps working as usual.", "Наведите на окно PiP Chrome, Firefox, Discord или другого приложения, и у его верхнего края появится заголовок PiP Studio. Перетаскивайте заголовок, чтобы двигать PiP, прокручивайте на нём, чтобы менять громкость, сворачивайте его и пользуйтесь теми же кнопками, что и на заголовке ваших PiP: показать приложение, режим кинотеатра, больше, меньше, следующий угол, закрыть и другие. Остальная часть PiP работает как обычно." },
                { "Show {0}", "Показать {0}" },
                { "Options in PiP Studio", "Параметры в PiP Studio" },
                { "Minimize", "Свернуть" },
                { "Restore", "Восстановить" },
                { "Restore {0}'s PiP", "Восстановить PiP {0}" },
                { "PiP Studio's title bar appears", "Появляется заголовок PiP Studio" },
                { "Your video", "Ваше видео" },
                { "Remove", "Удалить" },
                { "Remove all", "Удалить все" },
                { "Marked as PiPs", "Отмечены как PiP" },
                { "Windows you chose to treat as PiPs. Removing one makes it a normal window again and takes it off always on top.", "Окна, которые вы решили считать PiP. Если удалить окно отсюда, оно снова станет обычным и перестанет быть поверх всех окон." },
                { "Treat this window as a PiP?", "Считать это окно PiP?" },
                { "PiP Studio will handle it like another app's picture-in-picture window:", "PiP Studio будет работать с ним как с окном «картинка в картинке» другого приложения:" },
                { "•  It moves to Running PiPs and snaps to PiP spots", "•  Оно появится в «Открытых PiP» и будет привязываться к позициям PiP" },
                { "•  It stays on top of your other windows once you move or steer it", "•  Оно будет поверх других окон, как только вы его переместите или начнёте им управлять" },
                { "•  Your PiP shortcuts and controller move, resize, fade and close it", "•  Ваши сочетания клавиш для PiP и геймпад будут перемещать его, менять размер, затемнять и закрывать" },
                { "This applies to every window like this one from {0}, now and later. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Это относится ко всем таким окнам {0}, сейчас и потом. Отменить можно в любой момент в «Открытые PiP» > «Отмечены как PiP» — тогда окно также перестанет быть поверх всех." },
                { "This applies to this window only, until it closes. You can undo it any time under Running PiPs > Marked as PiPs, which also takes it off always on top.", "Это относится только к этому окну, пока оно не закроется. Отменить можно в любой момент в «Открытые PiP» > «Отмечены как PiP» — тогда окно также перестанет быть поверх всех." },
                { "Remove every mark?", "Удалить все отметки?" },
                { "Every window you marked with Treat as a PiP goes back to being a normal window, and comes off always on top.", "Все окна, отмеченные как «Считать PiP», снова станут обычными и перестанут быть поверх всех окон." },
                { "Every window like this from {0}", "Все такие окна {0}" },
                { "{0} · this window only, until it closes", "{0} · только это окно, пока оно не закроется" },
                { "Phone companion", "Компаньон на телефоне" },
                { "Control PiP Studio from your phone", "Управляйте PiP Studio с телефона" },
                { "Manage your PiPs and every app's volume from your phone's browser, over your home Wi-Fi. Windows may ask you to allow PiP Studio on private networks.", "Управляйте PiP и громкостью каждого приложения из браузера телефона через домашний Wi-Fi. Windows может попросить разрешить PiP Studio в частных сетях." },
                { "Pair a phone", "Подключить телефон" },
                { "Turn on the switch above first", "Сначала включите переключатель выше" },
                { "This PC isn't on a network right now", "Этот ПК сейчас не подключён ни к одной сети" },
                { "Your phone opens {0}", "Ваш телефон открывает {0}" },
                { "Not used since PiP Studio started", "Не использовался с запуска PiP Studio" },
                { "Last used {0}", "Последнее использование: {0}" },
                { "Remove {0}?", "Удалить {0}?" },
                { "It stops working right away. You can pair it again any time.", "Он сразу перестанет работать. Подключить его снова можно в любой момент." },
                { "No network", "Нет сети" },
                { "PiP Studio can't find this PC's address on your local network. Connect to Wi-Fi or Ethernet and try again.", "PiP Studio не может найти адрес этого ПК в вашей локальной сети. Подключитесь к Wi-Fi или Ethernet и попробуйте снова." },
                { "Paired with {0}. You can close this.", "Подключён к {0}. Это окно можно закрыть." },
                { "Couldn't open a network port. Another app may be using it.", "Не удалось открыть сетевой порт. Возможно, его использует другое приложение." },
                { "Or open {0} on your phone", "Или откройте {0} на телефоне" },
                { "Waiting for your phone…", "Ожидание телефона…" },
                { "That PIN doesn't match. Check the PIN on your phone.", "PIN не совпадает. Проверьте PIN на телефоне." },
                { "Too many wrong PINs. Start pairing again on your phone.", "Слишком много неверных PIN. Начните подключение на телефоне заново." },
                { "No phone is showing a PIN yet. Open the page on your phone and tap Pair.", "Ни один телефон ещё не показывает PIN. Откройте страницу на телефоне и нажмите «Подключить»." },
                { "Your phone is showing a PIN. Type it here.", "Ваш телефон показывает PIN. Введите его здесь." },
                { "1. Scan this code with your phone's camera (it needs to be on the same Wi-Fi as this PC) and tap Pair.", "1. Отсканируйте этот код камерой телефона (он должен быть в той же сети Wi-Fi, что и этот ПК) и нажмите «Подключить»." },
                { "2. Your phone shows a 6-digit PIN. Type it below.", "2. Телефон покажет 6-значный PIN. Введите его ниже." },
                { "Pair", "Подключить" },
                { "PiP Studio closed unexpectedly", "PiP Studio неожиданно закрылся" },
                { "Click to send a crash report, so it can be fixed.", "Щёлкните, чтобы отправить отчёт о сбое и помочь его исправить." },
                { "Sending this report helps get it fixed. It opens a new issue on GitHub in your browser with this already filled in, so you can check it, add what you were doing, and send it yourself. Your Windows user name and PC name are left out.", "Этот отчёт помогает исправить проблему. Он открывает в браузере новую задачу на GitHub с уже заполненными данными, чтобы вы могли проверить их, добавить, что вы делали, и отправить сами. Имя пользователя Windows и имя ПК в него не попадают." },
                { "Send report", "Отправить отчёт" },
                { "Copy report", "Скопировать отчёт" },
                { "Report a problem", "Сообщить о проблеме" },
                { "Opens a bug report on GitHub with your PiP Studio and Windows versions and recent errors filled in", "Открывает отчёт об ошибке на GitHub с уже указанными версиями PiP Studio и Windows и недавними ошибками" },
                { "Report", "Сообщить" },
                { "Copied", "Скопировано" },
                { "Controller controls on · The game runs as admin, so it still gets the controller", "Управление с геймпада включено · Игра запущена от имени администратора, поэтому всё ещё получает геймпад" },
                { "The game runs as administrator", "Игра запущена от имени администратора" },
                { "So it keeps getting your controller. Click to restart PiP Studio as administrator, which fixes that.", "Поэтому она продолжает получать ваш геймпад. Щёлкните, чтобы перезапустить PiP Studio от имени администратора, — это всё исправит." },
                { "Always start as administrator", "Всегда запускать от имени администратора" },
                { "Without asking each time, also at sign-in. For games and apps that run as administrator: PiP Studio can then show their windows and take their focus for controller controls. Windows asks once to set it up.", "Без вопросов каждый раз, в том числе при входе в систему. Для игр и приложений, запущенных от имени администратора: так PiP Studio сможет показывать их окна и забирать у них фокус для управления с геймпада. Windows спросит один раз при настройке." },
                { "Restart as administrator now?", "Перезапустить от имени администратора сейчас?" },
                { "From now on PiP Studio starts as administrator without asking, also when it starts at sign-in.", "Теперь PiP Studio будет запускаться от имени администратора без вопросов, в том числе при входе в систему." },
                { "Phone", "Телефон" },
                { "Paired phones", "Подключённые телефоны" },
                { "No phones are paired yet. Press Pair a phone above to add one.", "Подключённых телефонов пока нет. Нажмите «Подключить телефон» выше, чтобы добавить." },
                { "Rename", "Переименовать" },
                { "Rename phone", "Переименовать телефон" },
                { "The name shows here, so you can tell your phones apart.", "Имя показывается здесь, чтобы различать ваши телефоны." },
                { "Save", "Сохранить" },
                { "Not in the Microsoft Store version", "Нет в версии из Microsoft Store" },
                { "The phone companion needs network access the Store version doesn't have. The installer and portable versions from GitHub include it.", "Компаньону на телефоне нужен доступ к сети, которого нет у версии из Store. Он есть в версиях с установщиком и в портативной версии с GitHub." },
                { "Your phone becomes a remote for PiP Studio: move and resize PiPs, switch what they show, and set the volume of every app, from the phone's browser on your home Wi-Fi. Nothing goes over the internet, and everything between phone and PC is encrypted.", "Телефон превращается в пульт для PiP Studio: перемещайте PiP и меняйте их размер, переключайте, что они показывают, и регулируйте громкость каждого приложения из браузера телефона в домашнем Wi-Fi. Ничего не идёт через интернет, а всё, что передаётся между телефоном и ПК, зашифровано." },
                { "Pairing a phone", "Подключение телефона" },
                { "Like pairing Moonlight with Sunshine: scan the code, tap Pair on your phone, and type the PIN it shows into PiP Studio. The PIN only matches when nothing sits between the two, and only paired phones can connect. Remove a phone any time.", "Как подключение Moonlight к Sunshine: отсканируйте код, нажмите «Подключить» на телефоне и введите в PiP Studio PIN, который он покажет. PIN совпадёт, только если между устройствами никого нет, и подключаться могут только подключённые телефоны. Удалить телефон можно в любой момент." },
                { "Type the phone's PIN", "Введите PIN телефона" },
                { "Light, dark or OLED (black instead of grey, great on OLED screens) for PiP Studio's windows and menus, or follow Windows.", "Светлая, тёмная или OLED (чёрный вместо серого, отлично для OLED-экранов) для окон и меню PiP Studio, или как в Windows." },
                { "Light, dark or OLED black, for PiP Studio's windows and menus", "Светлая, тёмная или чёрная OLED, для окон и меню PiP Studio" },
                { "OLED", "OLED" },
                { "Full-screen windows can't be PiPs", "Полноэкранные окна не могут быть PiP" },
                { "It would stay on top of everything else on that display. Switch it to windowed mode first, then try again.", "Оно оставалось бы поверх всего остального на этом экране. Сначала переключите его в оконный режим и попробуйте снова." },
                { "Press {0} any time to put a window in picture-in-picture. Start PiP Studio again to open its window.", "Нажмите {0} в любой момент, чтобы открыть окно в режиме «картинка в картинке». Запустите PiP Studio снова, чтобы открыть его окно." },
                { "Your shortcuts and controller keep working. Start PiP Studio again to open this window.", "Сочетания клавиш и геймпад продолжают работать. Запустите PiP Studio снова, чтобы открыть это окно." },
                { "Utility PiP", "Служебный PiP" },
                { "Utility PiPs", "Служебные PiP" },
                { "System monitor", "Монитор системы" },
                { "Clock", "Часы" },
                { "Now playing", "Сейчас играет" },
                { "Main volume", "Общая громкость" },
                { "No app is making sound right now", "Сейчас ни одно приложение не издаёт звук" },
                { "CPU", "ЦП" },
                { "GPU", "ГП" },
                { "Memory", "Память" },
